// 句動詞データ（自動生成）
const PV_DATA = [{"no": 1, "stage": 1, "verb": "drop by", "meaning": "ちょっと立ち寄る", "def": "to visit someone briefly, usually without planning", "ex1": "I was in the neighborhood, so I dropped by your place — but nobody was home.", "ja1": "近くまで来たからちょっと寄ったんだけど、誰もいなかったよ。", "ex2": "Please drop by my desk if you have any questions about the proposal.", "ja2": "提案について質問があれば私の席に立ち寄ってください。", "note": "", "nuance": "visitより気軽で短時間。stop by(通り道での立ち寄り)とほぼ同義だが、drop byの方がより口語的でくだけた響き。", "groups": ["visit_casually"], "etymology": "drop（ポトリと落ちる）＋by（そばを）\n→ 通り道のそばにちょっと寄り道するイメージ\n→ そこから「ちょっと立ち寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 2, "stage": 1, "verb": "come over", "meaning": "（自分のところへ）来る、遊びに来る", "def": "to come to where the speaker is, especially to a home", "ex1": "My internet's down. Mind if I come over to use yours?", "ja1": "うちのネットが落ちてるんだけど、ちょっとお邪魔していい？", "ex2": "Could you come over to our office next Tuesday for the kickoff?", "ja2": "キックオフのため来週火曜に弊社オフィスへお越しいただけますか。", "note": "", "nuance": "visitよりカジュアルで、気軽な訪問を表す。go over(相手の場所へ「行く」)との違いは、come overが話し手側の場所を基点にしている点。", "groups": [], "etymology": "come（来る）＋over（越えて）\n→ 離れた場所から境界を越えてこちら側へ来るイメージ\n→ そこから「（自分のところへ）来る、遊びに来る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 3, "stage": 1, "verb": "look for", "meaning": "探す", "def": "to try to find something or someone", "ex1": "I've been looking for my glasses for ten minutes — and they're on my head.", "ja1": "10分もメガネを探してたら、頭の上に乗ってた。", "ex2": "We are looking for a vendor who can support 24-hour operations.", "ja2": "24時間対応できるベンダーを探しています。", "note": "", "nuance": "search for(改まった探索)より口語的で日常的。findは「見つかった結果」を表すのに対し、look forは「探す行為・過程」に焦点がある。", "groups": [], "etymology": "look（見る）＋for（求めて）\n→ 欲しい物に向かって手を伸ばすイメージ\n→ そこから「探す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 4, "stage": 1, "verb": "get on", "meaning": "（バス・電車・飛行機に）乗る", "def": "to board a bus, train, plane, or other large vehicle", "ex1": "She got on the wrong bus and ended up two towns away.", "ja1": "彼女は間違ったバスに乗って、隣の隣の町まで行ってしまった。", "ex2": "The team got on the shuttle bus to the client's site.", "ja2": "チームは客先へ向かうシャトルバスに乗った。", "note": "大型の乗り物に使う", "nuance": "get intoが車のように「中に入り込む」小さい乗り物用なのに対し、get onはバス・電車・飛行機など「上に乗る」大きい乗り物に使う。boardよりくだけた言い方。", "groups": ["board_vehicle"], "etymology": "get（得る・～になる）＋on（接触・継続）\n→ 乗り物の上に乗っかるイメージ\n→ そこから「（バス・電車・飛行機に）乗る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(5,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 5, "stage": 1, "verb": "get in", "meaning": "（車などに）乗り込む、中に入る", "def": "to enter a car or small vehicle; to enter a place", "ex1": "The dog wouldn't get in the car no matter how much we coaxed it.", "ja1": "どんなになだめても、犬は車に乗ろうとしなかった。", "ex2": "Please get in the taxi first; I'll bring the documents.", "ja2": "先にタクシーに乗ってください、書類は私が持っていきます。", "note": "車・タクシーなど小型の乗り物", "nuance": "車やタクシーなど小さい乗り物に「入り込む」イメージ。get onとの対比で覚える。", "groups": ["vehicle_actions"], "etymology": "get（得る・～になる）＋in（中へ）\n→ 外から内側の空間へ入り込むイメージ\n→ そこから「（車などに）乗り込む、中に入る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 6, "stage": 1, "verb": "get off", "meaning": "（バス・電車などから）降りる", "def": "to leave a bus, train, plane, or other large vehicle", "ex1": "I got off one stop too early and had to walk the rest of the way.", "ja1": "1駅早く降りてしまって、残りは歩く羽目になった。", "ex2": "We got off the train one stop early to reach the venue on foot.", "ja2": "会場まで歩くため、一駅手前で電車を降りた。", "note": "", "nuance": "get onの反対。大きい乗り物から降りる動作。", "groups": ["vehicle_actions"], "etymology": "get（得る・～になる）＋off（離れて）\n→ 乗っていた場所から離れて下に降りるイメージ\n→ そこから「（バス・電車などから）降りる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(5,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 7, "stage": 1, "verb": "clean up", "meaning": "きれいに片づける、掃除する", "def": "to make a place clean and tidy", "ex1": "My roommate finally cleaned up his side of the room after three weeks.", "ja1": "ルームメイトは3週間ぶりにやっと自分側の部屋を片づけた。", "ex2": "Let's clean up the meeting room before the client arrives.", "ja2": "顧客が到着する前に会議室を片づけよう。", "note": "", "nuance": "tidy up(整理整頓、軽めの片づけ)より徹底的で、汚れも含めてきれいにする。clearが「取り除いて空にする」に対し、clean upは「元の清潔な状態に戻す」イメージ。", "groups": ["tidy_up"], "etymology": "clean（きれいにする）＋up（上へ）\n→ 最後まできっちり仕上げる・整えるイメージ\n→ そこから「きれいに片づける、掃除する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M40 16 L24 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M24 44 L16 50 M24 44 L20 50 M24 44 L28 50\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 8, "stage": 1, "verb": "look up", "meaning": "（辞書などで）調べる", "def": "to search for information in a dictionary, book, or online", "ex1": "I looked up the word so many times I finally just memorized it.", "ja1": "何度も辞書で調べているうちに、とうとう覚えてしまった。", "ex2": "I looked up the specification in the product manual.", "ja2": "製品マニュアルで仕様を調べた。", "note": "", "nuance": "checkは「確認する」全般を指すのに対し、look upは辞書・データベースなど「特定の情報源」から調べる時に使う。searchよりも「答えが載っている場所を見る」というニュアンスが強い。", "groups": [], "etymology": "look（見る）＋up（上へ）\n→ 知りたい情報を掘り起こして表に持ってくるイメージ\n→ そこから「（辞書などで）調べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 9, "stage": 1, "verb": "put on", "meaning": "身につける、着る", "def": "to place clothing or accessories on your body", "ex1": "It was freezing, so I put on every jacket I owned.", "ja1": "凍えるほど寒かったので、持っている上着を全部着込んだ。", "ex2": "He put on a tie before the client presentation.", "ja2": "顧客プレゼンの前に彼はネクタイを締めた。", "note": "動作を表す（着ている状態は wear）", "nuance": "身につける動作そのもの。着ている状態はwearと区別。", "groups": ["clothing_wear"], "etymology": "put（置く）＋on（接触・継続）\n→ 体に密着させて身につけるイメージ\n→ そこから「身につける、着る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 10, "stage": 1, "verb": "take off", "meaning": "脱ぐ", "def": "to remove clothing or something you are wearing", "ex1": "He took off his shoes at the door without even being asked.", "ja1": "言われもしないのに、彼は玄関で靴を脱いだ。", "ex2": "Please take off your badge before leaving the secure area.", "ja2": "セキュリティエリアを出る前にバッジを外してください。", "note": "Stage 6 の take off*2（離陸する）と区別", "nuance": "remove(取り外す全般)より日常的で、特に衣類や靴に使う。put onの反対で、脱ぐ動作そのものに焦点がある。", "groups": ["clothing_wear"], "etymology": "take（取る）＋off（離れて）\n→ 身につけていた物を体から離すイメージ\n→ そこから「脱ぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 11, "stage": 1, "verb": "come back", "meaning": "戻ってくる、帰ってくる", "def": "to return to a place", "ex1": "I left my umbrella at the café and had to come back for it.", "ja1": "傘をカフェに忘れて、取りに戻らないといけなかった。", "ex2": "She came back from the site visit with several issues.", "ja2": "彼女は現地訪問から戻り、いくつかの課題を持ち帰った。", "note": "", "nuance": "returnよりくだけた言い方。go backが「（自分が）離れた場所へ戻る」のに対し、come backは「話し手のいる場所（元の場所）へ戻ってくる」視点の違いがある。", "groups": ["return"], "etymology": "come（来る）＋back（後ろ・元へ）\n→ 離れていた場所や状態へ戻っていくイメージ\n→ そこから「戻ってくる、帰ってくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 12, "stage": 1, "verb": "go back", "meaning": "戻る、帰る（自分から離れた元の場所へ）", "def": "to return to a place you were before", "ex1": "Halfway to the station, I realized I forgot my ticket and had to go back home.", "ja1": "駅まで半分来たところで切符を忘れたことに気づき、家に戻った。", "ex2": "Let's go back to the previous slide.", "ja2": "前のスライドに戻りましょう。", "note": "話し手から離れる方向が go back", "nuance": "come backの反対の視点。go backは自分を基点に「元いた場所へ戻る」動きを表し、話し手が今いる場所とは無関係。", "groups": ["return"], "etymology": "go（行く）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「戻る、帰る（自分から離れた元の場所へ）」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 13, "stage": 1, "verb": "come up with", "meaning": "（案・解決策を）思いつく", "def": "to think of an idea, plan, or solution", "ex1": "We brainstormed for an hour before someone finally came up with a decent name.", "ja1": "1時間ブレストして、ようやく誰かがまともな名前を思いついた。", "ex2": "The team came up with three options for the migration plan.", "ja2": "チームは移行計画の案を3つ考え出した。", "note": "", "nuance": "think of(単に思いつく)より、努力の末にアイデアや解決策を「作り出す」ニュアンスが強い。suggestよりカジュアル。", "groups": [], "etymology": "come（来る）＋up（上へ）＋with（一緒に）\n→ 上向き・完了や増加のイメージ\n→ そこから「（案・解決策を）思いつく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 14, "stage": 1, "verb": "hang up", "meaning": "電話を切る", "def": "to end a phone call", "ex1": "She got so angry mid-call that she just hung up on me.", "ja1": "電話の途中で彼女は怒って、そのまま切ってしまった。", "ex2": "Don't hang up until you have confirmed the next meeting date.", "ja2": "次回の日程を確認するまで電話を切らないでください。", "note": "", "nuance": "hang up onは「（怒って）電話を一方的に切る」という強いニュアンスを含むことがある。end the callより口語的。", "groups": [], "etymology": "hang（掛ける）＋up（上へ）\n→ それ以上は続けられない限界まで達し、そこで打ち切るイメージ\n→ そこから「電話を切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 15, "stage": 1, "verb": "go for", "meaning": "（〜を）選ぶ、〜にする", "def": "to choose or decide on something", "ex1": "Between the two options, I'll go for the cheaper one every time.", "ja1": "その2つなら、私はいつも安い方を選ぶ。", "ex2": "The client went for the cloud-based solution.", "ja2": "顧客はクラウド型のソリューションを選んだ。", "note": "", "nuance": "chooseより口語的でカジュアル。pickが「単に選ぶ」のに対し、go forは「積極的にそれを選ぶ、狙う」という意欲的なニュアンスがある。", "groups": ["choose"], "etymology": "go（行く）＋for（求めて）\n→ 数ある中から欲しい物に狙いを定めるイメージ\n→ そこから「（〜を）選ぶ、〜にする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 16, "stage": 1, "verb": "run away", "meaning": "逃げる、家出する", "def": "to escape from a place or situation", "ex1": "The cat ran away the moment the vacuum cleaner turned on.", "ja1": "掃除機の電源が入った瞬間、猫は逃げていった。", "ex2": "We shouldn't run away from the risks in this proposal.", "ja2": "この提案のリスクから目を背けるべきではない。", "note": "", "nuance": "escapeより日常的な言い方。flee(緊急の逃走)ほど深刻ではなく、家出や単純に逃げる場面で幅広く使う。", "groups": ["escape_run_away"], "etymology": "run（走る）＋away（遠くへ）\n→ 危険や束縛からその場を離れて遠ざかるイメージ\n→ そこから「逃げる、家出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 17, "stage": 1, "verb": "move in", "meaning": "引っ越してくる、入居する", "def": "to start living in a new home", "ex1": "They just moved in next door, and their moving truck blocked our driveway all day.", "ja1": "隣に引っ越してきたばかりで、引っ越しトラックが一日中うちの車道を塞いでいた。", "ex2": "The new team moves in to the fourth floor next Monday.", "ja2": "新チームは来週月曜に4階へ移ってくる。", "note": "", "nuance": "move outの反対。settle in(新しい環境に馴染む、住み始めた後の過程)より、引っ越してくる動作そのものに焦点がある。", "groups": ["move_house"], "etymology": "move（動く）＋in（中へ）\n→ 新しい場所の内側に入って根を下ろすイメージ\n→ そこから「引っ越してくる、入居する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 18, "stage": 1, "verb": "move out", "meaning": "引っ越して出ていく、退去する", "def": "to stop living in a place and leave it", "ex1": "The tenants moved out overnight, leaving the fridge completely empty.", "ja1": "住人たちは一晩で退去して、冷蔵庫は空っぽのままだった。", "ex2": "The department moved out of the old building last quarter.", "ja2": "その部署は前四半期に旧ビルから移転した。", "note": "", "nuance": "move inの反対。evict(強制退去させる)とは違い、自発的に出ていくニュアンス。", "groups": ["move_house"], "etymology": "move（動く）＋out（外へ）\n→ 内側の空間から外の世界へ出ていくイメージ\n→ そこから「引っ越して出ていく、退去する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 19, "stage": 1, "verb": "show up", "meaning": "現れる、姿を見せる", "def": "to arrive or appear, especially at an event", "ex1": "He promised to show up at seven, and at nine we were still waiting.", "ja1": "7時に来ると約束したのに、9時になってもまだ待っていた。", "ex2": "Two of the attendees didn't show up for the review meeting.", "ja2": "レビュー会議に出席者2名が現れなかった。", "note": "", "nuance": "appear(単に現れる)より、「来るはずの人・物が実際に姿を見せる」という期待と結果のニュアンスを含む。", "groups": ["appear"], "etymology": "show（見せる）＋up（上へ）\n→ 知りたい情報を掘り起こして表に持ってくるイメージ\n→ そこから「現れる、姿を見せる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 20, "stage": 1, "verb": "turn up", "meaning": "ひょっこり現れる、（なくし物が）出てくる", "def": "to appear, often unexpectedly; to be found by chance", "ex1": "I thought I'd lost my wallet forever, but it turned up under the couch.", "ja1": "財布はもう二度と出てこないと思ったら、ソファの下から出てきた。", "ex2": "The missing invoice turned up in the shared folder.", "ja2": "見つからなかった請求書が共有フォルダから出てきた。", "note": "show up より「予想外」の含みが強い", "nuance": "showは「見せる」意図が入るのに対し、turn upは「予期せず・偶然出てくる」ニュアンスが強い。show upより偶然性が高い。", "groups": ["appear"], "etymology": "turn（向きを変える）＋up（上へ）\n→ 知りたい情報を掘り起こして表に持ってくるイメージ\n→ そこから「ひょっこり現れる、（なくし物が）出てくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 21, "stage": 1, "verb": "come up", "meaning": "（話題・用事が）持ち上がる、起こる", "def": "to arise or be mentioned unexpectedly", "ex1": "Right before the deadline, a huge problem came up that nobody had planned for.", "ja1": "締め切り直前になって、誰も予想していなかった大問題が持ち上がった。", "ex2": "A scheduling conflict came up, so we need to reschedule.", "ja2": "予定が重なったので日程を再調整する必要があります。", "note": "Stage 2 の come up*2 と区別", "nuance": "happen(単に起こる)より、「議題や問題として持ち上がる」場面で使われることが多い。ariseよりくだけた言い方。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋up（上へ）\n→ 知りたい情報を掘り起こして表に持ってくるイメージ\n→ そこから「（話題・用事が）持ち上がる、起こる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 22, "stage": 1, "verb": "put off", "meaning": "延期する、先延ばしにする", "def": "to postpone something to a later time", "ex1": "We kept putting off the dentist appointment until the toothache got unbearable.", "ja1": "歯医者の予約をずっと先延ばしにしていたら、歯の痛みが我慢できなくなった。", "ex2": "The client asked us to put off the release until April.", "ja2": "顧客からリリースを4月まで延期するよう依頼された。", "note": "", "nuance": "postpone(改まった延期)より口語的。delayが「遅らせる」全般を指すのに対し、put offは「意図的に先延ばしにする」ニュアンスが強い。", "groups": ["postpone"], "etymology": "put（置く）＋off（離れて）\n→ 予定していた時から距離を置いて先に離すイメージ\n→ そこから「延期する、先延ばしにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 23, "stage": 1, "verb": "come in", "meaning": "入ってくる", "def": "to enter a room or building", "ex1": "She knocked twice, then just let herself come in without waiting for an answer.", "ja1": "彼女は2回ノックすると、返事も待たずに勝手に入ってきた。", "ex2": "New requirements came in after the design was fixed.", "ja2": "設計確定後に新しい要件が入ってきた。", "note": "", "nuance": "enterより口語的で日常会話向き。come inは「中に入ってくる」動作、get inは「（乗り物などに）乗り込む」というニュアンスの違いがある。", "groups": ["enter_various"], "etymology": "come（来る）＋in（中へ）\n→ 外から内側へ入ってくるイメージ\n→ そこから「入ってくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-12,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 24, "stage": 1, "verb": "stay in", "meaning": "家にいる、外出しない", "def": "to remain at home instead of going out", "ex1": "It rained all weekend, so we just stayed in and watched movies.", "ja1": "週末はずっと雨だったので、家にこもって映画を見ていた。", "ex2": "I stayed in over the weekend to prepare for Monday's presentation.", "ja2": "月曜のプレゼン準備のため週末は家にこもった。", "note": "", "nuance": "remain(単に留まる)より、「外出せず家の中で過ごす」という具体的な状況を表す。stay home（家にいる）とほぼ同義。", "groups": ["home_or_out"], "etymology": "stay（とどまる）＋in（中へ）\n→ 外に出ず、内側の空間にとどまるイメージ\n→ そこから「家にいる、外出しない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-12,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 25, "stage": 1, "verb": "take on", "meaning": "（仕事・責任を）引き受ける", "def": "to accept work or responsibility", "ex1": "Nobody else wanted the project, so I ended up taking it on myself.", "ja1": "誰もそのプロジェクトをやりたがらなかったので、結局自分で引き受けた。", "ex2": "Our team took on the maintenance work from April.", "ja2": "4月から当チームが保守業務を引き受けた。", "note": "", "nuance": "accept(単に受け入れる)より、責任や仕事を「自分の負担として引き受ける」という積極性を含む。undertakeよりカジュアル。", "groups": ["undertake_continue_work"], "etymology": "take（取る）＋on（接触・継続）\n→ 仕事や責任を自分の上に乗せて背負うイメージ\n→ そこから「（仕事・責任を）引き受ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 26, "stage": 1, "verb": "move on", "meaning": "次に進む、気持ちを切り替える", "def": "to leave one thing and start the next", "ex1": "It took months, but she finally moved on after the breakup.", "ja1": "何ヶ月もかかったが、彼女は失恋をようやく乗り越えて前に進んだ。", "ex2": "Let's move on to the next agenda item.", "ja2": "次の議題に移りましょう。", "note": "", "nuance": "get over(困難を乗り越える、完了のニュアンス)と近いが、move onは「過去を引きずらず前に進む」という継続的な姿勢を表す。", "groups": ["move_on_over"], "etymology": "move（動く）＋on（接触・継続）\n→ 意識を次の対象の上に移して切り替えるイメージ\n→ そこから「次に進む、気持ちを切り替える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 27, "stage": 1, "verb": "give up", "meaning": "あきらめる、やめる", "def": "to stop trying; to quit a habit", "ex1": "After the third failed attempt, he just gave up and went home.", "ja1": "3回目の失敗のあと、彼はもうあきらめて家に帰ってしまった。", "ex2": "We won't give up on meeting the deadline.", "ja2": "納期を守ることをあきらめません。", "note": "", "nuance": "quit(仕事や習慣をやめる)よりも、あきらめる気持ちの面が強い。stop(単に止める)より感情的なニュアンスを含む。", "groups": ["give_up_in"], "etymology": "give（与える）＋up（上へ）\n→ それ以上は続けられない限界まで達し、そこで打ち切るイメージ\n→ そこから「あきらめる、やめる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 28, "stage": 1, "verb": "get to", "meaning": "〜に到着する", "def": "to arrive at a place", "ex1": "If we leave now, we should get to the airport with time to spare.", "ja1": "今出れば、余裕を持って空港に着けるはずだ。", "ex2": "Please get to the venue 15 minutes before the meeting.", "ja2": "会議の15分前には会場に着いてください。", "note": "Stage 2 / Stage 8 に別語義あり", "nuance": "arrive at（到着そのもの）より口語的。reachが「（努力して）到達する」ニュアンスを含むのに対し、get toはシンプルに「着く」ことを表す。", "groups": ["get_to_senses"], "etymology": "get（得る・～になる）＋to（～へ）\n→ 目指す場所の方向へ進んで達するイメージ\n→ そこから「〜に到着する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 29, "stage": 1, "verb": "keep up", "meaning": "遅れずについていく", "def": "to move or progress at the same rate as others", "ex1": "He walks so fast that I have to jog just to keep up.", "ja1": "彼はとても早歩きなので、ついていくには小走りしないといけない。", "ex2": "It's hard to keep up with the changes in the requirements.", "ja2": "要件の変更についていくのは大変だ。", "note": "後ろに with を伴うことが多い", "nuance": "follow(単についていく)より、「遅れずに同じペースを保つ」という努力のニュアンスがある。catch up(遅れを取り戻す)とは違い、keep upはすでに追いついている状態を維持すること。", "groups": ["catch_up_behind"], "etymology": "keep（保つ）＋up（上へ）\n→ 遅れている分を引き上げて、相手と同じ地点まで達するイメージ\n→ そこから「遅れずについていく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 30, "stage": 1, "verb": "hold down", "meaning": "（仕事を）続ける／押さえつける", "def": "to keep a job over time; to keep something from moving", "ex1": "Even with two kids, she managed to hold down a full-time job.", "ja1": "子供が2人いても、彼女はフルタイムの仕事を続けている。", "ex2": "She has held down the project manager role for three years.", "ja2": "彼女は3年間プロジェクトマネージャーを務めている。", "note": "", "nuance": "keep(単に保つ)より具体的に、仕事や地位を「維持し続ける」努力を表す。maintainよりくだけた言い方。", "groups": ["undertake_continue_work"], "etymology": "hold（持つ・保つ）＋down（下へ）\n→ 揺らがず地に足をつけたまま保ち続けるイメージ\n→ そこから「（仕事を）続ける／押さえつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 31, "stage": 1, "verb": "hand in", "meaning": "提出する", "def": "to submit something to a person in authority", "ex1": "I handed in my essay ten minutes before the deadline, heart pounding.", "ja1": "締め切りの10分前に、心臓をバクバクさせながらレポートを提出した。", "ex2": "Please hand in your expense report by the end of the month.", "ja2": "月末までに経費精算書を提出してください。", "note": "", "nuance": "submit(改まった提出)より口語的。turn inとほぼ同義だが、hand inは「手渡す」動作のニュアンスがより強い。", "groups": ["submit"], "etymology": "hand（手渡す）＋in（中へ）\n→ 書類を窓口や制度の内側に差し出すイメージ\n→ そこから「提出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(11,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 32, "stage": 1, "verb": "get away", "meaning": "逃げる、（休暇で）出かける", "def": "to escape; to leave for a short break or trip", "ex1": "The prisoner got away by hiding in the back of a delivery truck.", "ja1": "その囚人は配達トラックの荷台に隠れて逃げた。", "ex2": "I couldn't get away from the office until eight.", "ja2": "8時までオフィスを離れられなかった。", "note": "", "nuance": "escape(逃げる)と同じ意味に加え、「休暇でどこかへ出かける」という別の意味もある。get away fromで「〜から逃れる」の形でよく使う。", "groups": ["escape_run_away"], "etymology": "get（得る・～になる）＋away（遠くへ）\n→ 危険や束縛からその場を離れて遠ざかるイメージ\n→ そこから「逃げる、（休暇で）出かける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 33, "stage": 1, "verb": "go ahead", "meaning": "先に進める、（許可して）どうぞ", "def": "to proceed with something; to give permission to start", "ex1": "The manager just nodded and said, \"Go ahead, I trust your judgment.\"", "ja1": "マネージャーはただうなずいて、「進めていいよ、君の判断を信じる」と言った。", "ex2": "Shall we go ahead with the current schedule?", "ja2": "現行のスケジュールで進めてよろしいですか。", "note": "", "nuance": "continue(単に続ける)より、相手に許可・促しを与える場面で使う口語表現。proceedより日常会話向き。", "groups": [], "etymology": "go（行く）＋ahead（先へ）\n→ 前方・先に進むイメージ\n→ そこから「先に進める、（許可して）どうぞ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L10 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 3 L12 13 M15 3 L15 13\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 34, "stage": 1, "verb": "come from", "meaning": "〜の出身である、〜に由来する", "def": "to originate from a place or source", "ex1": "Judging by his accent, I'd guess he comes from somewhere in the south.", "ja1": "訛りから判断すると、彼は南部のどこか出身だと思う。", "ex2": "Most of our revenue comes from the domestic market.", "ja2": "売上の大半は国内市場によるものです。", "note": "", "nuance": "originate from（改まった由来）より口語的。be fromとほぼ同義で、出身地や由来を表す最も一般的な言い方。", "groups": [], "etymology": "come（来る）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「〜の出身である、〜に由来する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 35, "stage": 1, "verb": "go together", "meaning": "似合う、調和する", "def": "to match or suit each other well", "ex1": "Those two colors really don't go together, but somehow the outfit works.", "ja1": "その2色は本来合わないはずなのに、なぜかその服装は決まっている。", "ex2": "Cost reduction and quality improvement don't always go together.", "ja2": "コスト削減と品質向上は必ずしも両立しない。", "note": "", "nuance": "matchが色や柄など「合う」全般を指すのに対し、go togetherは「調和して似合う」という主観的な印象を含む。", "groups": ["match_suit"], "etymology": "go（行く）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「似合う、調和する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 36, "stage": 1, "verb": "get into", "meaning": "中に入る／〜に夢中になる", "def": "to enter a place; to become interested in something", "ex1": "After watching one documentary, he got into astronomy and never stopped.", "ja1": "1本のドキュメンタリーを見てから、彼は天文学にハマってやめられなくなった。", "ex2": "It took time to get into the details of the contract.", "ja2": "契約の詳細に踏み込むのに時間がかかった。", "note": "", "nuance": "enterより口語的。get in(小さい乗り物に乗り込む)と似た形だが、get intoは「場所の内側に入る」動作、または「趣味などにハマる」という比喩的な意味でも使う。", "groups": ["enter_various"], "etymology": "get（得る・～になる）＋into（中へ変化）\n→ 興味の対象の中へどっぷりのめり込むイメージ\n→ そこから「中に入る／〜に夢中になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 37, "stage": 1, "verb": "put up", "meaning": "（看板・テントなどを）掲げる、建てる", "def": "to build or place something in position", "ex1": "It took all afternoon to put up the tent in the wind.", "ja1": "風の中でテントを立てるのに、午後いっぱいかかった。", "ex2": "They put up a notice about the system maintenance.", "ja2": "システムメンテナンスの掲示を出した。", "note": "Stage 2 / Stage 5 に別語義あり", "nuance": "buildより手軽な組み立てを表す。setUpとほぼ同義だが、put upはテントや看板など「立てる」動作に使われることが多い。", "groups": ["put_up_senses"], "etymology": "put（置く）＋up（上へ）\n→ 地面や壁から上へ向けて組み立て、据え付けるイメージ\n→ そこから「（看板・テントなどを）掲げる、建てる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-8,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 38, "stage": 1, "verb": "go away", "meaning": "立ち去る、（症状などが）消える", "def": "to leave a place; to disappear", "ex1": "I told him to just go away, but he kept following me anyway.", "ja1": "あっちに行ってと言ったのに、彼はそれでも私についてきた。", "ex2": "The problem won't go away unless we fix the root cause.", "ja2": "根本原因を直さない限り問題はなくならない。", "note": "", "nuance": "leave(単に去る)より、命令口調でよく使われるくだけた表現。disappear(完全に消える)より一時的なニュアンス。", "groups": ["leave_place"], "etymology": "go（行く）＋away（遠くへ）\n→ その場を離れて遠くへ去っていくイメージ\n→ そこから「立ち去る、（症状などが）消える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 39, "stage": 1, "verb": "go down", "meaning": "下がる、（日が）沈む", "def": "to decrease; to move downward", "ex1": "Stock prices went down the moment the news broke.", "ja1": "そのニュースが流れた瞬間、株価は下がった。", "ex2": "Our operating costs went down by ten percent.", "ja2": "運用コストが10パーセント下がった。", "note": "Stage 7 の go down*2 と区別", "nuance": "decrease(数値の減少)やset(日が沈む)を口語的に表す。riseの反対。", "groups": ["go_down_senses"], "etymology": "go（行く）＋down（下へ）\n→ 高い位置から低い位置へ落ちていくイメージ\n→ そこから「下がる、（日が）沈む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 40, "stage": 1, "verb": "get behind", "meaning": "遅れをとる、滞る", "def": "to fall behind a schedule or fail to keep up", "ex1": "He's always getting behind on rent, then scrambling to catch up.", "ja1": "彼はいつも家賃の支払いが遅れて、それから慌てて追いつこうとする。", "ex2": "The project got behind schedule by two weeks.", "ja2": "プロジェクトは2週間スケジュールが遅れた。", "note": "Stage 6 の get behind*2 と区別", "nuance": "fall behind(遅れる、より一般的)とほぼ同義だが、get behindは特に支払いやスケジュールの遅れによく使われる。", "groups": ["catch_up_behind"], "etymology": "get（得る・～になる）＋behind（後ろに）\n→ 後方に取り残されるイメージ\n→ そこから「遅れをとる、滞る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M3 3 L3 13 M6 3 L6 13\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 41, "stage": 1, "verb": "go out", "meaning": "外出する、出かける", "def": "to leave home for an activity", "ex1": "It was too nice a day to stay inside, so we went out for a walk.", "ja1": "家にいるにはもったいないほど良い天気だったので、散歩に出かけた。", "ex2": "The team went out for dinner after the release.", "ja2": "リリース後、チームは夕食に出かけた。", "note": "", "nuance": "leave the house（家を出る）よりカジュアルで、「外出して過ごす」というニュアンスを含む。stay in（家にいる）の反対。", "groups": ["home_or_out"], "etymology": "go（行く）＋out（外へ）\n→ 内側の空間から外の世界へ出ていくイメージ\n→ そこから「外出する、出かける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 42, "stage": 1, "verb": "go up to", "meaning": "〜に近づく、歩み寄る", "def": "to approach someone or something", "ex1": "A stranger went up to her and asked if they'd met before.", "ja1": "見知らぬ人が彼女に近づいてきて、前に会ったことがあるか尋ねた。", "ex2": "He went up to the client and introduced himself.", "ja2": "彼は顧客に歩み寄って自己紹介した。", "note": "", "nuance": "approach(改まった接近)より口語的。walk up to（歩いて近づく）とほぼ同義で、人に近づく場面でよく使う。", "groups": [], "etymology": "go（行く）＋up（上へ）＋to（～へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「〜に近づく、歩み寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 43, "stage": 1, "verb": "turn on", "meaning": "（電源・明かりを）つける", "def": "to start a machine, light, or device", "ex1": "I fumbled in the dark trying to turn on the light.", "ja1": "暗闇の中、明かりをつけようと手探りした。", "ex2": "Please turn on the projector before the meeting starts.", "ja2": "会議が始まる前にプロジェクターをつけてください。", "note": "元リストの turn on/off を分割", "nuance": "switch on(スイッチ操作を強調)とほぼ同義。turn offの反対で、電源・明かり全般に幅広く使う最も一般的な表現。", "groups": ["power"], "etymology": "turn（向きを変える）＋on（接触・継続）\n→ 電源をつなげて機能させるイメージ\n→ そこから「（電源・明かりを）つける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 44, "stage": 1, "verb": "turn off", "meaning": "（電源・明かりを）消す", "def": "to stop a machine, light, or device", "ex1": "Please turn off your phone before the movie starts.", "ja1": "映画が始まる前に携帯の電源を切ってください。", "ex2": "Turn off your microphone when you are not speaking.", "ja2": "話していないときはマイクをオフにしてください。", "note": "元リストの turn on/off を分割", "nuance": "switch off とほぼ同義。turn onの反対で、電源を切る最も一般的な言い方。", "groups": ["power"], "etymology": "turn（向きを変える）＋off（離れて）\n→ 動いていたものから電源やつながりを切り離して止めるイメージ\n→ そこから「（電源・明かりを）消す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-13,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 45, "stage": 1, "verb": "run into", "meaning": "偶然出会う／（問題に）ぶつかる", "def": "to meet by chance; to encounter a problem", "ex1": "I ran into my old roommate at the grocery store, of all places.", "ja1": "よりによってスーパーで元ルームメイトにばったり会った。", "ex2": "We ran into a problem during the data migration.", "ja2": "データ移行中に問題にぶつかった。", "note": "", "nuance": "encounter(改まった遭遇)より口語的。bump into(偶然ぶつかる)とほぼ同義で、人との遭遇にも問題への直面にも使える。", "groups": ["encounter"], "etymology": "run（走る）＋into（中へ変化）\n→ 予期せず何かの内側に入り込んでしまうイメージ\n→ そこから「偶然出会う／（問題に）ぶつかる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 46, "stage": 1, "verb": "put away", "meaning": "片づける、しまう", "def": "to return something to its proper place", "ex1": "After the party, we spent an hour putting away all the chairs.", "ja1": "パーティーのあと、椅子を全部片づけるのに1時間かかった。", "ex2": "Please put away the confidential documents after the meeting.", "ja2": "会議後は機密書類をしまってください。", "note": "", "nuance": "put back(元の場所に戻す)と似ているが、put awayは「使い終わった物を収納する」というニュアンスがより強い。", "groups": ["tidy_up"], "etymology": "put（置く）＋away（遠くへ）\n→ 使わない物を目の届かない所へしまい込むイメージ\n→ そこから「片づける、しまう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 47, "stage": 1, "verb": "turn out", "meaning": "結局〜になる、〜と判明する", "def": "to happen or end in a particular way; to prove to be", "ex1": "The trip that sounded like a disaster turned out to be the best one yet.", "ja1": "大失敗になりそうだった旅行が、結局これまでで一番の旅になった。", "ex2": "The estimate turned out to be too optimistic.", "ja2": "見積もりは楽観的すぎたと判明した。", "note": "", "nuance": "endは単に「終わる」ことを指すのに対し、turn outは「予想と違う結末になる」という意外性を含む。", "groups": ["turn_out_end_up"], "etymology": "turn（向きを変える）＋out（外へ）\n→ 隠れていた事実が表に出て、はっきり見えてくるイメージ\n→ そこから「結局〜になる、〜と判明する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 48, "stage": 1, "verb": "look up to", "meaning": "尊敬する", "def": "to admire and respect someone", "ex1": "She's always looked up to her older sister, even as an adult.", "ja1": "彼女は大人になった今でも、ずっとお姉さんを尊敬している。", "ex2": "The younger members look up to him as a mentor.", "ja2": "若手メンバーは彼をメンターとして尊敬している。", "note": "反意は look down on", "nuance": "尊敬の対象として見上げる比喩。look down onの反対。", "groups": [], "etymology": "look（見る）＋up（上へ）＋to（～へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「尊敬する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 49, "stage": 1, "verb": "ask for", "meaning": "求める、頼む", "def": "to request something", "ex1": "The toddler kept asking for one more cookie until we gave in.", "ja1": "その幼児は根負けするまで、もう一個クッキーをねだり続けた。", "ex2": "The client asked for a revised quotation.", "ja2": "顧客は見積もりの修正を求めた。", "note": "", "nuance": "requestより口語的。demand(強く要求する)ほど強くなく、頼み事全般に幅広く使う。", "groups": [], "etymology": "ask（尋ねる）＋for（求めて）\n→ 欲しい物に向かって手を伸ばすイメージ\n→ そこから「求める、頼む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 50, "stage": 1, "verb": "shut up", "meaning": "黙る", "def": "to stop talking", "ex1": "The teacher told the noisy kids to shut up, then immediately felt bad about it.", "ja1": "先生はうるさい子どもたちに黙るよう言ってから、すぐに悪いことをしたと感じた。", "ex2": "Telling a colleague to shut up would be unacceptable at work.", "ja2": "同僚に「黙れ」と言うのは職場では許されない。", "note": "かなり無礼。目上には使わない", "nuance": "be quietより直接的で、時にきつい響きを持つ命令表現。stop talking（話すのをやめて）と似ているが、shut upはやや無礼に聞こえることがある。", "groups": ["imperative_expr"], "etymology": "shut（閉める）＋up（上へ）\n→ それ以上は続けられない限界まで達し、そこで打ち切るイメージ\n→ そこから「黙る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(11,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 51, "stage": 1, "verb": "throw away", "meaning": "捨てる", "def": "to dispose of something you no longer want", "ex1": "I almost threw away the receipt, and of course that's the one I needed for the refund.", "ja1": "そのレシートを捨てそうになったけど、まさにそれが返金に必要なものだった。", "ex2": "Don't throw away the meeting notes; we may need them for the report.", "ja2": "議事メモを捨てないで、報告書で必要になるかもしれない。", "note": "", "nuance": "dispose of(改まった廃棄)より日常的。get rid of（処分する）とほぼ同義だが、throw awayはゴミ箱に捨てる動作そのものを表す。", "groups": ["discard"], "etymology": "throw（投げる）＋away（遠くへ）\n→ 不要な物を手放して遠くへやるイメージ\n→ そこから「捨てる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 53, "stage": 2, "verb": "freshen up", "meaning": "さっぱりする、身支度を整える", "def": "to wash and make yourself look tidy", "ex1": "I splashed some cold water on my face to freshen up before the interview.", "ja1": "面接の前に、顔に冷たい水をかけてさっぱりした。", "ex2": "Let's freshen up before we meet the client.", "ja2": "顧客に会う前に身なりを整えよう。", "note": "", "nuance": "wash up(洗って清潔にする)より軽く、水で顔を洗ったりして気分をすっきりさせる程度のニュアンス。", "groups": [], "etymology": "freshen（新鮮にする）＋up（上へ）\n→ 状態を上向きに整えて、良い状態に持っていくイメージ\n→ そこから「さっぱりする、身支度を整える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 54, "stage": 2, "verb": "check in", "meaning": "チェックインする、受付を済ませる", "def": "to register at a hotel, airport, or event", "ex1": "We couldn't check in until three, so we left our bags at the front desk.", "ja1": "3時までチェックインできなかったので、荷物をフロントに預けた。", "ex2": "Please check in at the reception desk on the first floor.", "ja2": "1階の受付で受付を済ませてください。", "note": "", "nuance": "register(登録)より特にホテルや空港での手続きを指す。check outの反対。", "groups": ["hotel_checkin"], "etymology": "check（確認する）＋in（中へ）\n→ 手続きの内側に入って完了させるイメージ\n→ そこから「チェックインする、受付を済ませる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 55, "stage": 2, "verb": "check out", "meaning": "チェックアウトする", "def": "to pay and leave a hotel", "ex1": "We overslept and had to check out in a total panic.", "ja1": "寝坊してしまい、大慌てでチェックアウトする羽目になった。", "ex2": "I checked out early to make the morning meeting.", "ja2": "朝の会議に間に合うよう早めにチェックアウトした。", "note": "Stage 3 / 6 に別語義あり", "nuance": "ホテルの精算・退室。Stage3・6の別義と区別が必要。", "groups": ["hotel_checkin"], "etymology": "check（確認する）＋out（外へ）\n→ 施設の手続きを終えて外へ出るイメージ\n→ そこから「チェックアウトする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 56, "stage": 2, "verb": "pick out", "meaning": "選び出す", "def": "to choose one thing from a group", "ex1": "It took forever, but she finally picked out a dress for the wedding.", "ja1": "すごく時間がかかったけど、彼女はようやく結婚式用のドレスを選び出した。", "ex2": "Please pick out three candidates for the interview.", "ja2": "面接の候補者を3名選んでください。", "note": "", "nuance": "chooseより「複数の中から一つを選び出す」という抜き出す動作のニュアンスが強い。selectよりくだけた言い方。", "groups": ["choose"], "etymology": "pick（つまむ・選ぶ）＋out（外へ）\n→ 多くの中から一つを外へ抜き出すイメージ\n→ そこから「選び出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 57, "stage": 2, "verb": "get together", "meaning": "集まる", "def": "to meet with other people socially or for a purpose", "ex1": "The old classmates get together every year on the same weekend in July.", "ja1": "その元クラスメイトたちは毎年7月の同じ週末に集まる。", "ex2": "Can we get together to review the draft?", "ja2": "草案を確認するために集まれますか。", "note": "Stage 3 に別語義あり", "nuance": "meet(単に会う)より、複数人が「一箇所に集まる」というニュアンスが強い。gather(改まった集合)より口語的。", "groups": ["gather"], "etymology": "get（得る・～になる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「集まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 58, "stage": 2, "verb": "go through", "meaning": "一通り目を通す／（つらい経験を）経る", "def": "to examine in detail; to experience something difficult", "ex1": "I went through the contract twice before I noticed the hidden fee.", "ja1": "隠れた手数料に気づくまで、契約書を2回読み直した。", "ex2": "Let's go through the agenda before we start.", "ja2": "始める前に議題に目を通しましょう。", "note": "", "nuance": "check(確認する)より徹底的に「一通り全部見る・経験する」ニュアンス。experience（経験する）より、大変さを乗り越える意味合いを含むことがある。", "groups": ["skim_review"], "etymology": "go（行く）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「一通り目を通す／（つらい経験を）経る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 59, "stage": 2, "verb": "put down", "meaning": "下に置く", "def": "to place something on a surface", "ex1": "She put down her phone the second the baby started crying.", "ja1": "赤ちゃんが泣き出した瞬間、彼女は携帯を置いた。", "ex2": "He put down his pen and looked at the screen.", "ja2": "彼はペンを置いて画面を見た。", "note": "Stage 3 / 4 に別語義あり", "nuance": "put awayが「収納する」のに対し、put downは「今持っている物を一時的に下に置く」動作を表す。dropより丁寧で意図的な動作。", "groups": ["put_down_senses"], "etymology": "put（置く）＋down（下へ）\n→ 手にしていた物をそっと下に置くイメージ\n→ そこから「下に置く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 60, "stage": 2, "verb": "try on", "meaning": "試着する", "def": "to put on clothing to see if it fits or suits you", "ex1": "He tried on five shirts before settling on the plain white one.", "ja1": "彼はシャツを5枚も試着した末、結局無地の白に落ち着いた。", "ex2": "She tried on the uniform before the trade show.", "ja2": "展示会の前に彼女は制服を試着した。", "note": "", "nuance": "wear(身につけている状態)ではなく、購入前に「試しに着てみる」動作を指す。fit（サイズが合う）とは異なる。", "groups": ["clothing_wear"], "etymology": "try（試す）＋on（接触・継続）\n→ 実際に身につけて確かめるイメージ\n→ そこから「試着する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 61, "stage": 2, "verb": "hold on", "meaning": "少し待つ、電話を切らずに待つ", "def": "to wait for a short time", "ex1": "Hold on a second, I think I hear someone at the door.", "ja1": "ちょっと待って、誰かがドアのところにいる気がする。", "ex2": "Could you hold on while I transfer your call?", "ja2": "お電話をおつなぎしますので少々お待ちください。", "note": "", "nuance": "wait(単に待つ)より、特に電話を切らずに待つ場面でよく使われる口語表現。stayより一時的な待機を表す。", "groups": ["wait"], "etymology": "hold（持つ・保つ）＋on（接触・継続）\n→ 接続やつながりをそのまま保ち続けるイメージ\n→ そこから「少し待つ、電話を切らずに待つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 62, "stage": 2, "verb": "give out", "meaning": "（無料サンプルなどを）配る", "def": "to distribute something to a group of people", "ex1": "Volunteers gave out free water bottles to everyone in the marathon.", "ja1": "ボランティアがマラソン参加者全員に無料の水を配った。", "ex2": "Please give out the handouts before the session starts.", "ja2": "セッション開始前に資料を配ってください。", "note": "Stage 2 の give out*2 と区別", "nuance": "distribute(改まった配布)より口語的。hand out（手渡しで配る）とほぼ同義。", "groups": ["distribute"], "etymology": "give（与える）＋out（外へ）\n→ 内側にあった物を外の人々へ配って行き渡らせるイメージ\n→ そこから「（無料サンプルなどを）配る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 63, "stage": 2, "verb": "pick up", "meaning": "拾い上げる／車で迎えに行く", "def": "to lift something up; to collect someone in a vehicle", "ex1": "I bent down to pick up a coin and hit my head on the table.", "ja1": "コインを拾おうとかがんだら、テーブルに頭をぶつけた。", "ex2": "I'll pick you up at the station at nine.", "ja2": "9時に駅までお迎えに行きます。", "note": "Stage 3 / 7 / 8 に別語義あり", "nuance": "get(単に得る)より「拾い上げる」「車で迎えに行く」など具体的な動作を伴う。collectよりカジュアル。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 下にある物や人をすくい上げて手元に引き寄せるイメージ\n→ そこから「拾い上げる／車で迎えに行く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 64, "stage": 2, "verb": "fall over", "meaning": "つまずいて転ぶ", "def": "to fall to the ground", "ex1": "He fell over his own shoelaces right in front of the whole class.", "ja1": "彼はクラス全員の前で自分の靴紐につまずいて転んだ。", "ex2": "The display panel fell over during setup.", "ja2": "設営中に展示パネルが倒れた。", "note": "", "nuance": "trip(つまずく)だけでなく、その結果「転ぶ」ところまでを含む。fall down（単に倒れる）より、何かにつまずいた原因を暗示する。", "groups": ["fall_down"], "etymology": "fall（落ちる）＋over（越えて）\n→ 越えようとしてバランスを崩し倒れるイメージ\n→ そこから「つまずいて転ぶ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 65, "stage": 2, "verb": "get up", "meaning": "起きる、立ち上がる", "def": "to get out of bed; to rise to your feet", "ex1": "I hit snooze three times before I finally got up.", "ja1": "スヌーズを3回押した末、ようやく起きた。", "ex2": "He got up to greet the visitors.", "ja2": "彼は来客を迎えるために立ち上がった。", "note": "", "nuance": "wake up（目が覚める）が意識が戻ることを指すのに対し、get upは「布団やベッドから体を起こす」動作そのものを表す。", "groups": ["get_up_stand_up"], "etymology": "get（得る・～になる）＋up（上へ）\n→ 物事の程度や量を実際より高く引き上げるイメージ\n→ そこから「起きる、立ち上がる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 66, "stage": 2, "verb": "run out of", "meaning": "〜を切らす、使い果たす", "def": "to have no more of something left", "ex1": "We ran out of milk again, so cereal for breakfast is off the table.", "ja1": "また牛乳を切らしてしまったので、朝食にシリアルは無理だ。", "ex2": "We're running out of time, so let's decide today.", "ja2": "時間がなくなってきたので今日決めましょう。", "note": "", "nuance": "use up（使い切る）とほぼ同義だが、run out ofは「気づいたら無くなっていた」という受動的なニュアンスが強い。", "groups": ["use_up"], "etymology": "run（走る）＋out（外へ）＋of（～の）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「〜を切らす、使い果たす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 67, "stage": 2, "verb": "walk out", "meaning": "途中で出ていく、席を立つ", "def": "to leave suddenly, often in protest", "ex1": "The meeting got so boring that two people quietly walked out.", "ja1": "会議があまりに退屈で、2人がこっそり席を立って出ていった。", "ex2": "Two members walked out of the negotiation.", "ja2": "交渉の場から2名が席を立って出ていった。", "note": "", "nuance": "leave(単に去る)より、抗議や不満を示すために「途中で席を立つ」という強い意思表示を含む。", "groups": ["leave_place"], "etymology": "walk（歩く）＋out（外へ）\n→ 内側の空間から外の世界へ出ていくイメージ\n→ そこから「途中で出ていく、席を立つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 68, "stage": 2, "verb": "catch up", "meaning": "追いつく、遅れを取り戻す", "def": "to reach the same level or position as others", "ex1": "I had to skip a whole week of classes, and it took ages to catch up.", "ja1": "まる1週間授業を休んで、追いつくのにすごく時間がかかった。", "ex2": "We need to catch up on the delayed tasks.", "ja2": "遅れているタスクを取り戻す必要がある。", "note": "Stage 4 に別語義あり", "nuance": "keep up(遅れずについていく、現在進行形)に対し、catch upは「すでに遅れている状態から追いつく」動作を表す。", "groups": ["catch_up_behind"], "etymology": "catch（捕まえる）＋up（上へ）\n→ 遅れている分を引き上げて、相手と同じ地点まで達するイメージ\n→ そこから「追いつく、遅れを取り戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 69, "stage": 2, "verb": "work out", "meaning": "うまくいく／運動する", "def": "to end successfully; to do physical exercise", "ex1": "Against all odds, the risky plan actually worked out.", "ja1": "予想に反して、そのリスクの高い計画は実際うまくいった。", "ex2": "I'm sure the new process will work out.", "ja2": "新しい手順はうまくいくと思う。", "note": "Stage 3 / 4 に別語義あり", "nuance": "succeed(単に成功する)より口語的。exercise(運動する)という全く別の意味もある多義語。", "groups": ["succeed"], "etymology": "work（働く・作用させる）＋out（外へ）\n→ 途中で終わらせず、最後までとことん計算・処理しきるイメージ\n→ そこから「うまくいく／運動する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 70, "stage": 2, "verb": "turn back", "meaning": "引き返す", "def": "to return the way you came", "ex1": "Halfway up the mountain, the storm forced us to turn back.", "ja1": "山を半分登ったところで、嵐のせいで引き返さざるを得なかった。", "ex2": "Once the contract is signed, we can't turn back.", "ja2": "契約を結んだら後戻りはできない。", "note": "", "nuance": "go back(単に戻る)より、「引き返す」という方向転換のニュアンスが強い。retreatより日常的な言い方。", "groups": ["turn_direction"], "etymology": "turn（向きを変える）＋back（後ろ・元へ）\n→ 進んでいた道を逆にたどって戻るイメージ\n→ そこから「引き返す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 71, "stage": 2, "verb": "go after", "meaning": "追いかける、（目標を）狙う", "def": "to chase or pursue someone or something", "ex1": "He quit his stable job to go after his dream of acting.", "ja1": "彼は安定した仕事を辞めて、俳優になる夢を追いかけた。", "ex2": "We're going after the mid-size enterprise market.", "ja2": "我々は中堅企業市場を狙っている。", "note": "", "nuance": "chase(単に追いかける)より、目標や機会を「積極的に狙いに行く」という意欲を含む。pursueより口語的。", "groups": [], "etymology": "go（行く）＋after（後を追って）\n→ 対象の後ろについていくイメージ\n→ そこから「追いかける、（目標を）狙う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/><path d=\"M9 3 L15 8 L9 13\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 72, "stage": 2, "verb": "stand up", "meaning": "立ち上がる", "def": "to rise to a standing position", "ex1": "The whole audience stood up and applauded the moment the song ended.", "ja1": "曲が終わった瞬間、観客全員が立ち上がって拍手した。", "ex2": "Please stand up and introduce yourself.", "ja2": "立って自己紹介をしてください。", "note": "Stage 2 の stand up*2 と区別", "nuance": "get up(起床する)と似た形だが、stand upは座っている状態から「立ち上がる」動作を指す。", "groups": ["get_up_stand_up"], "etymology": "stand（立つ）＋up（上へ）\n→ 物事の程度や量を実際より高く引き上げるイメージ\n→ そこから「立ち上がる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 73, "stage": 2, "verb": "speak up", "meaning": "大きな声で話す、意見を述べる", "def": "to speak more loudly; to express your opinion openly", "ex1": "She was too shy to speak up, even though she had the best idea.", "ja1": "彼女は一番良い案を持っていたのに、恥ずかしくて発言できなかった。", "ex2": "If you disagree, please speak up in the meeting.", "ja2": "反対なら会議で意見を述べてください。", "note": "", "nuance": "talk(単に話す)より、遠慮せず「はっきり意見を述べる」という積極性を含む。voice one's opinionより口語的。", "groups": ["speak_loudly"], "etymology": "speak（話す）＋up（上へ）\n→ 声や集中力を上向きに高めるイメージ\n→ そこから「大きな声で話す、意見を述べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 74, "stage": 2, "verb": "pass on", "meaning": "（情報を）伝える、渡す", "def": "to give information or an item to another person", "ex1": "Can you pass on this message to the rest of the team?", "ja1": "このメッセージをチームの他の人にも伝えてもらえる？", "ex2": "I'll pass on your feedback to the development team.", "ja2": "いただいたご意見を開発チームに伝えます。", "note": "", "nuance": "tellが単に「伝える」のに対し、pass onは受け取った情報を「別の人へ回す」という中継のニュアンスが強い。", "groups": ["convey_info"], "etymology": "pass（通す・渡す）＋on（接触・継続）\n→ 情報を次の人へとつなげて渡すイメージ\n→ そこから「（情報を）伝える、渡す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 75, "stage": 2, "verb": "come along", "meaning": "一緒に来る／進展する", "def": "to accompany someone; to make progress", "ex1": "We invited him to come along, and he ended up being the funniest one there.", "ja1": "彼を一緒に来るよう誘ったら、結局その場で一番面白い人になった。", "ex2": "How is the proposal coming along?", "ja2": "提案書の進み具合はいかがですか。", "note": "Stage 5 に別語義あり", "nuance": "join（参加する）より軽く、誘われて「一緒に来る」というニュアンス。progress(進展する)という別の意味も持つ。", "groups": [], "etymology": "come（来る）＋along（沿って）\n→ 相手と並んで同じ道を進んでいくイメージ\n→ そこから「一緒に来る／進展する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(2,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 76, "stage": 2, "verb": "come up*2", "meaning": "（機会・話が）出てくる、生じる", "def": "to become available or arise, e.g. an opportunity", "ex1": "A last-minute opportunity came up, so we changed our whole schedule.", "ja1": "土壇場でチャンスが出てきたので、予定を全部変更した。", "ex2": "If a suitable position comes up, I'll let you know.", "ja2": "適したポジションが空いたらお知らせします。", "note": "Stage 1 の come up と区別", "nuance": "arise(改まった発生)より口語的。come up(話題が持ち上がる、より一般的)と似ているが、come up with(思いつく)とは全く異なる意味なので注意。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋up（上へ）\n→ 知りたい情報を掘り起こして表に持ってくるイメージ\n→ そこから「（機会・話が）出てくる、生じる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 77, "stage": 2, "verb": "stand out", "meaning": "目立つ、際立つ", "def": "to be noticeably better or different from others", "ex1": "Her bright red coat made her stand out in the crowd immediately.", "ja1": "彼女の真っ赤なコートは、人混みの中ですぐに目立った。", "ex2": "This proposal stands out because of its cost advantage.", "ja2": "この提案はコスト面の優位性で際立っている。", "note": "", "nuance": "be noticeable(単に目立つ)より、周りとの対比で「際立って見える」という強調を含む。stick outとほぼ同義。", "groups": ["stand_out_show_off"], "etymology": "stand（立つ）＋out（外へ）\n→ 周囲から浮き上がるように外へ突き出るイメージ\n→ そこから「目立つ、際立つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 78, "stage": 2, "verb": "go over to", "meaning": "〜へ移動する、〜側につく", "def": "to move to another place or switch to another side", "ex1": "Midway through the debate, one panelist went over to the other side.", "ja1": "討論の途中で、パネリストの一人が反対側に寝返った。", "ex2": "Several clients went over to a competitor.", "ja2": "何社かの顧客が競合他社に移った。", "note": "", "nuance": "go over(見直す、確認する)とは別の意味で、こちらは「相手側へ移動する・寝返る」ことを指す。switch sidesと似たニュアンス。", "groups": ["head_toward"], "etymology": "go（行く）＋over（越えて）＋to（～へ）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「〜へ移動する、〜側につく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 79, "stage": 2, "verb": "head to", "meaning": "〜へ向かう", "def": "to go in the direction of a place", "ex1": "We need to head to the airport by six at the latest.", "ja1": "遅くとも6時までには空港へ向かわないといけない。", "ex2": "I'm heading to the client's office now.", "ja2": "これから顧客のオフィスへ向かいます。", "note": "", "nuance": "go to(単に行く)より、目的地への「移動を始める」という意図を強調する。leave forとほぼ同義。", "groups": ["head_toward"], "etymology": "head（向かう）＋to（～へ）\n→ 目指す場所の方へまっすぐ進むイメージ\n→ そこから「〜へ向かう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-12,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 80, "stage": 2, "verb": "look around", "meaning": "見て回る", "def": "to look at the things around you; to browse a place", "ex1": "Feel free to look around; there's no obligation to buy anything.", "ja1": "自由に見て回ってください、購入する義務は一切ありません。", "ex2": "Feel free to look around the factory floor.", "ja2": "工場内を自由に見て回ってください。", "note": "", "nuance": "look for(目的を持って探す)とは違い、look aroundは「特に目的を決めず、辺りを見て回る」ことを表す。browse（店内を見て回る）と似ている。", "groups": [], "etymology": "look（見る）＋around（周りに）\n→ 一箇所に留まらずあちこちを見渡すイメージ\n→ そこから「見て回る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(9,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 81, "stage": 2, "verb": "get through", "meaning": "やり遂げる、乗り切る", "def": "to finish or survive something difficult", "ex1": "It was a brutal exam, but somehow I got through it.", "ja1": "とてもきつい試験だったけれど、なんとか乗り切った。", "ex2": "We got through the whole agenda in an hour.", "ja2": "1時間で議題をすべて片づけた。", "note": "", "nuance": "get through(困難を乗り切る)は、finish(単に終える)より、大変な状況を耐え抜くニュアンスを含む。survive(生き延びる)より軽い場面でも使える。", "groups": ["accomplish_through"], "etymology": "get（得る・～になる）＋through（通り抜けて）\n→ 始めから終わりまで一気に通り抜けるイメージ\n→ そこから「やり遂げる、乗り切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 82, "stage": 2, "verb": "turn in", "meaning": "提出する／床につく", "def": "to submit something; to go to bed", "ex1": "I turned in my badge and keys on my very last day.", "ja1": "最終日に社員証と鍵を返却した。", "ex2": "Please turn in the timesheet by Friday.", "ja2": "金曜までに勤務表を提出してください。", "note": "Stage 6 に別語義あり", "nuance": "hand in(改まった提出)とほぼ同義だが、turn inには「就寝する」という全く別の意味もある。", "groups": ["submit"], "etymology": "turn（向きを変える）＋in（中へ）\n→ 書類を窓口や制度の内側に差し出すイメージ\n→ そこから「提出する／床につく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 83, "stage": 2, "verb": "get along", "meaning": "仲良くやる、うまくやっていく", "def": "to have a good relationship with someone", "ex1": "Even though they argue constantly, the roommates somehow get along.", "ja1": "そのルームメイトたちはしょっちゅう言い合いしているのに、なぜか仲良くやっている。", "ex2": "He gets along well with the client's team.", "ja2": "彼は顧客側のチームとうまくやっている。", "note": "", "nuance": "get on with（うまくやっていく）とほぼ同義。fight（喧嘩する）の反対で、良好な関係を保つことを表す。", "groups": ["relationship_harmony"], "etymology": "get（得る・～になる）＋along（沿って）\n→ 相手と歩調を合わせて仲良く進むイメージ\n→ そこから「仲良くやる、うまくやっていく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 84, "stage": 2, "verb": "fool around", "meaning": "ふざける、時間を無駄にする", "def": "to behave in a silly way; to waste time", "ex1": "Instead of studying, they just fooled around on their phones all evening.", "ja1": "彼らは勉強する代わりに、夜通し携帯でふざけていた。", "ex2": "We can't fool around; the deadline is tomorrow.", "ja2": "ふざけている場合ではない、締切は明日だ。", "note": "", "nuance": "play(単に遊ぶ)より、真剣さに欠けてふざけている、または時間を無駄にしているという否定的なニュアンスを含む。", "groups": ["slack_off_group"], "etymology": "fool（ふざける）＋around（周りに）\n→ 目的もなくその場をうろつき回るイメージ\n→ そこから「ふざける、時間を無駄にする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-12,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 85, "stage": 2, "verb": "give back", "meaning": "返す、返却する", "def": "to return something to its owner", "ex1": "I borrowed his ladder and finally gave it back a month later.", "ja1": "彼のはしごを借りて、1ヶ月後にやっと返した。", "ex2": "Please give back the security card when you leave.", "ja2": "退出時にセキュリティカードを返却してください。", "note": "", "nuance": "return(改まった返却)より口語的。take back(取り戻す、逆方向)とは意味が逆なので注意。", "groups": ["return_money"], "etymology": "give（与える）＋back（後ろ・元へ）\n→ 借りていた物を元の持ち主へ戻すイメージ\n→ そこから「返す、返却する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-13,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 86, "stage": 2, "verb": "find out", "meaning": "判明する、突き止める", "def": "to discover a fact or piece of information", "ex1": "It took a private investigator three weeks to find out the truth.", "ja1": "私立探偵が真実を突き止めるのに3週間かかった。", "ex2": "We need to find out why the system failed.", "ja2": "システム障害の原因を突き止める必要がある。", "note": "", "nuance": "discover(発見する)より、調査や努力の末に「事実を突き止める」というプロセスを含む。learn(単に知る)より能動的。", "groups": [], "etymology": "find（見つける）＋out（外へ）\n→ 隠れていた事実が表に出て、はっきり見えてくるイメージ\n→ そこから「判明する、突き止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 87, "stage": 2, "verb": "show off", "meaning": "見せびらかす、披露する", "def": "to display something proudly to impress others", "ex1": "He couldn't resist showing off his new watch to everyone at the party.", "ja1": "彼はパーティーで新しい時計をみんなに見せびらかさずにはいられなかった。", "ex2": "The demo is a chance to show off the new features.", "ja2": "デモは新機能を披露する好機だ。", "note": "", "nuance": "boast(自慢する、やや否定的)より軽い口調で、自分の持ち物や能力を人に見せたい気持ちを表す。", "groups": ["stand_out_show_off"], "etymology": "show（見せる）＋off（離れて）\n→ 他から切り離して目立たせ、見せつけるイメージ\n→ そこから「見せびらかす、披露する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 88, "stage": 2, "verb": "call back", "meaning": "折り返し電話する", "def": "to return a phone call", "ex1": "I missed her call, so I called back as soon as I could.", "ja1": "彼女からの着信に気づかなくて、できるだけ早く折り返した。", "ex2": "He is in a meeting; may he call you back at three?", "ja2": "彼は会議中です。3時に折り返してもよろしいでしょうか。", "note": "", "nuance": "return the call(改まった言い方)とほぼ同義。call backはかかってきた電話に「折り返す」という日常表現。", "groups": ["call_phone"], "etymology": "call（呼ぶ）＋back（後ろ・元へ）\n→ 受けた連絡を相手へ送り返すイメージ\n→ そこから「折り返し電話する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 89, "stage": 2, "verb": "go off", "meaning": "（警報などが）鳴る、（機器が）止まる", "def": "to make a sudden loud noise; to stop working", "ex1": "The fire alarm went off at 3 a.m. for absolutely no reason.", "ja1": "火災報知器が理由もなく午前3時に鳴り出した。", "ex2": "The fire alarm went off during the presentation.", "ja2": "プレゼン中に火災報知器が鳴った。", "note": "", "nuance": "ring(単に鳴る)より、警報やアラームが突然作動する場面でよく使う。stop working（機器が動かなくなる）という反対の意味もある多義語。", "groups": [], "etymology": "go（行く）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（警報などが）鳴る、（機器が）止まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 90, "stage": 2, "verb": "go with", "meaning": "〜に合う／〜を選ぶ", "def": "to match something; to choose an option", "ex1": "That scarf really goes with your coat.", "ja1": "そのスカーフはあなたのコートによく合っている。", "ex2": "Let's go with the second proposal.", "ja2": "2つ目の案でいきましょう。", "note": "", "nuance": "matchより口語的。go with は服が「似合う」意味と、選択肢から「〜を選ぶ」という全く別の意味がある。", "groups": ["match_suit"], "etymology": "go（行く）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「〜に合う／〜を選ぶ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 91, "stage": 2, "verb": "stay together", "meaning": "一緒にいる、離れずにいる", "def": "to remain with each other", "ex1": "Through every hardship, the two of them managed to stay together.", "ja1": "あらゆる困難を経ても、その二人はなんとか一緒にいられた。", "ex2": "The team stayed together even after the reorganization.", "ja2": "組織再編の後もチームは離れずにいた。", "note": "", "nuance": "remain together(改まった表現)より口語的。break up（別れる）の反対で、関係を維持することを表す。", "groups": ["relationship_harmony"], "etymology": "stay（とどまる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「一緒にいる、離れずにいる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 92, "stage": 2, "verb": "get around", "meaning": "（あちこち）移動する／（噂が）広まる", "def": "to travel from place to place; to spread among people", "ex1": "He's lived here so long that he can get around the city with his eyes closed.", "ja1": "彼はここに長く住んでいるので、目をつぶってでも街を移動できるほどだ。", "ex2": "News of the merger got around quickly.", "ja2": "合併の話はすぐに広まった。", "note": "Stage 3 に別語義あり", "nuance": "move around（動き回る、より一般的）とほぼ同義。get around*2（規制を回避する）とは別の意味なので文脈で判断する。", "groups": [], "etymology": "get（得る・～になる）＋around（周りに）\n→ 一点に留まらず広い範囲を巡っていくイメージ\n→ そこから「（あちこち）移動する／（噂が）広まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 93, "stage": 2, "verb": "get to*2", "meaning": "〜する機会を得る", "def": "to have the opportunity to do something", "ex1": "After years of trying, she finally got to travel to Japan.", "ja1": "何年も挑戦した末、彼女はついに日本へ行く機会を得た。", "ex2": "I got to present at the annual conference.", "ja2": "年次カンファレンスで発表する機会をもらった。", "note": "Stage 1 の get to（到着する）と区別", "nuance": "have the opportunity to(改まった言い方)より口語的。get to doで「〜する機会に恵まれる」という前向きなニュアンスを持つ。", "groups": ["get_to_senses"], "etymology": "get（得る・～になる）＋to（～へ）\n→ やりたいことの方向へ手が届くイメージ\n→ そこから「〜する機会を得る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 94, "stage": 2, "verb": "listen up", "meaning": "注目して聞く", "def": "to pay attention to what is about to be said", "ex1": "The coach clapped twice and shouted, \"Listen up, everyone!\"", "ja1": "コーチは2回手を叩いて「みんな、注目して聞いて！」と叫んだ。", "ex2": "Listen up, I'll explain the new safety rules.", "ja2": "聞いてください、新しい安全ルールを説明します。", "note": "通常は命令形で使う", "nuance": "listen(単に聞く)より、注意を引くための命令調の強い表現。pay attention（注意を払う）とほぼ同義だが、より直接的。", "groups": ["imperative_expr"], "etymology": "listen（聞く）＋up（上へ）\n→ 声や集中力を上向きに高めるイメージ\n→ そこから「注目して聞く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 95, "stage": 2, "verb": "stand up*2", "meaning": "（約束を）すっぽかす", "def": "to fail to meet someone as arranged", "ex1": "He stood her up on their first date, and she never gave him a second chance.", "ja1": "彼は初デートで彼女をすっぽかし、彼女は二度目のチャンスをくれなかった。", "ex2": "The supplier stood us up for the second meeting.", "ja2": "その業者は2回目の打ち合わせをすっぽかした。", "note": "目的語は人（stand someone up）", "nuance": "約束をすっぽかす、相手に対して失礼な行為を表す。", "groups": [], "etymology": "stand（立つ）＋up（上へ）\n→ 相手を待たせたまま約束が宙に浮いてしまうイメージ\n→ そこから「（約束を）すっぽかす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 96, "stage": 2, "verb": "see off", "meaning": "見送る", "def": "to go with someone to their point of departure to say goodbye", "ex1": "We waved from the platform as we saw her off on the train.", "ja1": "電車で彼女を見送る際、私たちはホームから手を振った。", "ex2": "We saw the visitors off at the entrance.", "ja2": "来客を入口で見送った。", "note": "", "nuance": "say goodbye(単なる別れの挨拶)より、空港や駅で見送る「行為」そのものを表す。", "groups": [], "etymology": "see（見る）＋off（離れて）\n→ 離れていく相手を見届けるイメージ\n→ そこから「見送る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 97, "stage": 2, "verb": "meet up", "meaning": "待ち合わせて会う", "def": "to meet someone at an arranged time and place", "ex1": "Let's meet up at the café near the station around noon.", "ja1": "お昼頃、駅近くのカフェで待ち合わせよう。", "ex2": "Let's meet up before the client meeting to align.", "ja2": "顧客との会議前にすり合わせのため会いましょう。", "note": "", "nuance": "meet(単に会う)より、事前に約束して「待ち合わせる」というニュアンスが強い。get togetherとほぼ同義。", "groups": ["gather"], "etymology": "meet（会う）＋up（上へ）\n→ 別々にいた者同士が一点に集まって合流するイメージ\n→ そこから「待ち合わせて会う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(10,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 98, "stage": 2, "verb": "look back on", "meaning": "振り返る", "def": "to think about something that happened in the past", "ex1": "Looking back on it now, quitting that job was the best decision I ever made.", "ja1": "今振り返ると、あの仕事を辞めたのは人生で一番良い決断だった。", "ex2": "Looking back on the project, we learned a lot.", "ja2": "プロジェクトを振り返ると、多くを学んだ。", "note": "", "nuance": "remember(単に思い出す)より、過去の出来事を意識的に「振り返って考える」という内省的なニュアンスを含む。", "groups": ["reflect_step_back"], "etymology": "look（見る）＋back（後ろ・元へ）＋on（接触・継続）\n→ 元の場所や状態に戻るイメージ\n→ そこから「振り返る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 99, "stage": 2, "verb": "give out*2", "meaning": "尽きる、（機械が）壊れる", "def": "to run out; to stop working properly", "ex1": "Halfway through the marathon, the free water gave out completely.", "ja1": "マラソンの途中で、無料の水がすっかり尽きてしまった。", "ex2": "The old server finally gave out last week.", "ja2": "古いサーバーが先週ついに動かなくなった。", "note": "Stage 2 の give out（配る）と区別", "nuance": "run out of(〜を切らす、原因側の視点)とは異なり、give out*2は主語が「（在庫や機械が）尽きる、壊れる」という結果側の視点。", "groups": ["break_malfunction"], "etymology": "give（与える）＋out（外へ）\n→ 内側にあった力や在庫が外へ出尽くして、空っぽになるイメージ\n→ そこから「尽きる、（機械が）壊れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 100, "stage": 2, "verb": "pay for", "meaning": "〜の代金を払う、負担する", "def": "to pay the cost of something", "ex1": "We split the bill, but he insisted on paying for dessert.", "ja1": "会計は割り勘にしたが、彼はデザート代を払うと言い張った。", "ex2": "The company pays for the training courses.", "ja2": "会社が研修費用を負担する。", "note": "", "nuance": "buy(単に買う)より、支払いの「負担・責任」に焦点がある。cover the cost（費用を賄う）と似ている。", "groups": ["pay_related"], "etymology": "pay（払う）＋for（求めて）\n→ 受け取った物に見合う対価を差し出すイメージ\n→ そこから「〜の代金を払う、負担する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 101, "stage": 2, "verb": "put up*2", "meaning": "（人を）泊める", "def": "to let someone stay at your home or arrange lodging", "ex1": "They put us up for the night after our flight got cancelled.", "ja1": "フライトがキャンセルになったあと、彼らは一晩泊めてくれた。", "ex2": "The company put us up in a hotel near the site.", "ja2": "会社は現場近くのホテルに宿泊を手配してくれた。", "note": "Stage 1 の put up と区別", "nuance": "let someone stay(改まった表現)より口語的。give someone a place to sleepとほぼ同義。", "groups": ["put_up_senses"], "etymology": "put（置く）＋up（上へ）\n→ 一時的に住む場所を提供して受け入れるイメージ\n→ そこから「（人を）泊める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-8,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 102, "stage": 2, "verb": "hang out", "meaning": "ぶらぶら過ごす、一緒に時間を過ごす", "def": "to spend time relaxing, especially with other people", "ex1": "We used to hang out at that diner every Friday after school.", "ja1": "私たちは毎週金曜、放課後にあのダイナーでよくたむろしていた。", "ex2": "The team hung out together after the release party.", "ja2": "リリースの打ち上げの後、チームで一緒に過ごした。", "note": "", "nuance": "spend time with（時間を過ごす、より一般的）とほぼ同義だが、hang outは特にリラックスした気軽な時間を指す。", "groups": ["socialize_catch_up"], "etymology": "hang（掛ける）＋out（外へ）\n→ 家の外で誰かと時間を共有するイメージ\n→ そこから「ぶらぶら過ごす、一緒に時間を過ごす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 452, "stage": 3, "verb": "throw out", "meaning": "捨てる／（案を）却下する", "def": "to discard something; to reject an idea or proposal", "ex1": "He threw out the idea before I even finished explaining it.", "ja1": "私が説明し終わる前に、彼はそのアイデアを却下した。", "ex2": "The committee threw out our first proposal.", "ja2": "委員会は我々の最初の提案を却下した。", "note": "", "nuance": "throw away(物を捨てる)とは違い、こちらは「アイデアや提案を却下する」という比喩的な意味で使われることが多い。", "groups": ["discard"], "etymology": "throw（投げる）＋out（外へ）\n→ いらない物や選択肢を内側から外へ弾き出すイメージ\n→ そこから「捨てる／（案を）却下する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 103, "stage": 3, "verb": "come around", "meaning": "立ち寄る／考えを変えて同意する", "def": "to visit someone; to change your opinion and agree", "ex1": "She was against the plan at first, but she came around after seeing the numbers.", "ja1": "彼女は最初その計画に反対していたが、数字を見て考えを変えた。", "ex2": "He finally came around to our way of thinking.", "ja2": "彼はついに我々の考え方に同意した。", "note": "Stage 4 / 5 に別語義あり", "nuance": "visit(単に訪れる)より軽く、ふらっと立ち寄るニュアンス。come around（考えを変える）という別の意味もある。", "groups": ["come_around_senses"], "etymology": "come（来る）＋around（周りに）\n→ 一周して元の考えに戻ってくるイメージ\n→ そこから「立ち寄る／考えを変えて同意する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 104, "stage": 3, "verb": "take in", "meaning": "理解する、頭に入れる", "def": "to understand and absorb information", "ex1": "The lecture was so fast that I could barely take in half of it.", "ja1": "講義が速すぎて、半分も頭に入らなかった。", "ex2": "It took a while to take in all the requirements.", "ja2": "要件をすべて把握するのに時間がかかった。", "note": "Stage 4 に別語義あり", "nuance": "understand(単に理解する)より、情報を「吸収して自分のものにする」というプロセスを強調する。absorbと似たニュアンス。", "groups": ["understand"], "etymology": "take（取る）＋in（中へ）\n→ 情報を頭の内側に取り込んで収めるイメージ\n→ そこから「理解する、頭に入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 105, "stage": 3, "verb": "try out", "meaning": "試してみる", "def": "to test something to see if it works or if you like it", "ex1": "Before buying, I always try out the mattress by lying on it for ten minutes.", "ja1": "買う前に、いつもマットレスに10分横になって試してみる。", "ex2": "We tried out the tool in a small pilot project.", "ja2": "小規模なパイロットでそのツールを試した。", "note": "", "nuance": "test(改まった試験)より軽く、実際に使ってみて確かめるという日常的なニュアンス。sample（試食・試用する）と似ている。", "groups": [], "etymology": "try（試す）＋out（外へ）\n→ 頭の中だけでなく、実際に外の場で試してみるイメージ\n→ そこから「試してみる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 106, "stage": 3, "verb": "turn into", "meaning": "〜に変わる、〜に発展する", "def": "to change or develop into something else", "ex1": "What started as a small argument turned into a full-blown fight.", "ja1": "小さな口論として始まったものが、本格的な喧嘩に発展した。", "ex2": "A small bug turned into a major incident.", "ja2": "小さな不具合が重大障害に発展した。", "note": "", "nuance": "become(単になる)より、変化の過程や発展を強調する。change into（変化する、より一般的）とほぼ同義。", "groups": [], "etymology": "turn（向きを変える）＋into（中へ変化）\n→ 元の姿から別の状態の中へと移り変わるイメージ\n→ そこから「〜に変わる、〜に発展する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 107, "stage": 3, "verb": "watch out", "meaning": "気をつける、注意する", "def": "to be careful about a danger or problem", "ex1": "Watch out! That step is loose and someone already fell once.", "ja1": "気をつけて！その段差はぐらついていて、もう一度誰かがそこで転んでいる。", "ex2": "Watch out for hidden costs in the contract.", "ja2": "契約書の隠れたコストに注意してください。", "note": "", "nuance": "be careful(単に気をつける)より、危険が迫っている場面での強い警告のニュアンスがある。look out forの形で「〜に注意する」とも使う。", "groups": ["be_careful"], "etymology": "watch（見張る）＋out（外へ）\n→ 身の回りの外側にある危険を見つけようと目を光らせるイメージ\n→ そこから「気をつける、注意する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 108, "stage": 3, "verb": "get together*2", "meaning": "（物・情報を）まとめる", "def": "to gather things or information into one place", "ex1": "Can you get together all the receipts before the accountant arrives?", "ja1": "会計士が来る前に、レシートを全部まとめておいてもらえる？", "ex2": "Could you get the figures together before the meeting?", "ja2": "会議の前に数値をまとめてもらえますか。", "note": "Stage 2 の get together（集まる）と区別", "nuance": "put together(組み立てる、より一般的)と似ているが、get together*2は資料や情報を「一箇所にまとめる」場面でよく使う。", "groups": ["organize"], "etymology": "get（得る・～になる）＋together（一つに）\n→ 散らばっていた物を一つに寄せ集めるイメージ\n→ そこから「（物・情報を）まとめる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 109, "stage": 3, "verb": "make from", "meaning": "（原料）から作る", "def": "to produce something from a raw material that is changed in the process", "ex1": "This bread is made from just flour, water, and salt.", "ja1": "このパンは小麦粉と水と塩だけから作られている。", "ex2": "This packaging is made from recycled paper.", "ja2": "この包装材は再生紙から作られている。", "note": "原料が原形をとどめない場合", "nuance": "made ofが「材料そのもの」を表すのに対し、made fromは「原型が変化して作られた」材料を表す（例: 木材から作った紙）。", "groups": ["made_of_from"], "etymology": "make（作る）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「（原料）から作る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 110, "stage": 3, "verb": "make of", "meaning": "（材料）でできている", "def": "to be composed of a material that is still recognizable", "ex1": "The old bridge is made of stone that's over two hundred years old.", "ja1": "その古い橋は200年以上前の石でできている。", "ex2": "The casing is made of aluminum.", "ja2": "筐体はアルミでできている。", "note": "材料が見て分かる場合。make from と対比で覚える", "nuance": "材料が見た目にそのまま残る場合に使う（木製の机）。make fromとの対比が重要。", "groups": ["made_of_from"], "etymology": "make（作る）＋of（～の）\n→ 対象を分離・限定するイメージ\n→ そこから「（材料）でできている」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 111, "stage": 3, "verb": "break up", "meaning": "別れる／解散する", "def": "to end a relationship; for a group to separate", "ex1": "They broke up right before the trip they'd been planning for months.", "ja1": "彼らは何ヶ月も計画していた旅行の直前に別れた。", "ex2": "The meeting broke up at noon.", "ja2": "会議は正午に散会した。", "note": "Stage 3 の break up*2 と区別", "nuance": "split up(改まった別れ・分裂)とほぼ同義。get together（付き合い始める）の反対。", "groups": ["break_up_apart"], "etymology": "break（壊す・分ける）＋up（上へ）\n→ 一つだったまとまりが上下にバラバラに壊れるイメージ\n→ そこから「別れる／解散する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 112, "stage": 3, "verb": "get back", "meaning": "戻る、帰る", "def": "to return to a place", "ex1": "I won't get back until well after midnight tonight.", "ja1": "今夜は深夜過ぎまで戻れないと思う。", "ex2": "I'll get back to the office after the site visit.", "ja2": "現地訪問の後オフィスに戻ります。", "note": "Stage 3 に get back*2 あり", "nuance": "come back(戻ってくる、聞き手側の視点)とほぼ同義だが、get backは「帰宅する」場面でよく使われる。", "groups": ["return"], "etymology": "get（得る・～になる）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「戻る、帰る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 113, "stage": 3, "verb": "bring up", "meaning": "（話題を）持ち出す", "def": "to mention a subject in conversation", "ex1": "I wasn't going to mention it, but she brought up the loan first.", "ja1": "言うつもりはなかったのに、彼女の方から先にその借金の話を持ち出した。", "ex2": "She brought up the budget issue in the meeting.", "ja2": "彼女は会議で予算の問題を持ち出した。", "note": "Stage 5 に別語義あり", "nuance": "mention(単に言及する)より、あえて「話題として持ち出す」という意図的なニュアンスを含む。", "groups": ["bring_up_senses"], "etymology": "bring（持ってくる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（話題を）持ち出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 114, "stage": 3, "verb": "take out", "meaning": "取り出す、持ち出す", "def": "to remove something from a place or container", "ex1": "He took out his notebook and started scribbling ideas immediately.", "ja1": "彼はノートを取り出すと、すぐにアイデアを書き殴り始めた。", "ex2": "He took out his laptop and started the demo.", "ja2": "彼はノートPCを取り出してデモを始めた。", "note": "Stage 7 に別語義あり", "nuance": "take away(持ち去る、より一般的)と似ているが、take outは「取り出す」「持ち出す」「異性を誘って外出する」など複数の意味を持つ。", "groups": ["take_out_senses"], "etymology": "take（取る）＋out（外へ）\n→ 中にしまってあった物を外へ取り出すイメージ\n→ そこから「取り出す、持ち出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 115, "stage": 3, "verb": "give away", "meaning": "ただであげる／（秘密を）漏らす", "def": "to give something for free; to reveal something secret", "ex1": "We're giving away all the furniture since the new apartment is smaller.", "ja1": "新しい部屋が狭くなるので、家具は全部あげてしまうことにした。", "ex2": "Don't give away the pricing before the negotiation.", "ja2": "交渉の前に価格を漏らさないでください。", "note": "", "nuance": "give(単に与える)より、無償で「あげてしまう」というニュアンス。reveal（秘密を漏らす）という別の意味もある。", "groups": ["reveal_secret"], "etymology": "give（与える）＋away（遠くへ）\n→ 自分の手元から離して相手に渡すイメージ\n→ そこから「ただであげる／（秘密を）漏らす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 116, "stage": 3, "verb": "look out", "meaning": "注意する、用心する", "def": "to be careful and pay attention to possible danger", "ex1": "Look out for scammers calling about your \"unpaid taxes.\"", "ja1": "「未払いの税金」について電話してくる詐欺師に注意してください。", "ex2": "Look out for errors in the migrated data.", "ja2": "移行データの誤りに注意してください。", "note": "watch out とほぼ同義", "nuance": "watch out（気をつける、より一般的）とほぼ同義。look out for the danger（危険に用心する）の形でよく使う。", "groups": ["be_careful"], "etymology": "look（見る）＋out（外へ）\n→ 身の回りの外側にある危険を見つけようと目を光らせるイメージ\n→ そこから「注意する、用心する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 117, "stage": 3, "verb": "keep away", "meaning": "近づかない、遠ざける", "def": "to stay at a distance; to prevent from coming near", "ex1": "The sign said to keep away from the edge of the cliff.", "ja1": "崖の端には近づかないようにと標識に書いてあった。", "ex2": "Keep unauthorized staff away from the server room.", "ja2": "権限のない社員をサーバー室に近づけないでください。", "note": "", "nuance": "stay away from（離れている、より一般的）とほぼ同義。keep someone awayで「人を近づけさせない」という他動詞的用法もある。", "groups": ["avoid_stay_away"], "etymology": "keep（保つ）＋away（遠くへ）\n→ 対象との間に距離を保ち続けるイメージ\n→ そこから「近づかない、遠ざける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 118, "stage": 3, "verb": "fill up", "meaning": "いっぱいにする、満席になる", "def": "to make or become completely full", "ex1": "The stadium filled up an hour before kickoff.", "ja1": "キックオフの1時間前にはスタジアムは満席になった。", "ex2": "The seminar filled up within two days.", "ja2": "セミナーは2日で満席になった。", "note": "", "nuance": "fillが単に「満たす」意味に対し、fill upは「容量いっぱいまで満たす」ことを強調する。満席になる状況にも使う。", "groups": [], "etymology": "fill（満たす）＋up（上へ）\n→ 容量の上限まで満たして満杯にするイメージ\n→ そこから「いっぱいにする、満席になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(2,32,32)\"><path d=\"M22 26 L24 46 Q24 48 26 48 L38 48 Q40 48 40 46 L42 26\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M18 26 L46 26\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 14 L32 22 M28 18 L32 22 L36 18\" stroke=\"#C79A3D\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 119, "stage": 3, "verb": "work out*2", "meaning": "計算する、算出する", "def": "to calculate an amount or find a solution", "ex1": "It took a whole afternoon to work out how much everyone owed.", "ja1": "みんながいくら払うべきか計算するのに、午後まるまるかかった。", "ex2": "We worked out the total cost of ownership.", "ja2": "総保有コスト（TCO）を算出した。", "note": "Stage 2 の work out と区別", "nuance": "calculate(改まった計算)より口語的。figure out（解決する、理解する）とは異なる意味なので注意。", "groups": [], "etymology": "work（働く・作用させる）＋out（外へ）\n→ 途中で終わらせず、最後までとことん計算・処理しきるイメージ\n→ そこから「計算する、算出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 120, "stage": 3, "verb": "run over", "meaning": "（車が）ひく／時間を超過する", "def": "to hit with a vehicle; to exceed a time limit", "ex1": "We ran over on time during the meeting and missed our next appointment.", "ja1": "会議で時間を超過してしまい、次の予定に間に合わなかった。", "ex2": "The meeting ran over by twenty minutes.", "ja2": "会議は20分超過した。", "note": "", "nuance": "hit(単にぶつかる)より、車が「上を通過してひく」という具体的な動作を表す。run late（時間に遅れる）とは別の意味で「予定時間を超過する」場合にも使う。", "groups": [], "etymology": "run（走る）＋over（越えて）\n→ 限度や物を越えてしまうイメージ\n→ そこから「（車が）ひく／時間を超過する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 121, "stage": 3, "verb": "tell off", "meaning": "叱る、きつく注意する", "def": "to speak angrily to someone about something they did wrong", "ex1": "The coach told the team off for showing up late to practice.", "ja1": "コーチは練習に遅刻したチームをきつく叱った。", "ex2": "The manager told him off for missing the deadline.", "ja2": "上司は納期を守らなかったことで彼を叱った。", "note": "", "nuance": "scold(改まった叱責)より口語的。yell at（怒鳴る）よりは、言葉できつく注意するニュアンス。", "groups": ["scold_yell"], "etymology": "tell（伝える）＋off（離れて）\n→ 相手をぴしゃりと切り離すように厳しく言うイメージ\n→ そこから「叱る、きつく注意する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 122, "stage": 3, "verb": "turn up", "meaning": "（音量・温度を）上げる", "def": "to increase the volume, heat, or power of something", "ex1": "Could you turn up the volume? I can barely hear the movie.", "ja1": "音量を上げてもらえる？映画がほとんど聞こえない。", "ex2": "Could you turn up the microphone volume?", "ja2": "マイクの音量を上げていただけますか。", "note": "元リストの turn up/down を分割。Stage 1 の turn up（現れる）と別語義", "nuance": "turn up(音量・明るさを上げる)はturn down（下げる）の反対。show up（現れる）とは全く別の意味の多義語。", "groups": ["volume"], "etymology": "turn（向きを変える）＋up（上へ）\n→ つまみや数値を上向きに高めるイメージ\n→ そこから「（音量・温度を）上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 123, "stage": 3, "verb": "turn down", "meaning": "（音量・温度を）下げる", "def": "to reduce the volume, heat, or power of something", "ex1": "Please turn down the heater; it's like a sauna in here.", "ja1": "暖房を下げてください、ここサウナみたいに暑いです。", "ex2": "Please turn down the volume during the conference call.", "ja2": "電話会議中は音量を下げてください。", "note": "元リストの turn up/down を分割。Stage 5 の turn down（断る）と別語義", "nuance": "turn upの反対。lower（下げる、より一般的）より、つまみやスイッチを回す動作を伴う日常表現。", "groups": ["volume"], "etymology": "turn（向きを変える）＋down（下へ）\n→ つまみや数値を下向きに絞るイメージ\n→ そこから「（音量・温度を）下げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 124, "stage": 3, "verb": "help out", "meaning": "手伝う、助ける", "def": "to help someone, especially when they are busy or in trouble", "ex1": "A stranger stopped to help out when our car broke down.", "ja1": "車が故障した時、見知らぬ人が手伝おうと車を止めてくれた。", "ex2": "He helped out on the project during the busy season.", "ja2": "繁忙期に彼はプロジェクトを手伝ってくれた。", "note": "", "nuance": "help(単に手伝う)とほぼ同義だが、help outは特に困っている人を「一時的に助ける」場面でよく使う。", "groups": ["help_cover"], "etymology": "help（助ける）＋out（外へ）\n→ 困っている人の外側から手を差し伸べるイメージ\n→ そこから「手伝う、助ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 125, "stage": 3, "verb": "go over", "meaning": "見直す、詳しく確認する", "def": "to review or examine something carefully", "ex1": "Let's go over the numbers one more time before the presentation.", "ja1": "プレゼンの前に、もう一度数字を見直しましょう。", "ex2": "Please go over the contract before signing.", "ja2": "署名の前に契約書をよく確認してください。", "note": "", "nuance": "look through(ざっと目を通す)より丁寧に、詳しく見直す・確認するニュアンス。reviewとほぼ同義。", "groups": ["review_check"], "etymology": "go（行く）＋over（越えて）\n→ 端から端まで一通り目を通すイメージ\n→ そこから「見直す、詳しく確認する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 126, "stage": 3, "verb": "look forward to", "meaning": "楽しみにする", "def": "to feel pleased about something that is going to happen", "ex1": "I've been looking forward to this vacation for the whole year.", "ja1": "この一年、この休暇をずっと楽しみにしていた。", "ex2": "I look forward to working with you.", "ja2": "ご一緒できるのを楽しみにしております。", "note": "to は前置詞。後ろは動名詞（-ing）", "nuance": "expect(単に予期する)より、楽しみな気持ちを込めて「待ち望む」ニュアンスが強い。anticipateより口語的。", "groups": [], "etymology": "look（見る）＋forward（前へ）＋to（～へ）\n→ 前方に進むイメージ\n→ そこから「楽しみにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 127, "stage": 3, "verb": "get back*2", "meaning": "取り戻す、返してもらう", "def": "to receive something again after not having it", "ex1": "I finally got back the money he'd owed me for three years.", "ja1": "3年間彼が借りていたお金を、ようやく取り戻した。", "ex2": "We got back the deposit after the contract ended.", "ja2": "契約終了後に保証金を返してもらった。", "note": "Stage 3 の get back（戻る）と区別", "nuance": "get back(単に戻る)とは別の意味で、こちらは失った物やお金を「取り戻す」ことを表す。", "groups": ["return"], "etymology": "get（得る・～になる）＋back（後ろ・元へ）\n→ 離れていた物を自分の手元へ引き戻すイメージ\n→ そこから「取り戻す、返してもらう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 128, "stage": 3, "verb": "get around*2", "meaning": "（問題・規則を）回避する", "def": "to find a way to deal with or avoid a problem", "ex1": "There's a loophole that lets you get around the age restriction.", "ja1": "年齢制限を回避できる抜け道がある。", "ex2": "We got around the limitation by using a workaround.", "ja2": "回避策を用いてその制約を回避した。", "note": "Stage 2 の get around（移動する）と区別", "nuance": "avoid(単に避ける)より、規則や問題を「巧妙にすり抜ける」という工夫を含む。get around（あちこち移動する）とは別の意味なので注意。", "groups": ["avoid_evade"], "etymology": "get（得る・～になる）＋around（周りに）\n→ 正面を避けて周りから回り込むイメージ\n→ そこから「（問題・規則を）回避する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 129, "stage": 3, "verb": "go out with", "meaning": "（人と）付き合う", "def": "to have a romantic relationship with someone", "ex1": "They've been going out with each other since high school.", "ja1": "彼らは高校時代からずっと付き合っている。", "ex2": "Going out with a client can be a conflict of interest.", "ja2": "顧客と交際することは利益相反になりうる。", "note": "", "nuance": "date（付き合う、より一般的）とほぼ同義。go out（外出する）とは異なり、恋愛関係を表す。", "groups": ["dating_romance"], "etymology": "go（行く）＋out（外へ）＋with（一緒に）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「（人と）付き合う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 130, "stage": 3, "verb": "make out of", "meaning": "（材料）を使って作る", "def": "to create something using a particular material", "ex1": "She made a whole costume out of cardboard boxes.", "ja1": "彼女は段ボール箱だけで衣装を丸ごと作った。", "ex2": "We made a prototype out of spare parts.", "ja2": "余った部品で試作品を作った。", "note": "", "nuance": "made ofが素材そのものを表すのに対し、make out ofは「〜を使って何かを作り出す」という創造的な工程を強調する。", "groups": ["made_of_from"], "etymology": "make（作る）＋out（外へ）＋of（～の）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「（材料）を使って作る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 131, "stage": 3, "verb": "make into", "meaning": "〜に作り変える", "def": "to change something so that it becomes something else", "ex1": "We made the leftover vegetables into a big pot of soup.", "ja1": "余った野菜を大鍋のスープに作り変えた。", "ex2": "We made the report into a slide deck.", "ja2": "報告書をスライド資料に作り変えた。", "note": "", "nuance": "become（単になる）よりも、意図的に材料や状況を別の形に「作り変える」プロセスを表す。turn into（自然に変化する）とは能動性が異なる。", "groups": ["made_of_from"], "etymology": "make（作る）＋into（中へ変化）\n→ 元の材料を別の状態の中へ作り変えるイメージ\n→ そこから「〜に作り変える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 132, "stage": 3, "verb": "break up*2", "meaning": "細かく分ける、分割する", "def": "to divide something into smaller parts", "ex1": "The teacher broke up the class into groups of four.", "ja1": "先生はクラスを4人ずつのグループに分けた。", "ex2": "Let's break up the task into smaller steps.", "ja2": "作業を小さな工程に分割しましょう。", "note": "Stage 3 の break up（別れる）と区別", "nuance": "break up（人間関係の別れ）とは別の意味で、こちらは物やグループを「細かく分割する」ことを表す。divideより口語的。", "groups": ["break_into_parts"], "etymology": "break（壊す・分ける）＋up（上へ）\n→ 大きな物を上から下まで細かく分けて処理するイメージ\n→ そこから「細かく分ける、分割する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 133, "stage": 3, "verb": "bring back", "meaning": "持ち帰る、返す／思い出させる", "def": "to return something; to cause someone to remember", "ex1": "The smell of that candle brings back memories of my grandmother's house.", "ja1": "そのキャンドルの香りは祖母の家の思い出を呼び起こす。", "ex2": "He brought back several requests from the client.", "ja2": "彼は顧客から要望をいくつか持ち帰った。", "note": "", "nuance": "take back（返品する、返す）と似た形だが、bring backは「持ち帰る」「思い出させる」の意味で使われることが多い。", "groups": ["return"], "etymology": "bring（持ってくる）＋back（後ろ・元へ）\n→ 借りていた物を元の持ち主へ戻すイメージ\n→ そこから「持ち帰る、返す／思い出させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 134, "stage": 3, "verb": "take back", "meaning": "返品する／（発言を）撤回する", "def": "to return an item to a shop; to retract what you said", "ex1": "I want to take back what I said earlier — I was wrong.", "ja1": "さっき言ったことを撤回したい、私が間違っていた。", "ex2": "I take back what I said about the schedule.", "ja2": "スケジュールについて言ったことは撤回します。", "note": "Stage 5 に別語義あり", "nuance": "return（返品する、より一般的）とほぼ同義。take back your wordsで「発言を撤回する」という別の意味もある。", "groups": ["return_money"], "etymology": "take（取る）＋back（後ろ・元へ）\n→ 一度出した言葉を口の中へ引っ込めるイメージ\n→ そこから「返品する／（発言を）撤回する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 135, "stage": 3, "verb": "pick up*2", "meaning": "（技能・言語を）自然に身につける", "def": "to learn something without making a deliberate effort", "ex1": "Kids pick up new languages so much faster than adults do.", "ja1": "子供は大人よりずっと早く新しい言語を身につける。", "ex2": "He picked up Excel skills on the job.", "ja2": "彼は実務の中でExcelのスキルを身につけた。", "note": "Stage 2 の pick up（拾う・迎えに行く）と区別", "nuance": "learn（意識的に学ぶ）とは違い、pick upは特に子供が言語などを「自然に、無意識に身につける」ニュアンスを持つ。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 知識や技能を通りすがりに拾い上げるイメージ\n→ そこから「（技能・言語を）自然に身につける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 136, "stage": 3, "verb": "make up", "meaning": "でっちあげる、作り話をする", "def": "to invent a story, excuse, or explanation", "ex1": "He made up an excuse about traffic, but everyone knew he overslept.", "ja1": "彼は渋滞のせいだと作り話をしたが、みんな彼が寝坊したことを知っていた。", "ex2": "Don't make up numbers in the report.", "ja2": "報告書の数字をでっちあげないでください。", "note": "Stage 4 / 5 に別語義あり", "nuance": "invent（発明する、創造的）とは違い、make upは「事実でない話をでっちあげる」という否定的なニュアンスを含む。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 何もないところから話をでっち上げるイメージ\n→ そこから「でっちあげる、作り話をする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 137, "stage": 3, "verb": "come by", "meaning": "立ち寄る／手に入れる", "def": "to visit briefly; to obtain something", "ex1": "Good apartments like this one are hard to come by these days.", "ja1": "最近は、こんな良い部屋にはなかなか出会えない。", "ex2": "Good engineers are hard to come by.", "ja2": "優秀な技術者はなかなか得がたい。", "note": "", "nuance": "visit（訪れる、より一般的）より軽い。get（手に入れる）という意味では、come by somethingで「珍しい物を手に入れる」という表現になる。", "groups": ["visit_casually"], "etymology": "come（来る）＋by（そばを）\n→ 通りすがりにそばにある物を手に入れるイメージ\n→ そこから「立ち寄る／手に入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 138, "stage": 3, "verb": "put out", "meaning": "（火・明かりを）消す", "def": "to make a fire or light stop burning", "ex1": "Firefighters took hours to put out the blaze.", "ja1": "消防士たちがその火を消すのに何時間もかかった。", "ex2": "The staff put out the fire before it spread.", "ja2": "社員は延焼する前に火を消し止めた。", "note": "Stage 4 に別語義あり", "nuance": "turn off（スイッチで消す）とは違い、put outは火や明かりを「消す」動作、特に消火活動でよく使われる。", "groups": ["put_out_senses"], "etymology": "put（置く）＋out（外へ）\n→ 燃えている火を外へ追いやって消すイメージ\n→ そこから「（火・明かりを）消す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 139, "stage": 3, "verb": "calm down", "meaning": "落ち着く、落ち着かせる", "def": "to become or make someone become less angry or upset", "ex1": "Take a deep breath and calm down before you reply to that email.", "ja1": "そのメールに返信する前に、深呼吸して落ち着いて。", "ex2": "He calmed down after the client accepted the fix.", "ja2": "顧客が修正案を受け入れて彼は落ち着いた。", "note": "", "nuance": "relax（くつろぐ、より一般的）とは違い、calm downは興奮や怒りなど「高ぶった感情を鎮める」場面で使う。", "groups": ["calm_down"], "etymology": "calm（落ち着かせる）＋down（下へ）\n→ 高ぶっていた気持ちが静かに下がるイメージ\n→ そこから「落ち着く、落ち着かせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 140, "stage": 3, "verb": "look after", "meaning": "世話をする、面倒を見る", "def": "to take care of someone or something", "ex1": "My neighbor looks after my plants whenever I travel.", "ja1": "旅行に行くときはいつも、隣人が私の植物の世話をしてくれる。", "ex2": "She looks after three client accounts.", "ja2": "彼女は3社の顧客を担当している。", "note": "", "nuance": "take care of（世話をする、より一般的）とほぼ同義。watch（見張る）より、責任を持って面倒を見るニュアンスが強い。", "groups": [], "etymology": "look（見る）＋after（後を追って）\n→ 対象の後ろについていくイメージ\n→ そこから「世話をする、面倒を見る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/><path d=\"M9 3 L15 8 L9 13\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 141, "stage": 3, "verb": "call up", "meaning": "電話をかける", "def": "to telephone someone", "ex1": "I called up an old friend I hadn't spoken to in a decade.", "ja1": "10年間話していなかった旧友に電話をかけた。", "ex2": "Call up the vendor and confirm the delivery date.", "ja2": "業者に電話して納期を確認してください。", "note": "", "nuance": "call（単に電話する）とほぼ同義だが、call upはやや古風または改まった響きを持つことがある。", "groups": ["call_phone"], "etymology": "call（呼ぶ）＋up（上へ）\n→ 相手を呼び出して電話をつなげるイメージ\n→ そこから「電話をかける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 142, "stage": 3, "verb": "turn to", "meaning": "（人・物に）頼る", "def": "to go to someone or something for help or advice", "ex1": "When things got hard, she always turned to her older brother for advice.", "ja1": "つらい時、彼女はいつもお兄さんに相談していた。", "ex2": "When issues arise, we turn to the support team.", "ja2": "問題が起きたときはサポートチームを頼ります。", "note": "", "nuance": "rely on（頼る、より一般的）とほぼ同義。turn（向きを変える）から派生し、困った時に頼る相手や物に「向かう」イメージ。", "groups": ["rely_on"], "etymology": "turn（向きを変える）＋to（～へ）\n→ 困った時に頼れる相手の方向を向くイメージ\n→ そこから「（人・物に）頼る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 143, "stage": 3, "verb": "go by", "meaning": "（時が）過ぎる、通り過ぎる", "def": "to pass, especially of time", "ex1": "The years went by so fast that I barely noticed my kids growing up.", "ja1": "あっという間に年月が過ぎて、子供たちが育っていくのにほとんど気づかなかった。", "ex2": "Three weeks went by without a reply from the client.", "ja2": "顧客から返信がないまま3週間が過ぎた。", "note": "", "nuance": "pass（過ぎる、より一般的）とほぼ同義。go by quicklyで「あっという間に過ぎる」という時間の経過を表す。", "groups": [], "etymology": "go（行く）＋by（そばを）\n→ 時間がすぐそばを通り過ぎていくイメージ\n→ そこから「（時が）過ぎる、通り過ぎる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 144, "stage": 3, "verb": "put down*2", "meaning": "けなす、こきおろす", "def": "to criticize someone and make them feel bad about themselves", "ex1": "He has a bad habit of putting down other people's ideas in meetings.", "ja1": "彼は会議で人のアイデアをけなす悪い癖がある。", "ex2": "Putting down team members lowers morale.", "ja2": "メンバーをけなすと士気が下がる。", "note": "Stage 2 の put down（置く）と区別", "nuance": "criticize（批判する、より直接的）とは違い、put downは特に人前で相手を「見下すように貶める」ニュアンスを持つ。", "groups": ["put_down_senses"], "etymology": "put（置く）＋down（下へ）\n→ 相手の評価をわざと下へ落とすイメージ\n→ そこから「けなす、こきおろす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 145, "stage": 3, "verb": "keep out", "meaning": "立ち入らせない、締め出す", "def": "to prevent someone or something from entering", "ex1": "A tall fence keeps stray animals out of the garden.", "ja1": "高いフェンスが野良動物を庭に入れないようにしている。", "ex2": "The sign says \"Keep out\" for the construction area.", "ja2": "工事区域には「立入禁止」と表示されている。", "note": "", "nuance": "keep away（近づかない、自動詞的）とは違い、keep outは「立ち入らせない」という他動詞的な排除の意味。", "groups": ["keep_in_out"], "etymology": "keep（保つ）＋out（外へ）\n→ 対象を内側に入れず外側に留め置くイメージ\n→ そこから「立ち入らせない、締め出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 146, "stage": 3, "verb": "stay up", "meaning": "夜更かしする", "def": "to remain awake later than usual", "ex1": "We stayed up all night finishing the project the day before it was due.", "ja1": "締め切り前日、プロジェクトを終わらせるために徹夜した。", "ex2": "He stayed up to finish the proposal.", "ja2": "彼は提案書を仕上げるため夜更かしした。", "note": "", "nuance": "stay awake（起きている状態、より一般的）とは違い、stay upは「意図的に夜遅くまで起きている」ことを表す。", "groups": [], "etymology": "stay（とどまる）＋up（上へ）\n→ 眠らずに起きた状態を保ち続けるイメージ\n→ そこから「夜更かしする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 147, "stage": 3, "verb": "put back", "meaning": "元の場所に戻す", "def": "to return something to where it was", "ex1": "Please put the milk back in the fridge when you're done.", "ja1": "使い終わったら牛乳を冷蔵庫に戻しておいてください。", "ex2": "Please put back the file after copying it.", "ja2": "コピーの後はファイルを元に戻してください。", "note": "", "nuance": "put away（収納する）とは違い、put backは「元あった場所へ正確に戻す」ことを強調する。", "groups": ["return"], "etymology": "put（置く）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「元の場所に戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 148, "stage": 3, "verb": "put in", "meaning": "設置する／（時間・労力を）注ぐ", "def": "to install something; to devote time or effort", "ex1": "It took the plumber all day to put in the new water heater.", "ja1": "配管工が新しい給湯器を設置するのに一日かかった。", "ex2": "She put in a lot of hours on this proposal.", "ja2": "彼女はこの提案書に多くの時間を費やした。", "note": "Stage 4 に別語義あり", "nuance": "install（改まった設置）より口語的。put in effort（努力を注ぐ）という比喩的な使い方もある。", "groups": ["spend_time_effort"], "etymology": "put（置く）＋in（中へ）\n→ 装置などを内部に組み込むイメージ\n→ そこから「設置する／（時間・労力を）注ぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 149, "stage": 3, "verb": "stand for", "meaning": "〜の略である、〜を表す", "def": "to be an abbreviation of something; to represent", "ex1": "Nobody at the meeting could remember what the acronym stood for.", "ja1": "その会議では誰も、その略語が何を表しているか思い出せなかった。", "ex2": "\"SLA\" stands for service level agreement.", "ja2": "SLAはサービスレベル合意の略です。", "note": "Stage 7 に別語義あり", "nuance": "mean（意味する、より一般的）とは違い、stand forは特に「略語や記号が何を表すか」を説明する時に使う。", "groups": ["stand_for_senses"], "etymology": "stand（立つ）＋for（求めて）\n→ その略が指し示す意味の方を向くイメージ\n→ そこから「〜の略である、〜を表す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 150, "stage": 3, "verb": "pass out", "meaning": "気を失う", "def": "to become unconscious", "ex1": "The heat was so intense that one runner passed out near the finish line.", "ja1": "暑さがあまりに強く、ゴール付近でランナーの一人が気を失った。", "ex2": "One participant passed out during the long session.", "ja2": "長時間のセッション中に参加者が1名倒れた。", "note": "Stage 7 の pass out*2（配る）と区別", "nuance": "faint（改まった失神）とほぼ同義だが、pass outはより口語的でカジュアルな表現。", "groups": [], "etymology": "pass（通す・渡す）＋out（外へ）\n→ 意識がすっと体の外へ抜けていくイメージ\n→ そこから「気を失う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 151, "stage": 3, "verb": "check out*2", "meaning": "調べる、確認してみる", "def": "to examine or investigate something", "ex1": "Before you sign anything, check out the reviews online first.", "ja1": "何かにサインする前に、まずネットのレビューを確認してみて。", "ex2": "Let me check out the error log first.", "ja2": "まずエラーログを確認させてください。", "note": "Stage 2 の check out（チェックアウト）と区別", "nuance": "look into（詳しく調査する）よりも軽く、ちょっと確認してみるというカジュアルなニュアンス。check（確認する、より一般的）とほぼ同義。", "groups": ["review_check"], "etymology": "check（確認する）＋out（外へ）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「調べる、確認してみる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 152, "stage": 3, "verb": "break into", "meaning": "押し入る、侵入する", "def": "to enter a place by force, usually to steal", "ex1": "Someone broke into the office over the weekend and took two laptops.", "ja1": "週末に誰かがオフィスに侵入し、ノートパソコンを2台盗んだ。", "ex2": "Hackers broke into the company network.", "ja2": "ハッカーが社内ネットワークに侵入した。", "note": "", "nuance": "enter（改まった侵入）より直接的。invade（軍事的に侵略する）ほど大げさではなく、家や建物への不法侵入によく使う。", "groups": ["enter_various"], "etymology": "break（壊す・分ける）＋into（中へ変化）\n→ 許可なく力ずくで内部へ押し入るイメージ\n→ そこから「押し入る、侵入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 153, "stage": 4, "verb": "open up", "meaning": "開ける、開店・開設する", "def": "to open something; to start a shop or business", "ex1": "The new bakery on the corner just opened up last week.", "ja1": "角にできた新しいパン屋は先週開店したばかりだ。", "ex2": "We're opening up a new office in Osaka.", "ja2": "大阪に新しいオフィスを開設します。", "note": "", "nuance": "openの反対にはcloseがあるが、open upは特に新しい店や施設が「開業する」場面、または人が「心を開く」場面で使われる。", "groups": ["open_up_senses"], "etymology": "open（開く）＋up（上へ）\n→ 閉じていた物や場を上へ開くイメージ\n→ そこから「開ける、開店・開設する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 154, "stage": 4, "verb": "come around*2", "meaning": "意識を取り戻す", "def": "to become conscious again", "ex1": "It took the boxer almost a full minute to come around after the knockout.", "ja1": "そのボクサーはノックアウトされてから、意識を取り戻すのにほぼ1分かかった。", "ex2": "The employee came around before the ambulance arrived.", "ja2": "救急車が到着する前に社員は意識を取り戻した。", "note": "Stage 3 / 5 に別語義あり", "nuance": "wake up（自然に目覚める）とは違い、come around*2は気絶や麻酔から「意識を取り戻す」場面で使う。", "groups": ["come_around_senses"], "etymology": "come（来る）＋around（周りに）\n→ 意識がぐるっと一周して戻ってくるイメージ\n→ そこから「意識を取り戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 155, "stage": 4, "verb": "make up*2", "meaning": "仲直りする", "def": "to become friendly again after an argument", "ex1": "They fought for a week straight, but somehow made up by Sunday.", "ja1": "彼らは丸1週間喧嘩していたが、なぜか日曜には仲直りしていた。", "ex2": "The two teams made up after the heated discussion.", "ja2": "激しい議論の後、両チームは和解した。", "note": "Stage 3 の make up（でっちあげる）と区別", "nuance": "reconcile（改まった和解）より口語的。break up（別れる）の反対で、喧嘩の後に「仲直りする」ことを表す。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 閉ざしていた心を上向きに開いて向き合うイメージ\n→ そこから「仲直りする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 156, "stage": 4, "verb": "open up*2", "meaning": "心を開いて話す", "def": "to talk freely about your feelings", "ex1": "It took a lot of trust for him to finally open up about his past.", "ja1": "彼が過去について心を開いて話すまでには、大きな信頼が必要だった。", "ex2": "The junior members opened up in the one-on-one.", "ja2": "1on1で若手メンバーが本音を話してくれた。", "note": "", "nuance": "talk（単に話す）とは違い、open up*2は普段話さないことを「打ち明ける」という心理的な壁を越えるニュアンスを含む。", "groups": ["open_up_senses"], "etymology": "open（開く）＋up（上へ）\n→ 閉ざしていた心を上向きに開いて向き合うイメージ\n→ そこから「心を開いて話す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 157, "stage": 4, "verb": "hang on", "meaning": "少し待つ、持ちこたえる", "def": "to wait for a short time; to hold firmly", "ex1": "Hang on, I need to grab my coat before we leave.", "ja1": "ちょっと待って、出る前にコートを取ってくる。", "ex2": "Hang on while I check the system status.", "ja2": "システムの状態を確認しますので少々お待ちください。", "note": "", "nuance": "hold on（少し待つ）はwait（待つ、より一般的）よりカジュアルで、電話中によく使われる。hold out（持ちこたえる）と似た意味でも使う。", "groups": ["wait"], "etymology": "hang（掛ける）＋on（接触・継続）\n→ 接続やつながりをそのまま保ち続けるイメージ\n→ そこから「少し待つ、持ちこたえる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(1,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 158, "stage": 4, "verb": "pick on", "meaning": "いじめる、目の敵にする", "def": "to treat someone unfairly or criticize them repeatedly", "ex1": "Kids used to pick on him for his accent, but he never let it show.", "ja1": "子供たちはよく彼の訛りをからかっていたが、彼はそれを表に出さなかった。", "ex2": "Don't pick on one member when the whole team missed the target.", "ja2": "チーム全体が未達なのに一人だけを責めないでください。", "note": "", "nuance": "bully（改まったいじめ）より口語的。tease（からかう、より軽い）よりは深刻な嫌がらせのニュアンスを持つことがある。", "groups": ["bully_mistreat"], "etymology": "pick（つまむ・選ぶ）＋on（接触・継続）\n→ 特定の相手に狙いを定めて働きかけ続けるイメージ\n→ そこから「いじめる、目の敵にする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 159, "stage": 4, "verb": "stay away", "meaning": "近寄らない", "def": "to avoid going near someone or something", "ex1": "The vet told us to stay away from other dogs until the vaccine kicks in.", "ja1": "獣医は、ワクチンが効くまで他の犬に近づかないようにと言った。", "ex2": "Stay away from the production server without approval.", "ja2": "承認なしに本番サーバーに触れないでください。", "note": "", "nuance": "keep away from（近づかない、より一般的）とほぼ同義だが、stay awayは自動詞的に「自分から離れている」ことを表す。", "groups": ["avoid_stay_away"], "etymology": "stay（とどまる）＋away（遠くへ）\n→ 自分から距離を取り、近寄らせないイメージ\n→ そこから「近寄らない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 160, "stage": 4, "verb": "keep in", "meaning": "中にとどめておく、外に出さない", "def": "to keep something or someone inside", "ex1": "We kept the puppy in the yard so it wouldn't run into the street.", "ja1": "子犬が道路に飛び出さないよう、庭の中にとどめておいた。", "ex2": "Please keep this information in the team for now.", "ja2": "この情報は当面チーム内にとどめてください。", "note": "", "nuance": "keep out（立ち入らせない）の反対で、keep inは中にある物や人を「外に出さないよう留めておく」ことを表す。", "groups": ["keep_in_out"], "etymology": "keep（保つ）＋in（中へ）\n→ 外に出さず内側に閉じ込めておくイメージ\n→ そこから「中にとどめておく、外に出さない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 161, "stage": 4, "verb": "take in*2", "meaning": "だます、欺く", "def": "to deceive someone, usually in the passive form", "ex1": "The scam artist took in dozens of investors before anyone noticed.", "ja1": "その詐欺師は誰かが気づく前に、何十人もの投資家をだました。", "ex2": "Several clients were taken in by the fake invoice.", "ja2": "何社かの顧客が偽の請求書にだまされた。", "note": "be taken in by の形が多い。Stage 3 の take in と区別", "nuance": "deceive（改まった欺き）より口語的。take in*2は、話や見た目に「だまされる」受動的な場面でよく使われる。", "groups": ["deceive"], "etymology": "take（取る）＋in（中へ）\n→ 相手の話を鵜呑みにして取り込まれてしまうイメージ\n→ そこから「だます、欺く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 162, "stage": 4, "verb": "call off", "meaning": "中止する", "def": "to cancel an event or plan", "ex1": "The concert was called off at the last minute due to the storm.", "ja1": "その嵐のせいで、コンサートは土壇場で中止になった。", "ex2": "The client called off the meeting at short notice.", "ja2": "顧客は直前に会議を中止した。", "note": "", "nuance": "cancel（改まったキャンセル）より口語的。postpone（延期する）とは違い、call offは完全に「中止する」ことを表す。", "groups": ["cancel_stop"], "etymology": "call（呼ぶ）＋off（離れて）\n→ 予定していたことを切り離して取りやめるイメージ\n→ そこから「中止する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(11,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 163, "stage": 4, "verb": "turn around", "meaning": "向きを変える／（業績を）好転させる", "def": "to face the other way; to improve a bad situation", "ex1": "Sales figures turned around completely after the new manager took over.", "ja1": "新しいマネージャーが就任してから、売上は完全に好転した。", "ex2": "The new manager turned the business around in a year.", "ja2": "新しい責任者は1年で事業を立て直した。", "note": "", "nuance": "improveが単に「改善する」意味なのに対し、turn aroundは業績や状況が「完全に好転する」という劇的な変化を強調する。", "groups": ["turn_direction"], "etymology": "turn（向きを変える）＋around（周りに）\n→ 状況や向きをぐるりと転換させるイメージ\n→ そこから「向きを変える／（業績を）好転させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 164, "stage": 4, "verb": "get by", "meaning": "何とかやっていく", "def": "to manage to live or continue with what you have", "ex1": "On a student's budget, we somehow got by on rice and eggs for a month.", "ja1": "学生の予算で、1ヶ月ご飯と卵だけで何とかやっていった。", "ex2": "We got by with two engineers until the new hire joined.", "ja2": "新人が入るまでエンジニア2名で何とか回した。", "note": "", "nuance": "manage（何とか対処する、より一般的）とほぼ同義。survive（生き延びる）ほど深刻ではなく、日々の生活を切り盛りするニュアンス。", "groups": [], "etymology": "get（得る・～になる）＋by（そばを）\n→ 最低限のそばのラインで何とかやり過ごすイメージ\n→ そこから「何とかやっていく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 165, "stage": 4, "verb": "bring in", "meaning": "導入する、（人・収益を）呼び込む", "def": "to introduce something new; to attract people or money", "ex1": "The startup brought in a new investor to fund the next phase.", "ja1": "そのスタートアップは次の段階の資金として、新しい投資家を呼び込んだ。", "ex2": "We brought in an external consultant.", "ja2": "外部コンサルタントを起用した。", "note": "", "nuance": "introduce（導入する、より一般的）より口語的。bring in customers（客を呼び込む）のように、人や利益を「呼び込む」意味でも使う。", "groups": ["bring_in_out"], "etymology": "bring（持ってくる）＋in（中へ）\n→ 新しい人や物を組織の内側に呼び込むイメージ\n→ そこから「導入する、（人・収益を）呼び込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 166, "stage": 4, "verb": "put out*2", "meaning": "外に出す", "def": "to place something outside", "ex1": "She put the cat out for the night after it scratched the couch again.", "ja1": "猫がまたソファをひっかいたので、彼女は夜の間外に出した。", "ex2": "Please put out the signage before the seminar starts.", "ja2": "セミナー開始前に案内看板を外に出してください。", "note": "Stage 3 の put out（火を消す）と区別", "nuance": "put out（火を消す）とは別の意味で、こちらは物を「外に出す」ことを表す。take out（取り出す）と似ているが、put outは設置するニュアンスを含む。", "groups": ["put_out_senses"], "etymology": "put（置く）＋out（外へ）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「外に出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 167, "stage": 4, "verb": "put down*3", "meaning": "書き留める、記入する", "def": "to write something down", "ex1": "I put down her number on a napkin so I wouldn't forget it.", "ja1": "忘れないよう、彼女の電話番号をナプキンに書き留めた。", "ex2": "Put down the action items as we go.", "ja2": "進めながらアクション項目を書き留めてください。", "note": "Stage 2 / 3 に別語義あり。take down とほぼ同義", "nuance": "write down（書き留める、より一般的）とほぼ同義。put down*3は特にメモや記録として書き留める場面で使う。", "groups": ["write_down"], "etymology": "put（置く）＋down（下へ）\n→ 頭の中の情報を紙の上に書き落とすイメージ\n→ そこから「書き留める、記入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 168, "stage": 4, "verb": "fall down", "meaning": "転ぶ、倒れる", "def": "to fall to the ground", "ex1": "He tripped on the rug and fell down right in the doorway.", "ja1": "彼は敷物につまずいて、玄関口でそのまま転んだ。", "ex2": "The whiteboard fell down during the workshop.", "ja2": "ワークショップ中にホワイトボードが倒れた。", "note": "", "nuance": "fall over（つまずいて転ぶ、原因を含む）とは違い、fall downはただ「倒れる、転ぶ」という結果を表す。", "groups": ["fall_down"], "etymology": "fall（落ちる）＋down（下へ）\n→ 立っていた状態から地面へ倒れ落ちるイメージ\n→ そこから「転ぶ、倒れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 169, "stage": 4, "verb": "point out", "meaning": "指摘する", "def": "to draw attention to a fact or a mistake", "ex1": "A colleague kindly pointed out the typo before I sent the email to the whole team.", "ja1": "同僚が、チーム全員にメールを送る前に親切にタイプミスを指摘してくれた。", "ex2": "The reviewer pointed out three issues in the design.", "ja2": "レビュー担当者は設計上の課題を3点指摘した。", "note": "", "nuance": "mention（言及する、より一般的）とは違い、point outは相手が気づいていないことを「具体的に指摘する」ニュアンスが強い。", "groups": [], "etymology": "point（指し示す）＋out（外へ）\n→ 隠れていた事実が表に出て、はっきり見えてくるイメージ\n→ そこから「指摘する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 170, "stage": 4, "verb": "get out", "meaning": "出る、抜け出す", "def": "to leave a place or a situation", "ex1": "He couldn't wait to get out of the dentist's chair.", "ja1": "彼は歯医者の椅子から早く出たくて仕方なかった。", "ex2": "We need to get out of this contract.", "ja2": "この契約から抜ける必要がある。", "note": "", "nuance": "leave（単に去る）より、閉じ込められた状況や困難な場所から「抜け出す」という解放のニュアンスを含む。escapeより口語的。", "groups": ["exit_leave_briefly"], "etymology": "get（得る・～になる）＋out（外へ）\n→ 続いていた場から途中で外へ抜け出すイメージ\n→ そこから「出る、抜け出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 171, "stage": 4, "verb": "hold off", "meaning": "見合わせる、先延ばしにする", "def": "to delay doing something", "ex1": "We're holding off on the announcement until the contract is fully signed.", "ja1": "契約が完全に署名されるまで、発表は見合わせている。", "ex2": "Let's hold off on the announcement until legal approves.", "ja2": "法務の承認が出るまで発表を見合わせましょう。", "note": "Stage 7 に別語義あり", "nuance": "postpone（改まった延期）より口語的。put off（先延ばしにする）とほぼ同義だが、hold offは「様子を見て控える」ニュアンスが強い。", "groups": ["postpone"], "etymology": "hold（持つ・保つ）＋off（離れて）\n→ 予定していた時から距離を置いて先に離すイメージ\n→ そこから「見合わせる、先延ばしにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 172, "stage": 4, "verb": "give in", "meaning": "屈する、折れる", "def": "to finally agree to something after resisting", "ex1": "After hours of arguing, he finally gave in and agreed to her plan.", "ja1": "何時間も言い合った末、彼はついに折れて彼女の案に同意した。", "ex2": "We gave in to the client's request for a discount.", "ja2": "値引きの要望に折れた。", "note": "", "nuance": "surrender（改まった降伏）より口語的。give up（あきらめる）とは違い、give inは他者の圧力に「屈する」という対人関係のニュアンスを含む。", "groups": ["give_up_in"], "etymology": "give（与える）＋in（中へ）\n→ 相手の力に押されて内側に屈するイメージ\n→ そこから「屈する、折れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 173, "stage": 4, "verb": "drop in", "meaning": "ふらっと立ち寄る", "def": "to visit someone without arranging it in advance", "ex1": "An old friend just dropped in unannounced while I was still in pajamas.", "ja1": "パジャマのままでいた時に、旧友が予告なしにふらっと立ち寄った。", "ex2": "Feel free to drop in on the weekly stand-up.", "ja2": "週次の朝会には気軽に参加してください。", "note": "", "nuance": "drop by（ちょっと立ち寄る）とほぼ同義で、どちらも予定せずふらっと訪れることを表す口語表現。", "groups": ["visit_casually"], "etymology": "drop（ポトリと落ちる）＋in（中へ）\n→ ついでに内側へふらっと入り込むイメージ\n→ そこから「ふらっと立ち寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 174, "stage": 4, "verb": "put in*2", "meaning": "（申請などを）出す、申し込む", "def": "to formally submit a request or application", "ex1": "She put in her application the night before the deadline.", "ja1": "彼女は締め切り前夜に申請書を出した。", "ex2": "She put in for three days of leave.", "ja2": "彼女は3日間の休暇を申請した。", "note": "put in for の形が多い。Stage 3 の put in と区別", "nuance": "hand in（提出する）とは別の意味で、こちらは申請書などを「提出する、申し込む」場面で使う。apply forと似ている。", "groups": ["submit"], "etymology": "put（置く）＋in（中へ）\n→ 申請書などを窓口の内側へ差し出すイメージ\n→ そこから「（申請などを）出す、申し込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 175, "stage": 4, "verb": "push over", "meaning": "押し倒す", "def": "to push someone or something so that it falls", "ex1": "The wrestler pushed his opponent over with one shove.", "ja1": "そのレスラーは一押しで相手を押し倒した。", "ex2": "Someone pushed over the stack of boxes in the warehouse.", "ja2": "倉庫で誰かが積み上げた箱を倒した。", "note": "", "nuance": "push（単に押す）より強く、相手を「倒すまで押す」という結果を含む動作を表す。", "groups": [], "etymology": "push（押す）＋over（越えて）\n→ 相手を境界の向こうへ押し倒すイメージ\n→ そこから「押し倒す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 176, "stage": 4, "verb": "figure out", "meaning": "理解する、解明する", "def": "to understand or solve something after thinking", "ex1": "It took me a while to figure out why the code kept crashing.", "ja1": "コードが落ち続ける理由を理解するのに、しばらく時間がかかった。", "ex2": "We figured out the cause of the outage.", "ja2": "障害の原因を突き止めた。", "note": "", "nuance": "understand（単に理解する）より、謎や問題を「考えて解き明かす」というプロセスを強調する。solveと似ているが、より思考的なニュアンス。", "groups": ["understand"], "etymology": "figure（思い描く・計算する）＋out（外へ）\n→ 隠れていた事実が表に出て、はっきり見えてくるイメージ\n→ そこから「理解する、解明する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><circle cx=\"32\" cy=\"26\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M26 38 L38 38 M28 44 L36 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 177, "stage": 4, "verb": "cheer up", "meaning": "元気づける、元気を出す", "def": "to become happier, or to make someone happier", "ex1": "Her friends threw a surprise party just to cheer her up.", "ja1": "友人たちはただ彼女を元気づけるためにサプライズパーティーを開いた。", "ex2": "The good sales results cheered up the whole team.", "ja2": "好調な売上がチーム全体を元気づけた。", "note": "", "nuance": "encourage（改まった励まし）より口語的。make someone happyより、落ち込んでいる人を元気にするという具体的な状況で使う。", "groups": ["cheer_encourage"], "etymology": "cheer（励ます）＋up（上へ）\n→ 沈んでいた気持ちを上向きに引き上げるイメージ\n→ そこから「元気づける、元気を出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 178, "stage": 4, "verb": "bring along", "meaning": "一緒に連れて行く、持って行く", "def": "to take someone or something with you", "ex1": "Do you mind if I bring along my little sister to the movie?", "ja1": "映画に妹を一緒に連れて行っても構わない？", "ex2": "Please bring along a copy of the requirements.", "ja2": "要件書のコピーを持参してください。", "note": "", "nuance": "bring（単に持ってくる）より、「一緒に連れて行く」という同伴のニュアンスを強調する。invite（招待する）より軽い誘い。", "groups": ["come_along_together"], "etymology": "bring（持ってくる）＋along（沿って）\n→ 自分の道行きに相手を道連れにするイメージ\n→ そこから「一緒に連れて行く、持って行く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 179, "stage": 4, "verb": "drop out", "meaning": "中退する、脱落する", "def": "to stop attending or participating before the end", "ex1": "He dropped out of college in his second year to start a company.", "ja1": "彼は会社を始めるため、大学2年生で中退した。", "ex2": "Two vendors dropped out of the bidding.", "ja2": "2社が入札から降りた。", "note": "", "nuance": "quit（単にやめる）とは違い、drop outは特に学校や競技を「中途半端な状態でやめる、脱落する」ことを表す。", "groups": [], "etymology": "drop（ポトリと落ちる）＋out（外へ）\n→ 続いていた場から途中で外へ抜け出すイメージ\n→ そこから「中退する、脱落する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 180, "stage": 4, "verb": "take down", "meaning": "書き留める、記録する", "def": "to write down what someone says", "ex1": "The officer took down every detail of the accident in his notebook.", "ja1": "警官は事故の詳細を全て手帳に記録した。", "ex2": "She took down the minutes of the meeting.", "ja2": "彼女は会議の議事を書き留めた。", "note": "", "nuance": "write down（書き留める、より一般的）とほぼ同義。take downは特に会議や証言など、話された内容を記録する場面で使う。", "groups": ["write_down"], "etymology": "take（取る）＋down（下へ）\n→ 頭の中の情報を紙の上に書き落とすイメージ\n→ そこから「書き留める、記録する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 181, "stage": 4, "verb": "pay back", "meaning": "返済する、返す", "def": "to return money that you borrowed", "ex1": "It'll take at least five years to pay back the student loans.", "ja1": "学生ローンを返済するには、少なくとも5年はかかるだろう。", "ex2": "The investment will pay back within three years.", "ja2": "その投資は3年で回収できる。", "note": "", "nuance": "repay（改まった返済）より口語的。give back（物を返す）とは違い、pay backはお金の返済に特化して使われる。", "groups": ["return_money"], "etymology": "pay（払う）＋back（後ろ・元へ）\n→ 借りていた物を元の持ち主へ戻すイメージ\n→ そこから「返済する、返す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 182, "stage": 4, "verb": "make out*2", "meaning": "（かろうじて）見分ける、判読する", "def": "to manage to see, hear, or read something with difficulty", "ex1": "Through the fog, I could barely make out the shape of the lighthouse.", "ja1": "霧の中、灯台の形をかろうじて見分けることができた。", "ex2": "I can't make out the handwriting on this form.", "ja2": "この用紙の手書き文字が判読できない。", "note": "Stage 3 の make up と混同しやすい", "nuance": "see（単に見る）より、はっきりしない中で「かろうじて識別する」という努力を含む。distinguishより口語的。", "groups": ["distinguish"], "etymology": "make（作る）＋out（外へ）\n→ 多くの中から一つを外へ抜き出すイメージ\n→ そこから「（かろうじて）見分ける、判読する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 183, "stage": 4, "verb": "bring out", "meaning": "世に出す、（性質を）引き出す", "def": "to release a product; to make a quality more noticeable", "ex1": "The lab is about to bring out a new vaccine after years of testing.", "ja1": "その研究所は、何年もの試験を経て新しいワクチンを世に出そうとしている。", "ex2": "We're bringing out the new version in September.", "ja2": "9月に新バージョンをリリースします。", "note": "", "nuance": "launch（改まった発売）より一般的。reveal（明らかにする）と似ているが、bring outは製品や才能を「世に出す」広い意味で使う。", "groups": ["bring_in_out"], "etymology": "bring（持ってくる）＋out（外へ）\n→ 隠れていた才能や物を世の中へ出すイメージ\n→ そこから「世に出す、（性質を）引き出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 184, "stage": 4, "verb": "catch up*2", "meaning": "近況を語り合う、情報を共有する", "def": "to exchange news with someone you have not seen for a while", "ex1": "We stayed on the phone for two hours just catching up.", "ja1": "私たちは2時間も電話をつなぎっぱなしで、ただ近況を語り合っていた。", "ex2": "Let's catch up briefly before the client call.", "ja2": "顧客との電話の前に少し状況を共有しましょう。", "note": "Stage 2 の catch up（追いつく）と区別", "nuance": "talk（単に話す）とは違い、catch up*2は久しぶりに会った人と「近況を交換し合う」という特定の状況を表す。", "groups": ["socialize_catch_up"], "etymology": "catch（捕まえる）＋up（上へ）\n→ 離れていた間の情報を最新の状態まで引き上げるイメージ\n→ そこから「近況を語り合う、情報を共有する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 185, "stage": 4, "verb": "take down*2", "meaning": "取り壊す、撤去する", "def": "to remove or dismantle something", "ex1": "The old stadium was taken down to make room for a shopping mall.", "ja1": "その古いスタジアムはショッピングモールを建てるために取り壊された。", "ex2": "We took down the booth after the exhibition.", "ja2": "展示会の後、ブースを撤去した。", "note": "元リストで take down が2回出現するため別語義として整理", "nuance": "demolish（改まった取り壊し）より口語的。put up（建てる）の反対で、建物や構造物を撤去することを表す。", "groups": ["take_down_senses"], "etymology": "take（取る）＋down（下へ）\n→ 建っていた物を崩して下へ下ろすイメージ\n→ そこから「取り壊す、撤去する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 186, "stage": 4, "verb": "bring down", "meaning": "引き下げる、失脚させる", "def": "to reduce something; to cause someone or something to fall", "ex1": "The scandal eventually brought down the entire cabinet.", "ja1": "そのスキャンダルは結局、内閣全体を失脚させた。", "ex2": "We need to bring down the running costs.", "ja2": "運用コストを引き下げる必要がある。", "note": "", "nuance": "reduce（減らす、より一般的）とは違い、bring downは特に価格や地位を「意図的に引き下げる」、または権力者を「失脚させる」ニュアンスを持つ。", "groups": [], "etymology": "bring（持ってくる）＋down（下へ）\n→ 高い地位や数値を引きずり下ろすイメージ\n→ そこから「引き下げる、失脚させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 187, "stage": 4, "verb": "put out*3", "meaning": "迷惑をかける、手間をかけさせる", "def": "to cause someone extra trouble or inconvenience", "ex1": "I'm sorry to put you out, but could you drive me to the airport?", "ja1": "ご迷惑をおかけして申し訳ないですが、空港まで送ってもらえますか。", "ex2": "I hope the schedule change didn't put you out.", "ja2": "日程変更でご迷惑をおかけしていなければよいのですが。", "note": "Stage 3 / 4 の put out と区別", "nuance": "inconvenience（改まった迷惑）より口語的。bother（困らせる、より一般的）とほぼ同義で、依頼する際の前置きとしてよく使われる。", "groups": ["put_out_senses"], "etymology": "put（置く）＋out（外へ）\n→ 自分の都合を外の相手にまで負担させるイメージ\n→ そこから「迷惑をかける、手間をかけさせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 188, "stage": 4, "verb": "pull off", "meaning": "やってのける、成功させる", "def": "to succeed in doing something difficult", "ex1": "Somehow he pulled off the entire presentation without any notes.", "ja1": "彼はどういうわけか、メモなしでプレゼン全体をやり遂げた。", "ex2": "The team pulled off the migration in one night.", "ja2": "チームは一晩で移行をやり遂げた。", "note": "Stage 8 に別語義あり", "nuance": "succeed（単に成功する）より、難しいことを「見事にやってのける」という驚きや称賛のニュアンスを含む。manage toと似ている。", "groups": ["succeed"], "etymology": "pull（引く）＋off（離れて）\n→ 難しい状況から見事に抜け出して成し遂げるイメージ\n→ そこから「やってのける、成功させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 189, "stage": 4, "verb": "pull over", "meaning": "（車を）路肩に寄せて止める", "def": "to move a vehicle to the side of the road and stop", "ex1": "A police officer pulled us over for a broken taillight.", "ja1": "警察官はテールランプの故障を理由に私たちを路肩に停止させた。", "ex2": "Pull over here; the entrance is on the left.", "ja2": "ここで停めてください、入口は左手です。", "note": "", "nuance": "stop（単に止まる）とは違い、pull overは車を運転中に「路肩に寄せて停止する」という具体的な動作を表す。", "groups": ["pull_over_stop_car"], "etymology": "pull（引く）＋over（越えて）\n→ 進路を越えて道の端へ寄せるイメージ\n→ そこから「（車を）路肩に寄せて止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 190, "stage": 4, "verb": "tag along", "meaning": "くっついていく、同行する", "def": "to go somewhere with someone, often without being invited", "ex1": "My little brother insisted on tagging along to every party I went to.", "ja1": "弟は私が行くパーティーすべてに、くっついてくると言い張った。", "ex2": "Can I tag along to the client meeting to observe?", "ja2": "見学のため顧客訪問に同行してもよいですか。", "note": "", "nuance": "follow（ついていく、より一般的）とは違い、tag alongは「誘われてもいないのについていく」という、やや押しかけるニュアンスを含むことがある。", "groups": ["come_along_together"], "etymology": "tag（タグをつける・くっついていく）＋along（沿って）\n→ 主となる相手にぴったりくっついて進むイメージ\n→ そこから「くっついていく、同行する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(9,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 191, "stage": 4, "verb": "hold out", "meaning": "持ちこたえる、持続する", "def": "to continue to last or resist", "ex1": "The old battery held out much longer than we expected.", "ja1": "その古いバッテリーは予想よりもずっと長持ちした。", "ex2": "The old server held out until the migration was done.", "ja2": "移行が終わるまで旧サーバーは持ちこたえた。", "note": "", "nuance": "last（単に持続する、より一般的）とは違い、hold outは苦しい状況の中で「持ちこたえる」という抵抗のニュアンスを含む。", "groups": ["hold_out_off"], "etymology": "hold（持つ・保つ）＋out（外へ）\n→ 外からの圧力に屈さず持ちこたえるイメージ\n→ そこから「持ちこたえる、持続する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 192, "stage": 4, "verb": "brush up", "meaning": "復習する、磨き直す", "def": "to improve a skill that you learned before", "ex1": "I need to brush up on my French before the trip to Paris.", "ja1": "パリ旅行の前に、フランス語を少し復習しておく必要がある。", "ex2": "I'm brushing up on my presentation skills.", "ja2": "プレゼンのスキルを磨き直しています。", "note": "brush up on の形が多い", "nuance": "review（改まった復習）より口語的。study again（もう一度勉強する）とほぼ同義だが、brush upは錆びついた技能を「磨き直す」イメージ。", "groups": ["study_review"], "etymology": "brush（さっと払う）＋up（上へ）\n→ 鈍っていた技能を磨いて仕上げるイメージ\n→ そこから「復習する、磨き直す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M40 16 L24 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M24 44 L16 50 M24 44 L20 50 M24 44 L28 50\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 193, "stage": 4, "verb": "pay off", "meaning": "完済する", "def": "to finish paying a debt", "ex1": "It took twenty years, but they finally paid off the house.", "ja1": "20年かかったが、彼らはついに家のローンを完済した。", "ex2": "The company paid off its debt ahead of schedule.", "ja2": "会社は予定より早く負債を完済した。", "note": "Stage 4 の pay off*2 と区別", "nuance": "pay back（返済する、より一般的）とは違い、pay offは借金やローンを「完全に返し終える」という完了のニュアンスを強調する。", "groups": ["pay_related"], "etymology": "pay（払う）＋off（離れて）\n→ 借りを完全に切り離して、きれいさっぱりにするイメージ\n→ そこから「完済する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 194, "stage": 4, "verb": "push back", "meaning": "反発する、難色を示す", "def": "to resist or express disagreement with a plan", "ex1": "Employees pushed back hard against the new overtime policy.", "ja1": "従業員たちは新しい残業方針に強く反発した。", "ex2": "The client pushed back on our estimate.", "ja2": "顧客は我々の見積もりに難色を示した。", "note": "Stage 7 に別語義あり", "nuance": "reject（改まった拒否）より、push backは相手の意見や方針に「反発・抵抗する」という対立のニュアンスを含む。", "groups": ["oppose_resist"], "etymology": "push（押す）＋back（後ろ・元へ）\n→ 相手の力に対して押し返すイメージ\n→ そこから「反発する、難色を示す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 195, "stage": 4, "verb": "put on*2", "meaning": "体重が増える", "def": "to gain weight", "ex1": "He's put on quite a bit of weight since he quit playing soccer.", "ja1": "サッカーをやめてから、彼はかなり体重が増えた。", "ex2": "He put on weight after moving to a desk job.", "ja2": "内勤になってから彼は太った。", "note": "Stage 1 の put on（着る）と区別", "nuance": "gain weight（改まった言い方）より口語的。put on*2は日常会話で「体重が増えた」ことを表す最も一般的な言い方。", "groups": [], "etymology": "put（置く）＋on（接触・継続）\n→ 体や物の上に重なって積もっていくイメージ\n→ そこから「体重が増える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 196, "stage": 4, "verb": "chill out", "meaning": "リラックスする、落ち着く", "def": "to relax and stop being angry or nervous", "ex1": "Just chill out, the flight isn't for another three hours.", "ja1": "落ち着いて、フライトはまだ3時間も先だよ。", "ex2": "Chill out — we still have two weeks before the deadline.", "ja2": "落ち着いて、締切まではまだ2週間ある。", "note": "かなりくだけた表現。目上には使わない", "nuance": "relax（くつろぐ、より一般的）とほぼ同義。calm down（落ち着く）と似ているが、chill outはより若者言葉的でカジュアル。", "groups": ["calm_down"], "etymology": "chill（冷やす・くつろぐ）＋out（外へ）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「リラックスする、落ち着く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 197, "stage": 4, "verb": "pay off*2", "meaning": "（努力が）実を結ぶ", "def": "to produce good results after effort or investment", "ex1": "Years of hard work finally paid off when she got the promotion.", "ja1": "何年もの努力が、彼女が昇進した時にようやく実を結んだ。", "ex2": "The extra testing paid off; there were no defects.", "ja2": "追加テストが功を奏し、不具合はなかった。", "note": "Stage 4 の pay off（完済する）と区別", "nuance": "succeed in（改まった成功）より、pay off*2は「これまでの努力が結果として実を結ぶ」という因果関係を強調する。", "groups": ["succeed"], "etymology": "pay（払う）＋off（離れて）\n→ 積み重ねた努力から結果が生まれ出るイメージ\n→ そこから「（努力が）実を結ぶ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 198, "stage": 4, "verb": "make out*2 (2)", "meaning": "うまくやる、首尾よくいく", "def": "to manage or succeed in a particular situation", "ex1": "Despite the rocky start, the two roommates somehow made out just fine.", "ja1": "出だしはぎくしゃくしていたが、そのルームメイト二人はなぜかうまくやっていった。", "ex2": "How did the team make out on the first day of the rollout?", "ja2": "展開初日、チームの首尾はどうでしたか。", "note": "元リストで make out*2 が2回出現するため別語義として整理", "nuance": "succeed（単に成功する）とは違い、make out*2 (2)は困難な状況でも「うまく乗り切る、やっていく」というニュアンス。", "groups": ["succeed"], "etymology": "make（作る）＋out（外へ）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「うまくやる、首尾よくいく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-13,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 199, "stage": 4, "verb": "make up*3", "meaning": "（不足を）埋め合わせる", "def": "to compensate for something that is missing or lost", "ex1": "She took a second job on weekends just to make up the difference in rent.", "ja1": "家賃の差額を埋め合わせるためだけに、彼女は週末に副業を始めた。", "ex2": "We worked overtime to make up the lost days.", "ja2": "遅れた日数を取り戻すため残業した。", "note": "Stage 3 / 4 / 5 に別語義あり", "nuance": "compensate for（改まった埋め合わせ）より口語的。make up*3は不足分やミスを「別の方法で埋め合わせる」場面で幅広く使う。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 足りない分を上まで満たして埋め合わせるイメージ\n→ そこから「（不足を）埋め合わせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 200, "stage": 4, "verb": "take up", "meaning": "始める／（時間・場所を）とる", "def": "to start a new activity; to occupy time or space", "ex1": "He took up painting during the pandemic and never stopped.", "ja1": "彼はパンデミック中に絵を始め、それ以来ずっと続けている。", "ex2": "This task takes up most of my morning.", "ja2": "この作業で午前中がほとんど埋まる。", "note": "元リスト表記は take-up。Stage 5 に take up*2 あり", "nuance": "start（始める、より一般的）とは全く別の意味で、こちらは新しい趣味や活動を「始める」、または物理的な「時間・場所を占める」ことを表す。", "groups": ["undertake_continue_work"], "etymology": "take（取る）＋up（上へ）\n→ 新しいことに取りかかり、時間や場所を占めるイメージ\n→ そこから「始める／（時間・場所を）とる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 201, "stage": 4, "verb": "take out*2", "meaning": "（保険・ローンを）契約する", "def": "to arrange to get insurance or a loan", "ex1": "We took out a small loan to cover the wedding costs.", "ja1": "結婚式の費用をまかなうため、私たちは小さなローンを組んだ。", "ex2": "The company took out insurance against project delays.", "ja2": "会社はプロジェクト遅延に備えて保険を掛けた。", "note": "Stage 3 の take out（取り出す）と区別", "nuance": "obtain（改まった契約取得）より口語的。take out*2は保険やローンを「契約する、組む」場面で使われる特定の表現。", "groups": ["take_out_senses"], "etymology": "take（取る）＋out（外へ）\n→ 保険やローンなどの合意を外部と結ぶイメージ\n→ そこから「（保険・ローンを）契約する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 202, "stage": 4, "verb": "go into", "meaning": "詳しく述べる／（分野に）進む", "def": "to explain in detail; to enter a field of work", "ex1": "The professor didn't have time to go into much detail about the exam.", "ja1": "教授は試験について詳しく述べる時間がなかった。", "ex2": "She went into consulting after graduation.", "ja2": "彼女は卒業後コンサルティング業界に進んだ。", "note": "", "nuance": "explain（単に説明する）とは違い、go intoは物事を「詳細に踏み込んで述べる」ニュアンスを含む。get into（分野に進む）と似た形だが意味は異なる。", "groups": ["elaborate_dig"], "etymology": "go（行く）＋into（中へ変化）\n→ 話題や分野の内側へ深く踏み込むイメージ\n→ そこから「詳しく述べる／（分野に）進む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 203, "stage": 5, "verb": "blow away", "meaning": "感動させる、圧倒する", "def": "to impress someone very much", "ex1": "The magician's final trick blew everyone in the audience away.", "ja1": "そのマジシャンの最後のトリックは、観客全員を圧倒した。", "ex2": "The demo blew away the client.", "ja2": "デモは顧客を圧倒した。", "note": "", "nuance": "amaze（改まった驚嘆）より口語的で強い表現。impress（感心させる）よりも、圧倒的な驚きや感動を表す。", "groups": [], "etymology": "blow（吹く）＋away（遠くへ）\n→ あまりの凄さに心を持っていかれるイメージ\n→ そこから「感動させる、圧倒する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 204, "stage": 5, "verb": "come along*2", "meaning": "（機会が）巡ってくる、現れる", "def": "to appear or become available", "ex1": "An opportunity like this doesn't come along very often, so take it.", "ja1": "こんな機会はそう滅多に巡ってこないから、つかんだ方がいい。", "ex2": "If a better offer comes along, we'll consider it.", "ja2": "より良い提案が出てくれば検討します。", "note": "Stage 2 の come along と区別", "nuance": "happen（単に起こる）とは違い、come along*2は良い機会やチャンスが「偶然巡ってくる」という前向きなニュアンスを含む。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋along（沿って）\n→ 進む道の先にタイミングよく現れるイメージ\n→ そこから「（機会が）巡ってくる、現れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(2,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 205, "stage": 5, "verb": "kick out", "meaning": "追い出す、除名する", "def": "to force someone to leave a place or group", "ex1": "He was kicked out of the club for breaking the rules twice.", "ja1": "彼はルールを2回破ったことで、そのクラブから追い出された。", "ex2": "The vendor was kicked out of the project for poor quality.", "ja2": "品質不良でその業者はプロジェクトから外された。", "note": "", "nuance": "remove（改まった除去）より口語的。expel（正式に除名する）とほぼ同義で、規則違反による追放を表す。get out（自分の意志で抜け出す）とは主語が逆で、kick outは「他者から強制的に追い出される」という受動的な立場を表す。", "groups": [], "etymology": "kick（蹴る）＋out（外へ）\n→ 対象を組織の外へ追い払うイメージ\n→ そこから「追い出す、除名する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 206, "stage": 5, "verb": "take back*2", "meaning": "元の場所へ戻す／思い出させる", "def": "to return someone or something to a place; to remind of the past", "ex1": "Please take the ladder back to the garage when you're finished.", "ja1": "使い終わったら、はしごをガレージに戻しておいてください。", "ex2": "This photo takes me back to my first project.", "ja2": "この写真を見ると最初のプロジェクトを思い出す。", "note": "Stage 3 の take back（返品・撤回）と区別", "nuance": "return（元の場所へ戻す）だけでなく、take back*2は思い出や記憶を「呼び起こす」という意味でも使われる。remind（思い出させる）と似ている。", "groups": ["return"], "etymology": "take（取る）＋back（後ろ・元へ）\n→ 過去の記憶が意識の中へ戻ってくるイメージ\n→ そこから「元の場所へ戻す／思い出させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 207, "stage": 5, "verb": "back off", "meaning": "引き下がる、手を引く", "def": "to stop pressing someone or interfering", "ex1": "The dog growled once, and the stranger immediately backed off.", "ja1": "犬が一度うなると、見知らぬ人はすぐに引き下がった。", "ex2": "The client backed off from the additional request.", "ja2": "顧客は追加要望を取り下げた。", "note": "", "nuance": "retreat（改まった撤退）より口語的。step back（一歩下がる）と似ているが、back offは対立や要求から「引き下がる」という対人関係のニュアンスが強い。", "groups": ["give_up_in"], "etymology": "back（後ろへ）＋off（離れて）\n→ 対立していた状況から距離を取って離れるイメージ\n→ そこから「引き下がる、手を引く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 208, "stage": 5, "verb": "make up*4", "meaning": "構成する、占める", "def": "to form or compose a whole", "ex1": "Freelancers now make up almost a third of the entire workforce.", "ja1": "フリーランサーは今や全労働力のほぼ3分の1を占めている。", "ex2": "Licence fees make up 60 percent of the cost.", "ja2": "ライセンス費用がコストの6割を占める。", "note": "Stage 3 / 4 に別語義あり", "nuance": "consist of（構成される、より一般的）と似ているが、make up*4は「全体のうちどれくらいの割合を占めるか」という比率のニュアンスを含む。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 要素が積み上がって一つの形を構成するイメージ\n→ そこから「構成する、占める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 209, "stage": 5, "verb": "bring up*2", "meaning": "育てる、養育する", "def": "to raise a child", "ex1": "She was brought up by her grandparents in a small fishing village.", "ja1": "彼女は小さな漁村で祖父母に育てられた。", "ex2": "He was brought up to value punctuality.", "ja2": "彼は時間厳守を重んじるよう育てられた。", "note": "Stage 3 の bring up（話題を出す）と区別", "nuance": "raise（育てる、より一般的）とほぼ同義。bring up*2は特に「どんな環境で育てられたか」を語る際によく使われる。", "groups": ["bring_up_senses"], "etymology": "bring（持ってくる）＋up（上へ）\n→ 子どもが上へ育つよう支え続けるイメージ\n→ そこから「育てる、養育する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 210, "stage": 5, "verb": "take down*3", "meaning": "やり込める、打ち負かす", "def": "to defeat someone or destroy their argument", "ex1": "The underdog took down the reigning champion in the final round.", "ja1": "そのアンダードッグは、最終ラウンドでチャンピオンを打ち負かした。", "ex2": "The report took down the manager's argument point by point.", "ja2": "その報告は上司の主張を一つずつ論破した。", "note": "Stage 4 の take down / take down*2 と区別", "nuance": "defeat（改まった打ち負かし）より口語的。beat（単に勝つ）より、相手を圧倒的にやり込めるニュアンスを含む。", "groups": ["take_down_senses"], "etymology": "take（取る）＋down（下へ）\n→ 相手を組み伏せて下に置くイメージ\n→ そこから「やり込める、打ち負かす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 211, "stage": 5, "verb": "break down", "meaning": "故障する、（人が）取り乱す", "def": "to stop working; to lose emotional control", "ex1": "Our car broke down halfway through the road trip.", "ja1": "ロードトリップの途中で車が故障した。", "ex2": "The system broke down during peak hours.", "ja2": "ピーク時にシステムが停止した。", "note": "Stage 5 の break down*2 と区別", "nuance": "malfunction（改まった故障）より口語的。stop working（動かなくなる）とほぼ同義だが、人が精神的に「取り乱す」場面でも使う多義語。", "groups": ["break_malfunction"], "etymology": "break（壊す・分ける）＋down（下へ）\n→ 正常だった機能や心の状態が落ち込むイメージ\n→ そこから「故障する、（人が）取り乱す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 212, "stage": 5, "verb": "dress up", "meaning": "着飾る、正装する", "def": "to wear formal or special clothes", "ex1": "Everyone dressed up for the gala, even the kids.", "ja1": "子供たちも含め、みんながそのパーティーのために着飾った。", "ex2": "You don't need to dress up for the casual meeting.", "ja2": "カジュアルな打ち合わせなので正装は不要です。", "note": "", "nuance": "wear nice clothes（改まった言い方）より口語的。put on（単に着る）とは違い、dress upは特別な場のために「着飾る」ニュアンスを含む。", "groups": ["clothing_wear"], "etymology": "dress（着せる）＋up（上へ）\n→ 身なりを上等に仕上げて整えるイメージ\n→ そこから「着飾る、正装する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 213, "stage": 5, "verb": "get in*2", "meaning": "（組織・学校に）入る、合格する", "def": "to be accepted into a school or organization", "ex1": "She studied for two years straight just to get in to that university.", "ja1": "彼女はその大学に合格するためだけに、2年間ずっと勉強した。", "ex2": "It's hard to get in to that company without a referral.", "ja2": "紹介なしにあの会社に入るのは難しい。", "note": "Stage 1 の get in（乗り込む）と区別", "nuance": "join（改まった加入）より口語的。get on（乗り物に乗る）とは全く別の意味で、get in*2は組織や学校に「合格して入る」ことを表す。", "groups": ["enter_various"], "etymology": "get（得る・～になる）＋in（中へ）\n→ 組織の内側に受け入れられて一員になるイメージ\n→ そこから「（組織・学校に）入る、合格する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 214, "stage": 5, "verb": "keep on", "meaning": "〜し続ける", "def": "to continue doing something", "ex1": "Even after the injury, he kept on training every single day.", "ja1": "怪我をしたあとも、彼は毎日トレーニングし続けた。", "ex2": "Keep on testing until the issue is reproduced.", "ja2": "事象が再現するまでテストを続けてください。", "note": "後ろは動名詞（-ing）", "nuance": "continue（単に続ける）より口語的。keep doingの形で「〜し続ける」という動作の継続を表す最も一般的な言い方。", "groups": ["undertake_continue_work"], "etymology": "keep（保つ）＋on（接触・継続）\n→ 動作や状態が途切れずそのまま続いていくイメージ\n→ そこから「〜し続ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 215, "stage": 5, "verb": "take away", "meaning": "持ち去る、取り上げる", "def": "to remove something or someone from a place", "ex1": "Security took away his badge the moment he was fired.", "ja1": "解雇された瞬間、警備員は彼の社員証を取り上げた。", "ex2": "The new rule took away our flexibility.", "ja2": "新しい規則で柔軟性が失われた。", "note": "", "nuance": "take out（取り出す、持ち出す）とは違い、take awayは物を「持ち去る」「取り上げる」という奪う動作を強調する。", "groups": [], "etymology": "take（取る）＋away（遠くへ）\n→ 対象を奪い取って遠くへ持ち去るイメージ\n→ そこから「持ち去る、取り上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 216, "stage": 5, "verb": "fill in", "meaning": "記入する", "def": "to write information in the spaces on a form", "ex1": "Please fill in your name and address at the top of the form.", "ja1": "用紙の一番上に、お名前とご住所を記入してください。", "ex2": "Please fill in the required fields in the request sheet.", "ja2": "依頼書の必須項目を記入してください。", "note": "Stage 7 に fill in*2、Stage 5 に fill in for あり", "nuance": "記入する動作。fill in for（代理）、fill in*2（伝える）と区別。", "groups": ["fill_form"], "etymology": "fill（満たす）＋in（中へ）\n→ 書類の空欄の内側に文字を書き込むイメージ\n→ そこから「記入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><path d=\"M22 26 L24 46 Q24 48 26 48 L38 48 Q40 48 40 46 L42 26\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M18 26 L46 26\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 14 L32 22 M28 18 L32 22 L36 18\" stroke=\"#C79A3D\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 217, "stage": 5, "verb": "take apart", "meaning": "分解する", "def": "to separate something into its parts", "ex1": "My dad took apart the toaster just to see how it worked.", "ja1": "父はただ仕組みを見たいがために、トースターを分解した。", "ex2": "We took apart the process to find the bottleneck.", "ja2": "ボトルネックを見つけるため工程を分解した。", "note": "", "nuance": "disassemble（改まった分解）より口語的。break down*2（分解する、より技術的）とほぼ同義。", "groups": ["break_into_parts"], "etymology": "take（取る）＋apart（ばらばらに）\n→ 一つだった物が分かれていくイメージ\n→ そこから「分解する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L0 8 L8 14 M8 2 L16 8 L8 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 218, "stage": 5, "verb": "hold in", "meaning": "（感情を）抑える", "def": "to keep an emotion from being shown", "ex1": "She held in her laughter until the meeting was completely over.", "ja1": "彼女は会議が完全に終わるまで笑いを我慢した。", "ex2": "He held in his frustration during the negotiation.", "ja2": "交渉中、彼は苛立ちを抑えた。", "note": "Stage 5 の hold in*2 と区別", "nuance": "suppress（改まった抑圧）より口語的。hold in*2（熱や水を閉じ込める）とは別の意味で、こちらは感情を「表に出さず抑える」ことを表す。", "groups": ["hold_in_senses"], "etymology": "hold（持つ・保つ）＋in（中へ）\n→ 感情をあふれさせず内側に押し込めるイメージ\n→ そこから「（感情を）抑える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 219, "stage": 5, "verb": "keep off", "meaning": "近づかない、（話題を）避ける", "def": "to stay away from something; to avoid a topic", "ex1": "The doctor told him to keep off his injured ankle for two weeks.", "ja1": "医者は彼に、2週間はけがした足首に負担をかけないようにと言った。", "ex2": "Let's keep off the pricing topic until legal reviews it.", "ja2": "法務が確認するまで価格の話題は避けましょう。", "note": "", "nuance": "stay away from（近づかない、より一般的）とほぼ同義。keep off the topicで「その話題を避ける」という比喩的な意味でも使う。", "groups": ["avoid_stay_away"], "etymology": "keep（保つ）＋off（離れて）\n→ 対象を自分から切り離し、近づかせないイメージ\n→ そこから「近づかない、（話題を）避ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 220, "stage": 5, "verb": "cover up", "meaning": "隠蔽する、覆い隠す", "def": "to hide a mistake or wrongdoing", "ex1": "The company tried to cover up the leak for as long as possible.", "ja1": "その会社はできる限り長く、情報漏洩を隠蔽しようとした。", "ex2": "Covering up a defect makes the problem worse.", "ja2": "不具合を隠蔽すると問題は悪化する。", "note": "", "nuance": "hide（単に隠す）より、真実や問題を組織的に「隠蔽する」という否定的なニュアンスを強く含む。", "groups": [], "etymology": "cover（覆う）＋up（上へ）\n→ 見えないよう上から覆いをかぶせるイメージ\n→ そこから「隠蔽する、覆い隠す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 221, "stage": 5, "verb": "turn down", "meaning": "断る、却下する", "def": "to refuse an offer, request, or application", "ex1": "I asked her out, but she politely turned me down.", "ja1": "彼女をデートに誘ったが、彼女はやんわりと断った。", "ex2": "They turned down our request for an extension.", "ja2": "先方は納期延長の依頼を断った。", "note": "Stage 3 の turn down（音量を下げる）と区別", "nuance": "refuse（改まった拒否）より口語的。turn up（音量を上げる）とは全く別の意味の多義語なので注意。", "groups": [], "etymology": "turn（向きを変える）＋down（下へ）\n→ 差し出されたものを下に押し返すイメージ\n→ そこから「断る、却下する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 222, "stage": 5, "verb": "catch on", "meaning": "人気が出る、広まる", "def": "to become popular or fashionable", "ex1": "The trend caught on so fast that every store ran out of stock.", "ja1": "そのトレンドはあまりに早く広まり、どの店も在庫切れになった。", "ex2": "The service caught on among small businesses.", "ja2": "そのサービスは中小企業に広まった。", "note": "Stage 7 に別語義あり", "nuance": "become popular（改まった言い方）より口語的。トレンドや習慣が急速に「広まる、定着する」ことを表す。", "groups": ["gain_popularity"], "etymology": "catch（捕まえる）＋on（接触・継続）\n→ 多くの人にくっついて広がり、定着するイメージ\n→ そこから「人気が出る、広まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 223, "stage": 5, "verb": "come around*3", "meaning": "（時期が）巡ってくる", "def": "to happen again as part of a regular cycle", "ex1": "Winter always comes around faster than I'd like.", "ja1": "冬はいつも思っているより早く巡ってくる。", "ex2": "Budget season comes around every October.", "ja2": "予算の時期は毎年10月に巡ってくる。", "note": "元リスト表記は come-around*3", "nuance": "come up（話題が持ち上がる）とは別の意味で、come around*3は季節や記念日など「決まった時期が巡ってくる」ことを表す。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋around（周りに）\n→ 時が一周してまた巡ってくるイメージ\n→ そこから「（時期が）巡ってくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 224, "stage": 5, "verb": "put together", "meaning": "組み立てる、まとめ上げる", "def": "to assemble or create something from separate parts", "ex1": "It took us three hours to put together the bookshelf from the manual.", "ja1": "説明書を見ながら本棚を組み立てるのに3時間かかった。", "ex2": "She put together the proposal in two days.", "ja2": "彼女は2日で提案書をまとめた。", "note": "", "nuance": "assemble（改まった組み立て）より口語的。put up（テントなどを立てる）とは違い、put togetherは複数の部品を「組み合わせて完成させる」プロセスを強調する。", "groups": ["organize"], "etymology": "put（置く）＋together（一つに）\n→ 散らばっていた物を一つに寄せ集めるイメージ\n→ そこから「組み立てる、まとめ上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 225, "stage": 5, "verb": "hold in*2", "meaning": "（熱・水などを）閉じ込める", "def": "to keep something inside and prevent it from escaping", "ex1": "The thick curtains hold in the heat during winter nights.", "ja1": "その厚いカーテンは、冬の夜の熱を室内に閉じ込めておく。", "ex2": "The case holds in the heat, so ventilation is needed.", "ja2": "筐体は熱がこもるので換気が必要だ。", "note": "Stage 5 の hold in（感情を抑える）と区別", "nuance": "hold in（感情を抑える）とは別の意味で、hold in*2は物理的に熱や水などを「内部に閉じ込めておく」ことを表す。", "groups": ["hold_in_senses"], "etymology": "hold（持つ・保つ）＋in（中へ）\n→ 熱や水などを外に逃さず内部に留めるイメージ\n→ そこから「（熱・水などを）閉じ込める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 226, "stage": 5, "verb": "break down*2", "meaning": "分解する、内訳を示す", "def": "to divide something into smaller parts for analysis", "ex1": "Can you break down the total cost into monthly payments?", "ja1": "総額を月々の支払いに分けて示してもらえますか。", "ex2": "Please break down the cost by category.", "ja2": "コストを費目ごとに分けて示してください。", "note": "Stage 5 の break down（故障する）と区別", "nuance": "break down（故障する）とは別の意味で、break down*2は大きな数字や情報を「項目ごとに分解して示す」ことを表す。analyzeより具体的。", "groups": ["break_into_parts"], "etymology": "break（壊す・分ける）＋down（下へ）\n→ 一つの塊を下の階層まで細かく分けるイメージ\n→ そこから「分解する、内訳を示す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 227, "stage": 5, "verb": "slack off", "meaning": "手を抜く、怠ける", "def": "to work less hard than you should", "ex1": "The moment the manager left, half the team started slacking off.", "ja1": "マネージャーが去った途端、チームの半分が手を抜き始めた。", "ex2": "Quality drops when we slack off on reviews.", "ja2": "レビューの手を抜くと品質が落ちる。", "note": "", "nuance": "be lazy（改まった言い方）より口語的。slack offは特に仕事や勉強で「本来のペースより手を抜く」場面で使う。", "groups": ["slack_off_group"], "etymology": "slack（たるむ・怠ける）＋off（離れて）\n→ 入れていた力を抜いてだらける方向へ離れるイメージ\n→ そこから「手を抜く、怠ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 228, "stage": 5, "verb": "cover for", "meaning": "代理を務める、かばう", "def": "to do someone's work while they are away; to protect someone", "ex1": "She covered for me at work while I was in the hospital.", "ja1": "私が入院している間、彼女は職場で私の代わりを務めてくれた。", "ex2": "I'll cover for her while she's on leave.", "ja2": "休暇中は私が彼女の代わりを務めます。", "note": "", "nuance": "cover（かばう、より一般的）とほぼ同義。sub for someone（代理を務める、くだけた言い方）と似ている。", "groups": ["help_cover"], "etymology": "cover（覆う）＋for（求めて）\n→ 相手を守るために間に立ちはだかるイメージ\n→ そこから「代理を務める、かばう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 229, "stage": 5, "verb": "kick off", "meaning": "開始する", "def": "to start an event, match, or project", "ex1": "The festival kicks off with a fireworks show at sunset.", "ja1": "そのお祭りは日没時の花火ショーで幕を開ける。", "ex2": "We kick off the project next Monday.", "ja2": "来週月曜にプロジェクトを開始します。", "note": "", "nuance": "start（単に始める）より、イベントや活動を「正式に開始する」という号砲的なニュアンスを含む。begin（改まった開始）より口語的。", "groups": [], "etymology": "kick（蹴る）＋off（離れて）\n→ スタート地点から離れて動き出すイメージ\n→ そこから「開始する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 230, "stage": 5, "verb": "hold up", "meaning": "遅らせる／（強盗が）襲う", "def": "to delay someone or something; to rob using force", "ex1": "Roadwork on the highway held up traffic for over an hour.", "ja1": "高速道路の工事が1時間以上、交通を遅らせた。", "ex2": "The approval process held up the release.", "ja2": "承認プロセスがリリースを遅らせた。", "note": "", "nuance": "delay（改まった遅延）より口語的。rob（強盗する、より直接的）とほぼ同義の別の意味も持つ多義語。", "groups": [], "etymology": "hold（持つ・保つ）＋up（上へ）\n→ 物事の進行を上から押さえて止めるイメージ\n→ そこから「遅らせる／（強盗が）襲う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 231, "stage": 5, "verb": "come across", "meaning": "偶然見つける、出くわす", "def": "to find or meet something by chance", "ex1": "I came across an old photo of us while cleaning out the closet.", "ja1": "クローゼットを片づけている時、私たちの古い写真を偶然見つけた。", "ex2": "I came across a useful case study on their site.", "ja2": "先方のサイトで役立つ事例を偶然見つけた。", "note": "Stage 6 の come across as と区別", "nuance": "偶然に何かを見つける、予期せぬ発見。come across asと区別。", "groups": ["encounter"], "etymology": "come（来る）＋across（横切って）\n→ ある空間や境界を横切って向こう側に届くイメージ\n→ そこから「偶然見つける、出くわす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M2 2 L14 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M2 14 L14 2\" stroke=\"#B5392F\" stroke-width=\"1.4\" opacity=\"0.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 232, "stage": 5, "verb": "put up with", "meaning": "我慢する、耐える", "def": "to tolerate something unpleasant", "ex1": "I can put up with the noise, but the smell is unbearable.", "ja1": "騒音は我慢できるが、この匂いは耐えられない。", "ex2": "We put up with the slow system for months.", "ja2": "我々は何か月も遅いシステムに耐えた。", "note": "Stage 1 / 2 の put up と区別", "nuance": "tolerate（改まった容認）より口語的。bear（我慢する、より硬い）とほぼ同義で、不快な状況を耐え忍ぶことを表す。", "groups": ["endure"], "etymology": "put（置く）＋up（上へ）＋with（一緒に）\n→ 上向き・完了や増加のイメージ\n→ そこから「我慢する、耐える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M16 46 L48 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><rect x=\"23\" y=\"32\" width=\"18\" height=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M32 15 L32 27 M28 23 L32 27 L36 23\" stroke=\"#C79A3D\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 233, "stage": 5, "verb": "look into", "meaning": "調査する、検討する", "def": "to investigate a matter", "ex1": "The detective agreed to look into the missing car case.", "ja1": "その探偵は行方不明の車の件を調査することに同意した。", "ex2": "We're looking into the cause of the delay.", "ja2": "遅延の原因を調査しています。", "note": "", "nuance": "investigate（改まった調査）より口語的。check（確認する、より軽い）より深く掘り下げて調べるニュアンスを含む。", "groups": ["review_check"], "etymology": "look（見る）＋into（中へ変化）\n→ 物事の内部まで踏み込んで確かめるイメージ\n→ そこから「調査する、検討する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 234, "stage": 5, "verb": "use up", "meaning": "使い切る", "def": "to consume all of something", "ex1": "We used up all the paint before finishing even one wall.", "ja1": "壁を1面塗り終える前に、ペンキを全部使い切ってしまった。", "ex2": "The team used up its budget by August.", "ja2": "チームは8月までに予算を使い切った。", "note": "", "nuance": "finish（単に終える）とは違い、use upは資源や在庫を「完全に使い切る」ことを強調する。run out of（受動的に尽きる）とは主語の視点が逆。", "groups": ["use_up"], "etymology": "use（使う）＋up（上へ）\n→ それ以上は続けられない限界まで達し、そこで打ち切るイメージ\n→ そこから「使い切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 235, "stage": 5, "verb": "get over", "meaning": "立ち直る、克服する", "def": "to recover from an illness, shock, or difficulty", "ex1": "It took him nearly a year to get over the loss of his job.", "ja1": "失業から立ち直るのに、彼はほぼ1年かかった。", "ex2": "It took time to get over the failed release.", "ja2": "失敗したリリースから立ち直るのに時間がかかった。", "note": "", "nuance": "recover from（改まった回復）より口語的。move on（気持ちを切り替える）と似ているが、get overは特に困難や病気からの回復を表す。", "groups": ["move_on_over"], "etymology": "get（得る・～になる）＋over（越えて）\n→ 困難を乗り越えて元の状態に戻るイメージ\n→ そこから「立ち直る、克服する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 236, "stage": 5, "verb": "sit on", "meaning": "（対応を）先延ばしにする、握りつぶす", "def": "to delay dealing with something", "ex1": "The manager just sat on the complaint for weeks without acting.", "ja1": "そのマネージャーは何週間もその苦情を放置し、何も対応しなかった。", "ex2": "Management sat on the report for weeks.", "ja2": "経営陣は報告書を何週間も放置した。", "note": "", "nuance": "ignore（無視する、より一般的）とは違い、sit onは問題や決定を「意図的に放置し、対応を先延ばしにする」ニュアンスを含む。", "groups": [], "etymology": "sit（座る）＋on（接触・継続）\n→ 対応せずそのまま上に乗せて放置するイメージ\n→ そこから「（対応を）先延ばしにする、握りつぶす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(1,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 237, "stage": 5, "verb": "cheer on", "meaning": "声援を送る、応援する", "def": "to encourage someone by shouting support", "ex1": "The whole crowd cheered on the last runner as she crossed the line.", "ja1": "観客全員が、最後のランナーがゴールするまで声援を送った。", "ex2": "The whole office cheered on the presenters.", "ja2": "オフィス全員が発表者を応援した。", "note": "", "nuance": "support（応援する、より一般的）とは違い、cheer onは声を出して「その場で応援する」という直接的な行動を伴う。", "groups": ["cheer_encourage"], "etymology": "cheer（励ます）＋on（接触・継続）\n→ 相手にぴったり寄り添って後押しするイメージ\n→ そこから「声援を送る、応援する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 238, "stage": 5, "verb": "take up*2", "meaning": "（提案を）受け入れる／（問題を）取り上げる", "def": "to accept an offer; to raise a matter for discussion", "ex1": "The board decided to take up the proposal at the next meeting.", "ja1": "取締役会は次の会議でその提案を取り上げることにした。", "ex2": "We'll take up this issue at the steering committee.", "ja2": "この件は運営委員会で取り上げます。", "note": "Stage 4 の take up と区別", "nuance": "accept（単に受け入れる）とは別に、take up*2は提案や問題を「取り上げて検討する」場面でも使う。始める（Stage4）とは別の意味。", "groups": ["accept_take_up"], "etymology": "take（取る）＋up（上へ）\n→ 出された話を持ち上げて取り扱うイメージ\n→ そこから「（提案を）受け入れる／（問題を）取り上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 239, "stage": 5, "verb": "pull away", "meaning": "離れていく、引き離す", "def": "to move away; to move ahead of others", "ex1": "The train slowly pulled away from the platform as I waved goodbye.", "ja1": "私が別れの手を振る中、電車はゆっくりとホームから離れていった。", "ex2": "The leading vendor pulled away from the competition.", "ja2": "首位のベンダーは競合を引き離した。", "note": "", "nuance": "move away（離れていく、より一般的）とほぼ同義。pull backとは違い、pull awayは車や船などが「その場から離れていく」動作によく使う。", "groups": ["pull_out_away"], "etymology": "pull（引く）＋away（遠くへ）\n→ 二つの物や人の距離がどんどん開いていくイメージ\n→ そこから「離れていく、引き離す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 240, "stage": 5, "verb": "own up", "meaning": "白状する、非を認める", "def": "to admit that you did something wrong", "ex1": "After days of denial, he finally owned up to breaking the vase.", "ja1": "何日も否定した末、彼はついに花瓶を割ったことを認めた。", "ex2": "She owned up to the error in the estimate.", "ja2": "彼女は見積もりの誤りを認めた。", "note": "own up to の形で使う", "nuance": "admit（改まった認め）より口語的。confess（告白する、より重い）ほど深刻でなくても、非を認める場面で使える。", "groups": [], "etymology": "own（認める・所有する）＋up（上へ）\n→ 隠していたことを認めて表に差し出すイメージ\n→ そこから「白状する、非を認める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 241, "stage": 5, "verb": "fit in", "meaning": "なじむ、溶け込む", "def": "to be accepted as part of a group", "ex1": "It took a few weeks, but the new intern finally fit in with the team.", "ja1": "数週間かかったが、新しいインターンはついにチームに馴染んだ。", "ex2": "The new member fit in with the team right away.", "ja2": "新メンバーはすぐチームになじんだ。", "note": "Stage 7 に別語義あり", "nuance": "belong（属する、より静的）とは違い、fit inは新しい環境に「馴染んでいくプロセス」を強調する。", "groups": ["adapt_fit_in"], "etymology": "fit（合う）＋in（中へ）\n→ 周囲の内側にすんなり馴染んでいくイメージ\n→ そこから「なじむ、溶け込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 242, "stage": 5, "verb": "stay over", "meaning": "泊まる、外泊する", "def": "to spend the night at someone else's place", "ex1": "My cousin is staying over at our place this weekend.", "ja1": "今週末、いとこがうちに泊まりに来る。", "ex2": "I stayed over near the site before the early cutover.", "ja2": "早朝の切替に備えて現場近くに前泊した。", "note": "", "nuance": "stay（泊まる、より一般的）とほぼ同義。stay overは特に一泊する、外泊する場面でよく使われる。", "groups": [], "etymology": "stay（とどまる）＋over（越えて）\n→ その場に留まって一晩を越すイメージ\n→ そこから「泊まる、外泊する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 243, "stage": 5, "verb": "step out", "meaning": "少し席を外す", "def": "to leave a room or building for a short time", "ex1": "I need to step out for a minute, but I'll be right back.", "ja1": "ちょっと席を外すけど、すぐ戻るね。", "ex2": "He stepped out of the meeting for five minutes.", "ja2": "彼は5分ほど会議を中座した。", "note": "", "nuance": "leave（単に去る）より軽く、ほんの少しの間「席を外す」というニュアンスを含む。go out（外出する）よりも短時間。", "groups": ["exit_leave_briefly"], "etymology": "step（一歩踏み出す）＋out（外へ）\n→ 今いる場所から少しだけ外れるイメージ\n→ そこから「少し席を外す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 244, "stage": 5, "verb": "head off", "meaning": "未然に防ぐ、先回りして止める", "def": "to prevent something from happening", "ex1": "The company headed off the strike by offering a small raise.", "ja1": "その会社はわずかな昇給を提示することで、ストライキを未然に防いだ。", "ex2": "Early testing headed off a major defect.", "ja2": "早期のテストで重大な不具合を未然に防いだ。", "note": "", "nuance": "prevent（改まった防止）より口語的。avoid（避ける、より一般的）とは違い、head offは問題が起きる前に先回りして対処するニュアンスを含む。", "groups": [], "etymology": "head（向かう）＋off（離れて）\n→ 動いていたものから電源やつながりを切り離して止めるイメージ\n→ そこから「未然に防ぐ、先回りして止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 245, "stage": 5, "verb": "fill in for", "meaning": "代理を務める", "def": "to do someone's job temporarily while they are away", "ex1": "Could you fill in for me at the front desk during lunch?", "ja1": "お昼の間、受付で私の代わりをしてもらえますか。", "ex2": "I'll fill in for the PM while he's on leave.", "ja2": "PMの休暇中は私が代理を務めます。", "note": "Stage 5 の fill in（記入する）と区別", "nuance": "cover for（代理を務める、かばう）とほぼ同義だが、fill in forは特に一時的に人の穴を「埋める」場面で使われる。", "groups": ["help_cover"], "etymology": "fill（満たす）＋in（中へ）＋for（求めて）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「代理を務める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 26 L24 46 Q24 48 26 48 L38 48 Q40 48 40 46 L42 26\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M18 26 L46 26\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 14 L32 22 M28 18 L32 22 L36 18\" stroke=\"#C79A3D\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 246, "stage": 5, "verb": "mix up", "meaning": "混同する、取り違える", "def": "to confuse one thing with another", "ex1": "The twins look so alike that people constantly mix them up.", "ja1": "その双子はあまりに似ていて、みんな絶えず混同してしまう。", "ex2": "We mixed up the file versions and sent the old one.", "ja2": "ファイルの版を取り違えて古いものを送ってしまった。", "note": "", "nuance": "confuse（混同する、より一般的）とほぼ同義。mistake A for B（AをBと間違える）と似た状況で使う。", "groups": [], "etymology": "mix（混ぜる）＋up（上へ）\n→ 複数の物が上でごちゃ混ぜに混ざるイメージ\n→ そこから「混同する、取り違える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(2,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/><circle cx=\"32\" cy=\"20\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 247, "stage": 5, "verb": "pick up*3", "meaning": "回復する、勢いを増す", "def": "to improve or increase", "ex1": "Sales picked up right after the holiday advertising started.", "ja1": "休日向けの広告が始まった途端、売上は勢いを増した。", "ex2": "Sales picked up after the campaign.", "ja2": "キャンペーンの後、売上が回復した。", "note": "Stage 2 / 3 に別語義あり", "nuance": "recover（回復する、より一般的）とは違い、pick up*3は売上や勢いが「上向きに転じる」ビジネス文脈でもよく使われる。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 落ちていた調子が上向きに持ち直すイメージ\n→ そこから「回復する、勢いを増す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 248, "stage": 5, "verb": "tell apart", "meaning": "見分ける、区別する", "def": "to distinguish between two similar things", "ex1": "The two brands look almost identical; I can barely tell them apart.", "ja1": "その2つのブランドはほぼ同じに見えて、ほとんど見分けがつかない。", "ex2": "It's hard to tell the two plans apart.", "ja2": "2つのプランを見分けるのは難しい。", "note": "tell A and B apart の語順に注意", "nuance": "distinguish（改まった区別）より口語的。tell A from B（AとBを見分ける）の形でもよく使う。", "groups": ["distinguish"], "etymology": "tell（伝える）＋apart（ばらばらに）\n→ 一つだった物が分かれていくイメージ\n→ そこから「見分ける、区別する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L0 8 L8 14 M8 2 L16 8 L8 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 249, "stage": 5, "verb": "clear up", "meaning": "（天気が）晴れる／（誤解を）解く", "def": "to become fine; to resolve confusion or a problem", "ex1": "The sky cleared up just in time for the outdoor wedding.", "ja1": "屋外での結婚式にちょうど間に合うタイミングで、空は晴れた。", "ex2": "Let's clear up the misunderstanding about the scope.", "ja2": "スコープに関する誤解を解きましょう。", "note": "", "nuance": "become clear（改まった言い方）より口語的。天気が晴れる意味と、誤解を「解消する」意味の両方を持つ多義語。", "groups": [], "etymology": "clear（片づける・澄ませる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（天気が）晴れる／（誤解を）解く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M40 16 L24 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M24 44 L16 50 M24 44 L20 50 M24 44 L28 50\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 250, "stage": 5, "verb": "dive in", "meaning": "勢いよく取りかかる", "def": "to start doing something eagerly, often without preparing", "ex1": "Without reading the manual, he just dove in and started assembling it.", "ja1": "説明書も読まずに、彼はいきなり組み立てに取りかかった。", "ex2": "Let's not dive in before we agree on the requirements.", "ja2": "要件が固まる前に着手するのはやめましょう。", "note": "", "nuance": "start（単に始める）とは違い、dive inは準備や様子見をせず「いきなり勢いよく取りかかる」という積極性を強調する。", "groups": ["dive_jump_in"], "etymology": "dive（飛び込む）＋in（中へ）\n→ 深く考えず内側へ勢いよく飛び込むイメージ\n→ そこから「勢いよく取りかかる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 251, "stage": 5, "verb": "cut off", "meaning": "遮断する、停止する", "def": "to stop a supply or disconnect something", "ex1": "The storm cut off power to the whole neighborhood for two days.", "ja1": "その嵐で近所一帯の電力が2日間遮断された。", "ex2": "Their access was cut off after the contract ended.", "ja2": "契約終了後、アクセス権が停止された。", "note": "Stage 6 / 7 に別語義あり", "nuance": "disconnect（改まった切断）より口語的。cut down（減らす）とは別の意味で、電気や供給を完全に「遮断する」ことを表す。", "groups": ["cut_off_senses"], "etymology": "cut（切る）＋off（離れて）\n→ 動いていたものから電源やつながりを切り離して止めるイメージ\n→ そこから「遮断する、停止する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 252, "stage": 5, "verb": "miss out", "meaning": "（機会を）逃す", "def": "to lose a chance to do or have something", "ex1": "I fell asleep and missed out on the entire second half of the game.", "ja1": "眠ってしまって、試合の後半をまるまる見逃した。", "ex2": "We missed out on the deal by one day.", "ja2": "1日の差で商談を逃した。", "note": "miss out on の形が多い", "nuance": "lose the chance（改まった言い方）より口語的。fail to（〜できない）とは違い、miss outは得られたはずの機会を「逃してしまう」という損失感を含む。", "groups": [], "etymology": "miss（逃す）＋out（外へ）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「（機会を）逃す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 253, "stage": 6, "verb": "sort out", "meaning": "整理する、解決する", "def": "to organize something; to resolve a problem", "ex1": "It took all weekend to sort out the mess in the garage.", "ja1": "ガレージの散らかりを整理するのに、週末まるまるかかった。", "ex2": "Let's sort out the billing issue first.", "ja2": "まず請求の問題を片づけましょう。", "note": "", "nuance": "organize（改まった整理）より口語的。clean up（片づける）とは違い、sort outは物事の混乱や問題を「整理して解決する」ニュアンスを含む。", "groups": ["organize"], "etymology": "sort（分類する）＋out（外へ）\n→ こんがらがった物事を外に出して整理するイメージ\n→ そこから「整理する、解決する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><rect x=\"18\" y=\"38\" width=\"28\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"20\" y=\"28\" width=\"24\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"22\" y=\"18\" width=\"20\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 254, "stage": 6, "verb": "break out", "meaning": "（火事・争いが）突然起こる", "def": "to start suddenly, usually of something bad", "ex1": "A fire broke out in the kitchen just minutes before closing.", "ja1": "閉店のわずか数分前に、厨房で火事が起きた。", "ex2": "A dispute broke out over the scope of work.", "ja2": "作業範囲をめぐって争いが起きた。", "note": "", "nuance": "happen（単に起こる）とは違い、break outは火事や争いなど、望ましくない事態が「突然、勢いよく発生する」ことを強調する。", "groups": [], "etymology": "break（壊す・分ける）＋out（外へ）\n→ 抑えられていたものが一気に外へ噴き出すイメージ\n→ そこから「（火事・争いが）突然起こる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 255, "stage": 6, "verb": "look through", "meaning": "ざっと目を通す", "def": "to read or examine something quickly", "ex1": "I only had time to look through the report, not read every page.", "ja1": "レポートにざっと目を通す時間しかなく、全ページ読む余裕はなかった。", "ex2": "Please look through the draft before the meeting.", "ja2": "会議の前に草案に目を通してください。", "note": "", "nuance": "read（読む、より一般的）とは違い、look throughは全部を丁寧にではなく「ざっと目を通す」という軽さを表す。go through（詳しく調べる）より簡易的。", "groups": ["skim_review"], "etymology": "look（見る）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「ざっと目を通す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-7,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 256, "stage": 6, "verb": "give off", "meaning": "（においや光・熱を）発する", "def": "to produce and send out a smell, light, or heat", "ex1": "The old fridge gives off a strange humming noise all night.", "ja1": "その古い冷蔵庫は一晩中、変なうなり音を発している。", "ex2": "The device gives off a lot of heat under load.", "ja2": "その機器は負荷時に多くの熱を発する。", "note": "", "nuance": "emit（改まった放出）より口語的。においや光、熱などが自然に「発せられる」ことを表す。", "groups": [], "etymology": "give（与える）＋off（離れて）\n→ においや光が体から離れて外へ放たれるイメージ\n→ そこから「（においや光・熱を）発する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><path d=\"M18 40 Q18 30 26 28 L42 24 Q46 23 46 27 Q46 30 42 31 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 46 24 46 L38 46\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 257, "stage": 6, "verb": "pick through", "meaning": "丹念に選り分ける、調べる", "def": "to search carefully through a large number of things", "ex1": "She spent an hour picking through the bargain bin for the right size.", "ja1": "彼女はちょうどいいサイズを求めて、1時間かけて特価品の山を選り分けた。", "ex2": "We picked through the logs to find the error.", "ja2": "エラーを見つけるためログを丹念に調べた。", "note": "", "nuance": "sort through（整理しながら見る）と似ているが、pick throughは特に丁寧に、時間をかけて選り分けるニュアンスが強い。", "groups": [], "etymology": "pick（つまむ・選ぶ）＋through（通り抜けて）\n→ 資料の隅々まで目を通り抜けさせるイメージ\n→ そこから「丹念に選り分ける、調べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 258, "stage": 6, "verb": "wear out", "meaning": "すり減る／疲れ果てさせる", "def": "to become unusable through use; to exhaust someone", "ex1": "These running shoes wore out after just three months.", "ja1": "このランニングシューズは、たった3ヶ月ですり減ってしまった。", "ex2": "The long negotiation wore out the team.", "ja2": "長い交渉でチームは疲れ果てた。", "note": "", "nuance": "get tired（改まった疲労）より口語的。wear out物には「すり減る」、人には「疲れ果てさせる」という両方の意味で使う多義語。", "groups": ["break_malfunction"], "etymology": "wear（身につける・すり減らす）＋out（外へ）\n→ 内側にあった力や在庫が外へ出尽くして、空っぽになるイメージ\n→ そこから「すり減る／疲れ果てさせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-10,32,32)\"><path d=\"M24 20 L18 26 L22 32 L26 28 L26 48 L38 48 L38 28 L42 32 L46 26 L40 20 Q36 24 32 24 Q28 24 24 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.3\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 259, "stage": 6, "verb": "fill out", "meaning": "（書類に）記入する", "def": "to complete a form by writing information in it", "ex1": "Please fill out this form before you see the doctor.", "ja1": "診察を受ける前に、この書類にご記入ください。", "ex2": "Please fill out the survey after the training.", "ja2": "研修後にアンケートに記入してください。", "note": "fill in とほぼ同義。米では fill out が一般的", "nuance": "fill in（記入する、より一般的）とほぼ同義。fill outは特にアメリカ英語で書類全体に記入する場面でよく使われる。", "groups": ["fill_form"], "etymology": "fill（満たす）＋out（外へ）\n→ 書類の空欄を埋めて外部へ提出するイメージ\n→ そこから「（書類に）記入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-12,32,32)\"><path d=\"M22 26 L24 46 Q24 48 26 48 L38 48 Q40 48 40 46 L42 26\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M18 26 L46 26\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 14 L32 22 M28 18 L32 22 L36 18\" stroke=\"#C79A3D\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 260, "stage": 6, "verb": "break off", "meaning": "中断する、打ち切る", "def": "to stop suddenly; to end a relationship or talks", "ex1": "They broke off the negotiations without any warning.", "ja1": "彼らは何の予告もなく交渉を打ち切った。", "ex2": "The two companies broke off negotiations.", "ja2": "2社は交渉を打ち切った。", "note": "", "nuance": "stop（単に止める）とは違い、break offは交渉や関係を「途中で急に打ち切る」という強い決断を含む。", "groups": ["cancel_stop"], "etymology": "break（壊す・分ける）＋off（離れて）\n→ 続いていた物事を途中でぷつりと切り離すイメージ\n→ そこから「中断する、打ち切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 261, "stage": 6, "verb": "pass off", "meaning": "（偽って）通す、〜として通用させる", "def": "to falsely present something as something else", "ex1": "He tried to pass off the copy as an original painting.", "ja1": "彼はその複製を本物の絵画として通そうとした。", "ex2": "Don't pass off an estimate as a firm quotation.", "ja2": "概算を確定見積もりとして通さないでください。", "note": "pass A off as B の形", "nuance": "pretend（改まったふり）より口語的。fake（偽物、より直接的）と似ているが、pass offは偽物を本物として「他人に信じ込ませる」プロセスを表す。", "groups": ["pretend_pass_off"], "etymology": "pass（通す・渡す）＋off（離れて）\n→ 本物から離れた偽りをそれらしく通すイメージ\n→ そこから「（偽って）通す、〜として通用させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 262, "stage": 6, "verb": "make out*3", "meaning": "〜であるかのように言う、主張する", "def": "to claim or suggest that something is true", "ex1": "She made it out like the whole idea had been hers from the start.", "ja1": "彼女は最初からそれが全部自分のアイデアだったかのように主張した。", "ex2": "The vendor made out that the delay was our fault.", "ja2": "その業者は遅延が我々のせいだと主張した。", "note": "Stage 4 の make out*2 と区別", "nuance": "claim（改まった主張）より口語的。pretend（〜のふりをする）と似ているが、make out*3は事実と違うことを強く言い張るニュアンス。", "groups": ["pretend_pass_off"], "etymology": "make（作る）＋out（外へ）\n→ 事実と違うことを外に向けて装うイメージ\n→ そこから「〜であるかのように言う、主張する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 263, "stage": 6, "verb": "come on to", "meaning": "言い寄る", "def": "to show sexual interest in someone", "ex1": "Some guy at the bar kept coming on to her all night.", "ja1": "バーにいたある男が、一晩中彼女に言い寄り続けた。", "ex2": "Coming on to a colleague can be harassment.", "ja2": "同僚に言い寄る行為はハラスメントになりうる。", "note": "", "nuance": "flirt with（口説く、より一般的）とほぼ同義だが、come on toはやや強引・しつこい印象を与えることがある。", "groups": ["dating_romance"], "etymology": "come（来る）＋on（接触・継続）＋to（～へ）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「言い寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 264, "stage": 6, "verb": "come off", "meaning": "取れる、外れる／うまくいく", "def": "to become detached; to succeed as planned", "ex1": "The button came off my coat on the very first day I wore it.", "ja1": "着た初日に、コートのボタンが取れてしまった。", "ex2": "The event came off better than expected.", "ja2": "イベントは予想以上にうまくいった。", "note": "", "nuance": "fall off（落ちる、より一般的）とは違い、come offはボタンなど付いていた物が「取れる」動作、または計画が「うまくいく」という別の意味も持つ。", "groups": ["succeed"], "etymology": "come（来る）＋off（離れて）\n→ 固定されていた物が離れて外れるイメージ\n→ そこから「取れる、外れる／うまくいく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 265, "stage": 6, "verb": "throw in", "meaning": "おまけに付ける", "def": "to add something extra without charging for it", "ex1": "The salesman threw in a free case if we bought the phone that day.", "ja1": "その販売員は、当日携帯を買えばケースをおまけに付けると言った。", "ex2": "We threw in three months of support at no charge.", "ja2": "3か月分のサポートを無償で付けた。", "note": "", "nuance": "include（含める、より一般的）とは違い、throw inは購入時などに追加の物を「おまけとして付ける」という気前の良さを含む。", "groups": [], "etymology": "throw（投げる）＋in（中へ）\n→ 本体の内側にもう一つ含めてしまうイメージ\n→ そこから「おまけに付ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 266, "stage": 6, "verb": "deal with", "meaning": "対処する、扱う", "def": "to take action about a problem or person", "ex1": "I'll deal with the complaints tomorrow; I'm too tired tonight.", "ja1": "苦情には明日対処するよ、今夜は疲れすぎてる。", "ex2": "She deals with customer complaints.", "ja2": "彼女は顧客からの苦情に対応している。", "note": "", "nuance": "handle（対処する、より一般的）とほぼ同義。cope with（耐えて対処する）より、問題そのものに直接取り組むニュアンス。", "groups": [], "etymology": "deal（扱う）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「対処する、扱う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 267, "stage": 6, "verb": "come down with", "meaning": "（病気に）かかる", "def": "to become ill with a particular illness", "ex1": "Half the office came down with the flu the same week.", "ja1": "オフィスの半分が同じ週にインフルエンザにかかった。", "ex2": "Two members came down with the flu before the release.", "ja2": "リリース前にメンバー2名がインフルエンザにかかった。", "note": "", "nuance": "get sick（改まった言い方）より口語的。catch（病気にかかる、より一般的）と似ているが、come down withは徐々に発症する軽い病気によく使う。", "groups": [], "etymology": "come（来る）＋down（下へ）＋with（一緒に）\n→ 病気を体の中に一緒に持ち込むイメージ\n→ そこから「（病気に）かかる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 268, "stage": 6, "verb": "hop on", "meaning": "ひょいと乗る、（会議に）参加する", "def": "to get on something quickly; to join a call", "ex1": "Just hop on the call whenever you're ready; we haven't started yet.", "ja1": "準備ができたらいつでも通話に参加して、まだ始まってないから。", "ex2": "Can you hop on the call for five minutes?", "ja2": "5分ほど電話会議に入ってもらえますか。", "note": "オンライン会議に「入る」意味でもよく使う", "nuance": "get on（乗り物に乗る、より一般的）より軽く、hop onは「ひょいと気軽に乗る」という身軽さを表す。会議に「途中参加する」意味でも使う。", "groups": ["board_vehicle"], "etymology": "hop（ぴょんと跳ぶ）＋on（接触・継続）\n→ 乗り物の上に乗っかるイメージ\n→ そこから「ひょいと乗る、（会議に）参加する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 269, "stage": 6, "verb": "drop off", "meaning": "送り届ける／（数量が）減る", "def": "to deliver someone or something; to decrease", "ex1": "I can drop you off at the station on my way to work.", "ja1": "仕事に行くついでに、駅まで送っていけるよ。", "ex2": "Inquiries dropped off after the campaign ended.", "ja2": "キャンペーン終了後に問い合わせが減った。", "note": "", "nuance": "drop（落とす、より一般的）とは違い、drop offは人や物を目的地へ「送り届ける」、または数値が「徐々に減る」ことを表す。", "groups": [], "etymology": "drop（ポトリと落ちる）＋off（離れて）\n→ 人や物を運び、目的地で切り離して降ろすイメージ\n→ そこから「送り届ける／（数量が）減る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 270, "stage": 6, "verb": "go along with", "meaning": "同意する、（方針に）従う", "def": "to agree with a plan, idea, or person", "ex1": "Reluctantly, he went along with the team's decision.", "ja1": "彼は不本意ながら、チームの決定に従った。", "ex2": "We went along with the client's schedule.", "ja2": "我々は顧客のスケジュールに合わせた。", "note": "", "nuance": "agree（改まった同意）より口語的。go along withは自分の意見より「相手の方針に合わせる」という消極的な同意を含む。", "groups": ["comply_defy"], "etymology": "go（行く）＋along（沿って）＋with（一緒に）\n→ 一緒に・並んで進むイメージ\n→ そこから「同意する、（方針に）従う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 271, "stage": 6, "verb": "go against", "meaning": "反する、逆らう", "def": "to oppose or conflict with something", "ex1": "Her final decision went completely against her parents' wishes.", "ja1": "彼女の最終的な決断は、両親の望みに完全に反していた。", "ex2": "This approach goes against our security policy.", "ja2": "この方法は当社のセキュリティ方針に反する。", "note": "", "nuance": "oppose（改まった反対）より口語的。go against one's wishesの形で、期待や希望に「反する」ことを表す。", "groups": ["comply_defy"], "etymology": "go（行く）＋against（逆らって）\n→ 向かい合って押し返す・反対するイメージ\n→ そこから「反する、逆らう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L10 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M13 2 L13 14\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 272, "stage": 6, "verb": "get out of", "meaning": "逃れる、免れる", "def": "to avoid a duty or an obligation", "ex1": "He managed to get out of jury duty by claiming he was self-employed.", "ja1": "彼は自営業だと主張して、陪審員の義務を逃れた。", "ex2": "We can't get out of the contract without a penalty.", "ja2": "違約金なしに契約から抜けることはできない。", "note": "", "nuance": "avoid（避ける、より一般的）とは違い、get out ofは義務や責任を「うまく逃れる」というずる賢さを含むことがある。", "groups": ["avoid_evade"], "etymology": "get（得る・～になる）＋out（外へ）＋of（～の）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「逃れる、免れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-7,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 273, "stage": 6, "verb": "get at", "meaning": "言おうとする、ほのめかす", "def": "to try to express or suggest something", "ex1": "I don't quite get at what you're trying to say.", "ja1": "あなたが何を言おうとしているのか、いまいち分からない。", "ex2": "I see what you're getting at about the risk.", "ja2": "リスクについておっしゃりたいことは分かります。", "note": "", "nuance": "mean（意味する、より一般的）とは違い、get atは相手が遠回しに「何を言おうとしているか」を推測する場面で使う。", "groups": [], "etymology": "get（得る・～になる）＋at（～めがけて）\n→ ピンポイントで対象を狙うイメージ\n→ そこから「言おうとする、ほのめかす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 274, "stage": 6, "verb": "step back", "meaning": "一歩引いて考える", "def": "to pause and look at a situation from a distance", "ex1": "Take a step back and look at the whole picture before deciding.", "ja1": "決める前に、一歩引いて全体を見てみて。", "ex2": "Let's step back and revisit the original goal.", "ja2": "一度立ち返って当初の目的を見直しましょう。", "note": "", "nuance": "reconsider（改まった再考）より、step backは物理的・心理的に「一歩引いて全体を見る」という視点の転換を強調する。", "groups": ["reflect_step_back"], "etymology": "step（一歩踏み出す）＋back（後ろ・元へ）\n→ 一歩下がって全体を見渡すイメージ\n→ そこから「一歩引いて考える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-11,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 275, "stage": 6, "verb": "play along", "meaning": "話を合わせる", "def": "to pretend to agree in order to avoid trouble", "ex1": "I didn't believe his story, but I played along to avoid an argument.", "ja1": "彼の話は信じなかったが、喧嘩を避けるために話を合わせた。", "ex2": "I played along until we had the full picture.", "ja2": "全体像がつかめるまで話を合わせておいた。", "note": "", "nuance": "agree（本当に同意する）とは違い、play alongは内心では違うと思いながらも「表面上話を合わせる」という演技的なニュアンスを含む。", "groups": ["pretend_pass_off"], "etymology": "play（遊ぶ・演じる）＋along（沿って）\n→ 相手の話の流れに調子を合わせて進むイメージ\n→ そこから「話を合わせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M27 24 L27 40 L41 32 Z\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 276, "stage": 6, "verb": "take back to", "meaning": "（元の場所へ）返しに行く、連れ戻す", "def": "to return someone or something to a place", "ex1": "He drove an hour to take the wrong package back to the store.", "ja1": "彼は間違って届いた荷物を店に返しに行くため、1時間車を走らせた。", "ex2": "Please take these documents back to the client.", "ja2": "この書類を顧客に返却してきてください。", "note": "", "nuance": "return（返す、より一般的）とは違い、take back toは物や人を「元あった場所へ」わざわざ戻しに行く動作を強調する。", "groups": ["return"], "etymology": "take（取る）＋back（後ろ・元へ）＋to（～へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「（元の場所へ）返しに行く、連れ戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 277, "stage": 6, "verb": "bump into", "meaning": "偶然出会う", "def": "to meet someone by chance", "ex1": "I bumped into my old teacher at the airport of all places.", "ja1": "よりによって空港で、昔の先生に偶然出会った。", "ex2": "I bumped into our old client at the conference.", "ja2": "カンファレンスで昔の顧客に偶然会った。", "note": "run into とほぼ同義", "nuance": "run into（偶然出会う、より一般的）とほぼ同義。bump intoはより口語的で、ばったり感が強い。", "groups": ["encounter"], "etymology": "bump（ぶつかる）＋into（中へ変化）\n→ 予期せず何かの内側に入り込んでしまうイメージ\n→ そこから「偶然出会う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 278, "stage": 6, "verb": "count on", "meaning": "頼りにする、当てにする", "def": "to rely on someone or something", "ex1": "You can always count on her to show up early.", "ja1": "彼女なら早く来てくれると、いつも頼りにできる。", "ex2": "We're counting on the vendor to deliver by Friday.", "ja2": "金曜までの納品を業者に期待しています。", "note": "", "nuance": "rely on（頼る、より一般的）とほぼ同義。depend on（依存する、より重い）より、信頼して当てにするニュアンスが強い。", "groups": ["rely_on"], "etymology": "count（数える）＋on（接触・継続）\n→ 相手の上に体重を預けるようによりかかるイメージ\n→ そこから「頼りにする、当てにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 279, "stage": 6, "verb": "hear from", "meaning": "〜から連絡をもらう", "def": "to receive news or a message from someone", "ex1": "I still haven't heard from him about the weekend plans.", "ja1": "週末の予定について、まだ彼から連絡をもらっていない。", "ex2": "We haven't heard from the client since Tuesday.", "ja2": "火曜以降、顧客から連絡がありません。", "note": "", "nuance": "get a message from（改まった言い方）より口語的。hear fromは特に久しぶりの連絡や返事を待っている時に使う。", "groups": ["contact_related"], "etymology": "hear（聞く）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「〜から連絡をもらう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(11,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 280, "stage": 6, "verb": "throw up", "meaning": "吐く", "def": "to vomit", "ex1": "The turbulence was so bad that a few passengers threw up.", "ja1": "揺れがあまりにひどく、乗客の何人かは吐いてしまった。", "ex2": "One participant threw up and left the training early.", "ja2": "参加者1名が体調を崩し研修を早退した。", "note": "", "nuance": "vomit（改まった言い方）と同義だが、throw upの方が日常会話で圧倒的によく使われる口語表現。", "groups": [], "etymology": "throw（投げる）＋up（上へ）\n→ 胃の内容物が上へ込み上げてくるイメージ\n→ そこから「吐く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 281, "stage": 6, "verb": "get back at", "meaning": "仕返しをする", "def": "to take revenge on someone", "ex1": "Instead of getting back at him, she just walked away.", "ja1": "彼女は彼に仕返しをする代わりに、ただその場を立ち去った。", "ex2": "Getting back at a colleague never helps the team.", "ja2": "同僚に仕返ししてもチームのためにならない。", "note": "", "nuance": "revenge（改まった復讐）より口語的。get evenとほぼ同義で、仕返しをするというカジュアルな言い方。", "groups": ["revenge_group"], "etymology": "get（得る・～になる）＋back（後ろ・元へ）＋at（～めがけて）\n→ 元の場所や状態に戻るイメージ\n→ そこから「仕返しをする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 282, "stage": 6, "verb": "start off", "meaning": "まず〜から始める", "def": "to begin something in a particular way", "ex1": "Let's start off with a quick review of last week's homework.", "ja1": "まずは先週の宿題の簡単な復習から始めましょう。", "ex2": "Let's start off with a review of last week's actions.", "ja2": "先週の宿題の確認から始めましょう。", "note": "", "nuance": "begin with（改まった開始）より口語的。start off byの形で、物事の「まず最初のステップ」を表す。", "groups": ["begin"], "etymology": "start（始める）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「まず〜から始める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><circle cx=\"32\" cy=\"26\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M26 38 L38 38 M28 44 L36 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 283, "stage": 6, "verb": "check in with", "meaning": "（人に）状況を確認する、連絡を取る", "def": "to contact someone to see how things are going", "ex1": "My manager checks in with me every Monday morning.", "ja1": "上司は毎週月曜の朝、私の状況を確認してくる。", "ex2": "I'll check in with the team before the deadline.", "ja2": "締切前にチームの状況を確認します。", "note": "", "nuance": "check on someone（様子を確認する、より一般的）とほぼ同義。check in withは特に定期的な状況確認のニュアンスを含む。", "groups": ["contact_related"], "etymology": "check（確認する）＋in（中へ）＋with（一緒に）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（人に）状況を確認する、連絡を取る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 284, "stage": 6, "verb": "fall apart", "meaning": "ばらばらになる、崩壊する", "def": "to break into pieces; to fail completely", "ex1": "Their whole plan fell apart the moment the sponsor pulled out.", "ja1": "スポンサーが手を引いた瞬間、彼らの計画は全て崩壊した。", "ex2": "The plan fell apart when the budget was cut.", "ja2": "予算が削られて計画は崩れた。", "note": "", "nuance": "collapse（改まった崩壊）より口語的。break down（故障する）とは違い、fall apartは計画や関係が「ばらばらに崩れる」ことを表す。", "groups": ["break_up_apart"], "etymology": "fall（落ちる）＋apart（ばらばらに）\n→ 一つだった物が分かれていくイメージ\n→ そこから「ばらばらになる、崩壊する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L0 8 L8 14 M8 2 L16 8 L8 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 285, "stage": 6, "verb": "pull up", "meaning": "（車が）止まる、止める", "def": "to stop a vehicle", "ex1": "A taxi pulled up right outside just as it started to rain.", "ja1": "雨が降り始めたちょうどその時、外にタクシーが止まった。", "ex2": "The shuttle pulled up at the main entrance.", "ja2": "送迎車が正面玄関に止まった。", "note": "Stage 7 / 8 に別語義あり", "nuance": "stop（単に止まる）とは違い、pull upは車が「特定の場所にすっと止まる」という動作を具体的に表す。", "groups": ["pull_over_stop_car"], "etymology": "pull（引く）＋up（上へ）\n→ それ以上は続けられない限界まで達し、そこで打ち切るイメージ\n→ そこから「（車が）止まる、止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 286, "stage": 6, "verb": "pick up*4", "meaning": "（電話に）出る", "def": "to answer the telephone", "ex1": "I called three times, but nobody picked up.", "ja1": "3回電話したが、誰も出なかった。", "ex2": "Please pick up if the client calls.", "ja2": "顧客から電話があったら出てください。", "note": "Stage 2 / 3 / 5 に別語義あり", "nuance": "answer the phone（改まった言い方）より口語的。pick up*4は電話に「出る」という最も日常的な言い方。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（電話に）出る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M26 20 L26 34 M38 20 L38 34\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M26 34 Q32 40 38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 287, "stage": 6, "verb": "follow through", "meaning": "最後までやり遂げる", "def": "to complete something you started or promised", "ex1": "It's easy to make plans, but hard to actually follow through on them.", "ja1": "計画を立てるのは簡単だが、実際に最後までやり遂げるのは難しい。", "ex2": "We need to follow through on the action items.", "ja2": "アクション項目を最後までやり切る必要がある。", "note": "", "nuance": "complete（改まった完了）より、follow throughは始めたことを「最後まで責任を持ってやり遂げる」という継続性を強調する。", "groups": ["accomplish_through"], "etymology": "follow（従う）＋through（通り抜けて）\n→ 始めから終わりまで一気に通り抜けるイメージ\n→ そこから「最後までやり遂げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 288, "stage": 6, "verb": "settle in", "meaning": "（新しい環境に）慣れる", "def": "to become comfortable in a new place or job", "ex1": "It took the new family a few months to settle in.", "ja1": "その新しい家族が新しい環境に慣れるまで、数ヶ月かかった。", "ex2": "The new hire is settling in well.", "ja2": "新入社員はうまく職場になじんでいる。", "note": "", "nuance": "adjust（改まった適応）より口語的。get used to（慣れる、より一般的）と似ているが、settle inは新しい家や職場に「落ち着いて馴染む」プロセスを表す。", "groups": ["adapt_fit_in"], "etymology": "settle（落ち着かせる）＋in（中へ）\n→ 新しい環境の内側に少しずつ馴染むイメージ\n→ そこから「（新しい環境に）慣れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 289, "stage": 6, "verb": "take out on", "meaning": "八つ当たりする", "def": "to direct your anger at someone who is not responsible", "ex1": "He was having a bad day and ended up taking it out on his coworkers.", "ja1": "彼はついてない一日だったせいで、結局同僚に八つ当たりしてしまった。", "ex2": "Don't take the client's pressure out on your team.", "ja2": "顧客からの圧力をチームに八つ当たりしないでください。", "note": "take it out on someone の形", "nuance": "blame（非難する、より直接的）とは違い、take out onは自分の怒りやストレスを「無関係な人にぶつける」という八つ当たりのニュアンスを含む。", "groups": ["revenge_group"], "etymology": "take（取る）＋out（外へ）＋on（接触・継続）\n→ 内側から外へ・出現や消失、完全にやり切るイメージ\n→ そこから「八つ当たりする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 290, "stage": 6, "verb": "sign off", "meaning": "承認する／（作業を）終える", "def": "to give final approval; to finish for the day", "ex1": "The manager signed off on the budget without even reading it fully.", "ja1": "そのマネージャーは最後まで読みもせずに予算を承認した。", "ex2": "The client signed off on the design document.", "ja2": "顧客が設計書を承認した。", "note": "承認の意味では sign off on", "nuance": "approve（改まった承認）より口語的。finish（単に終える）とは違い、sign offは正式な確認や署名を伴う完了を表す。", "groups": [], "etymology": "sign（署名する）＋off（離れて）\n→ 作業から手を離し、区切りをつけるイメージ\n→ そこから「承認する／（作業を）終える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M20 44 L38 26 L44 32 L26 50 L18 50 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/><path d=\"M38 26 L42 22\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 291, "stage": 6, "verb": "talk over", "meaning": "じっくり話し合う", "def": "to discuss something thoroughly", "ex1": "We stayed up late talking over the pros and cons of the offer.", "ja1": "私たちはその提案の長所と短所を、夜遅くまでじっくり話し合った。", "ex2": "Let's talk over the options before deciding.", "ja2": "決める前に選択肢をじっくり話し合いましょう。", "note": "", "nuance": "discuss（改まった議論）より、talk overは時間をかけて「じっくり話し合う」という丁寧さを強調する。", "groups": ["discuss_thoroughly"], "etymology": "talk（話す）＋over（越えて）\n→ 話題のあちこちに目を通しながら検討するイメージ\n→ そこから「じっくり話し合う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 292, "stage": 6, "verb": "catch out", "meaning": "見破る、ぼろを出させる", "def": "to discover that someone is lying or mistaken", "ex1": "The teacher caught him out with a question he clearly hadn't prepared for.", "ja1": "先生は彼が明らかに準備していなかった質問で、ぼろを出させた。", "ex2": "The audit caught out several errors in the records.", "ja2": "監査で記録の誤りがいくつか露見した。", "note": "", "nuance": "expose（改まった暴露）より口語的。catch outは相手のミスやうそを「見つけて追い詰める」という対人関係のニュアンスを含む。", "groups": [], "etymology": "catch（捕まえる）＋out（外へ）\n→ 隠れていた事実が表に出て、はっきり見えてくるイメージ\n→ そこから「見破る、ぼろを出させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 293, "stage": 6, "verb": "eat up", "meaning": "平らげる／（時間・資源を）食う", "def": "to eat all of something; to consume a lot of resources", "ex1": "The kids ate up the entire pizza before I even sat down.", "ja1": "私が座る前に、子供たちはピザを丸ごと平らげてしまった。", "ex2": "Meetings eat up half of my week.", "ja2": "会議が週の半分を食いつぶしている。", "note": "", "nuance": "finish eating（改まった言い方）より口語的。use up（使い切る、より一般的）と似た形で、食べ物や時間・資源を「すっかり消費する」ことを表す。", "groups": ["spend_time_effort"], "etymology": "eat（食べる）＋up（上へ）\n→ 出された物や時間を残さず食い尽くすイメージ\n→ そこから「平らげる／（時間・資源を）食う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 294, "stage": 6, "verb": "call out", "meaning": "大声で呼ぶ／公然と批判する", "def": "to shout to get attention; to criticize someone publicly", "ex1": "The activist called out the company for its false advertising.", "ja1": "その活動家は、虚偽広告についてその会社を公然と批判した。", "ex2": "He called out the vendor for missing the deadline.", "ja2": "彼は納期を守らなかった業者を公然と批判した。", "note": "Stage 7 に別語義あり", "nuance": "shout（叫ぶ、より一般的）とは違い、call outはさらに「公然と批判する」という意味でも使われる多義語。", "groups": ["speak_loudly"], "etymology": "call（呼ぶ）＋out（外へ）\n→ 声や非難を外に向けて張り上げるイメージ\n→ そこから「大声で呼ぶ／公然と批判する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 295, "stage": 6, "verb": "check out*3", "meaning": "確認が取れる、裏が取れる", "def": "to be found to be correct or true after checking", "ex1": "It took two days, but the alibi finally checked out.", "ja1": "2日かかったが、そのアリバイはついに裏が取れた。", "ex2": "The figures check out against the invoice.", "ja2": "数値は請求書と一致している。", "note": "Stage 2 / 3 に別語義あり", "nuance": "verify（改まった検証）より口語的。check out*3は情報や話の「裏付けが取れる」という結果に焦点がある。", "groups": ["confirm_check"], "etymology": "check（確認する）＋out（外へ）\n→ 事実の裏付けが表に出て確認できるイメージ\n→ そこから「確認が取れる、裏が取れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 296, "stage": 6, "verb": "talk down", "meaning": "見下した話し方をする", "def": "to speak to someone as if they were less intelligent", "ex1": "Even as the boss, he never talks down to his employees.", "ja1": "彼は上司の立場でも、決して従業員を見下すような話し方をしない。", "ex2": "He tends to talk down to junior members.", "ja2": "彼は若手を見下した話し方をしがちだ。", "note": "talk down to someone の形", "nuance": "condescend（改まった見下し）より口語的。talk downは相手を対等に扱わず「上から目線で話す」という否定的なニュアンスを含む。", "groups": [], "etymology": "talk（話す）＋down（下へ）\n→ \n→ そこから「見下した話し方をする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 297, "stage": 6, "verb": "hit up", "meaning": "連絡を取る、頼む", "def": "to contact someone, often to ask for something", "ex1": "I might hit up my cousin to see if he can lend us his truck.", "ja1": "トラックを貸してもらえるか、いとこに連絡してみようかな。", "ex2": "Hit up the support team if the error repeats.", "ja2": "エラーが再発したらサポートチームに連絡してください。", "note": "くだけた表現。社外にはやや不向き", "nuance": "contact（連絡する、より一般的）より口語的でくだけている。ask（頼む、より一般的）と似た意味でも使われる。", "groups": ["call_phone"], "etymology": "hit（打つ）＋up（上へ）\n→ 相手に声をかけて働きかけるイメージ\n→ そこから「連絡を取る、頼む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 298, "stage": 6, "verb": "get behind*2", "meaning": "支持する、後押しする", "def": "to support a person, plan, or campaign", "ex1": "The whole neighborhood got behind the campaign to save the old library.", "ja1": "近所全体が、その古い図書館を守る運動を後押しした。", "ex2": "Management got behind the new initiative.", "ja2": "経営陣は新しい取り組みを後押しした。", "note": "Stage 1 の get behind（遅れる）と区別", "nuance": "support（支持する、より一般的）とほぼ同義。get behind*2は特にプロジェクトや運動を「後押しする」場面でよく使う。", "groups": ["cheer_encourage"], "etymology": "get（得る・～になる）＋behind（後ろに）\n→ 後方に取り残されるイメージ\n→ そこから「支持する、後押しする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M3 3 L3 13 M6 3 L6 13\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 299, "stage": 6, "verb": "take off*2", "meaning": "離陸する／（売上などが）急伸する", "def": "to leave the ground; to grow very quickly", "ex1": "The plane finally took off two hours after the scheduled time.", "ja1": "飛行機は予定より2時間遅れて、ようやく離陸した。", "ex2": "Sales took off after the product launch.", "ja2": "製品発売後、売上が急伸した。", "note": "Stage 1 の take off（脱ぐ）と区別", "nuance": "launch（改まった離陸）より口語的。take off*2は飛行機の離陸と、ビジネスが「急成長する」という比喩的な意味の両方を持つ。", "groups": ["gain_popularity"], "etymology": "take（取る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「離陸する／（売上などが）急伸する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 300, "stage": 6, "verb": "come across as", "meaning": "〜という印象を与える", "def": "to give a particular impression to others", "ex1": "Even though he means well, he can come across as rude sometimes.", "ja1": "彼に悪気はないのに、時々失礼な印象を与えてしまうことがある。", "ex2": "The email came across as too aggressive.", "ja2": "そのメールは強すぎる印象を与えた。", "note": "Stage 5 の come across（偶然見つける）と区別", "nuance": "seem（〜のように見える、より一般的）とほぼ同義。come across asは、意図とは関係なく他人にどう「映るか」という印象に焦点がある。", "groups": ["impression"], "etymology": "come（来る）＋across（横切って）＋as（～として）\n→ 発した印象や情報が空間を越えて相手に伝わるイメージ\n→ そこから「〜という印象を与える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M2 2 L14 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M2 14 L14 2\" stroke=\"#B5392F\" stroke-width=\"1.4\" opacity=\"0.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 301, "stage": 6, "verb": "turn in*2", "meaning": "（犯人を）引き渡す、通報する", "def": "to hand someone over to the authorities", "ex1": "After weeks on the run, he finally turned himself in to the police.", "ja1": "何週間も逃げ回った末、彼はついに警察に自首した。", "ex2": "The company turned in the employee for fraud.", "ja2": "会社は不正を行った社員を通報した。", "note": "Stage 2 の turn in（提出する）と区別", "nuance": "report（改まった通報）より口語的。hand over（引き渡す、より一般的）と似ているが、turn in*2は特に犯人や容疑者を当局に引き渡す場面で使う。", "groups": ["hand_over"], "etymology": "turn（向きを変える）＋in（中へ）\n→ 対象を当局の管理下の内側へ引き渡すイメージ\n→ そこから「（犯人を）引き渡す、通報する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 302, "stage": 6, "verb": "mess up", "meaning": "台無しにする、しくじる", "def": "to spoil something or make a serious mistake", "ex1": "I really messed up the presentation by mixing up the slides.", "ja1": "スライドの順番を間違えて、プレゼンを台無しにしてしまった。", "ex2": "I messed up the version number in the release note.", "ja2": "リリースノートの版番号を間違えた。", "note": "", "nuance": "ruin（改まった台無し）より口語的。screw up（俗語的、より強い）と似ているが、mess upは失敗全般に幅広く使われる。", "groups": ["mess_disrupt"], "etymology": "mess（ごちゃごちゃにする）＋up（上へ）\n→ せっかく積み上げた物事をぐちゃぐちゃに崩すイメージ\n→ そこから「台無しにする、しくじる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/><circle cx=\"32\" cy=\"20\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 303, "stage": 7, "verb": "feel out", "meaning": "探りを入れる", "def": "to try to discover someone's opinion indirectly", "ex1": "Before making an offer, we decided to feel out how flexible they were on price.", "ja1": "オファーを出す前に、価格についてどれだけ融通が利くか探りを入れることにした。", "ex2": "Let's feel out the client on budget before proposing.", "ja2": "提案の前に顧客の予算感に探りを入れましょう。", "note": "", "nuance": "test（試す、より直接的）とは違い、feel outは相手の反応や状況を「そっと探る」という慎重なニュアンスを強調する。", "groups": ["probe_sniff"], "etymology": "feel（感じる）＋out（外へ）\n→ 相手の反応を外側からそっと探るイメージ\n→ そこから「探りを入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 304, "stage": 7, "verb": "relate to", "meaning": "共感する、理解できる", "def": "to understand and identify with someone or something", "ex1": "I can really relate to what you're going through right now.", "ja1": "あなたが今経験していることに、本当に共感できる。", "ex2": "Customers relate to case studies more than specifications.", "ja2": "顧客は仕様よりも事例に共感する。", "note": "", "nuance": "understand（単に理解する）より、relate toは相手の経験に「自分も同じように感じる」という共感を含む。", "groups": [], "etymology": "relate（関連づける）＋to（～へ）\n→ 相手の気持ちの方向に寄り添うイメージ\n→ そこから「共感する、理解できる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 305, "stage": 7, "verb": "bum out", "meaning": "がっかりさせる", "def": "to make someone feel sad or disappointed", "ex1": "It really bummed me out when the concert got cancelled.", "ja1": "コンサートが中止になって、本当にがっかりした。", "ex2": "The postponement bummed out the whole team.", "ja2": "延期にチーム全体ががっかりした。", "note": "くだけた表現", "nuance": "disappoint（改まったがっかりさせ）より口語的。upset（動揺させる、より強い）ほど深刻ではない軽いがっかり感を表す。", "groups": [], "etymology": "bum（物乞いする）＋out（外へ）\n→ がっかりして気力が外へ抜け落ちるイメージ\n→ そこから「がっかりさせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M32 44 Q32 30 24 28 Q22 27 23 25 Q24 23 26 24 Q30 26 32 32 Q34 26 38 24 Q40 23 41 25 Q42 27 40 28 Q32 30 32 44 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 306, "stage": 7, "verb": "push back*2", "meaning": "（予定を）後ろ倒しにする", "def": "to move something to a later time", "ex1": "We had to push the wedding back a month because of the venue.", "ja1": "会場の都合で、結婚式を1ヶ月後ろ倒しにしなければならなかった。", "ex2": "We pushed back the release to next month.", "ja2": "リリースを翌月に延期した。", "note": "Stage 4 の push back（反発する）と区別", "nuance": "postpone（改まった延期）より口語的。put off（先延ばしにする）と似ているが、push back*2は特に予定の日時を「後ろにずらす」場面で使う。", "groups": ["postpone"], "etymology": "push（押す）＋back（後ろ・元へ）\n→ 予定の位置を時間軸上で後ろへずらすイメージ\n→ そこから「（予定を）後ろ倒しにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 307, "stage": 7, "verb": "jump in", "meaning": "途中から加わる、口を挟む", "def": "to join a conversation or activity suddenly", "ex1": "Feel free to jump in anytime if you have questions.", "ja1": "質問があれば、いつでも途中から口を挟んでください。", "ex2": "Jump in if I miss anything in the explanation.", "ja2": "説明に漏れがあれば口を挟んでください。", "note": "", "nuance": "join（参加する、より一般的）とは違い、jump inは進行中の会話や活動に「勢いよく途中から加わる」ことを強調する。", "groups": ["dive_jump_in"], "etymology": "jump（跳ぶ）＋in（中へ）\n→ 進行中の輪の内側に割り込んで加わるイメージ\n→ そこから「途中から加わる、口を挟む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 308, "stage": 7, "verb": "butt in", "meaning": "話に割り込む", "def": "to interrupt rudely", "ex1": "I hate it when people butt in on a private conversation.", "ja1": "個人的な会話に人が割り込んでくるのは嫌いだ。", "ex2": "He butted in while the client was explaining.", "ja2": "顧客の説明中に彼が割り込んだ。", "note": "jump in より否定的な語感", "nuance": "interrupt（改まった中断）より口語的。cut in（割り込む、より一般的）と似ているが、butt inは招かれざる干渉という否定的なニュアンスが強い。", "groups": ["interrupt"], "etymology": "butt（頭突きする）＋in（中へ）\n→ 他人の会話の内側に頭を突っ込むイメージ\n→ そこから「話に割り込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 309, "stage": 7, "verb": "call out*2", "meaning": "呼び出す、招集する", "def": "to summon someone, especially to deal with a problem", "ex1": "The general called out three units for the emergency mission.", "ja1": "その将軍は緊急任務のために3つの部隊を招集した。", "ex2": "We called out the on-call engineer for the incident.", "ja2": "障害対応でオンコール担当を呼び出した。", "note": "Stage 6 の call out と区別", "nuance": "summon（改まった招集）より口語的。gather（集める、より一般的）とは違い、call out*2は緊急時に人員を「呼び出す」ニュアンスを含む。", "groups": ["speak_loudly"], "etymology": "call（呼ぶ）＋out（外へ）\n→ 人々を一か所の外へ呼び集めるイメージ\n→ そこから「呼び出す、招集する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 310, "stage": 7, "verb": "freak out", "meaning": "パニックになる、取り乱す", "def": "to become very anxious, upset, or afraid", "ex1": "She froze and completely freaked out when the spider crawled onto her hand.", "ja1": "クモが手に這い上がってきた時、彼女は固まってすっかり取り乱した。", "ex2": "Don't freak out; we have a rollback plan.", "ja2": "慌てないでください、切り戻し手順があります。", "note": "", "nuance": "panic（改まったパニック）より口語的。freak outは驚きや恐怖で「取り乱す」という感情の爆発を強く表す。", "groups": [], "etymology": "freak（ひどく興奮する）＋out（外へ）\n→ 抑えていた感情が外へあふれ出すイメージ\n→ そこから「パニックになる、取り乱す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"26\" cy=\"28\" r=\"2.5\" fill=\"#C79A3D\"/><circle cx=\"38\" cy=\"28\" r=\"2.5\" fill=\"#C79A3D\"/><circle cx=\"32\" cy=\"40\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 311, "stage": 7, "verb": "fall for", "meaning": "恋に落ちる／だまされる", "def": "to fall in love with someone; to be deceived by a trick", "ex1": "He fell for her the moment she laughed at his terrible joke.", "ja1": "彼女が彼のひどい冗談に笑った瞬間、彼は恋に落ちた。", "ex2": "Several staff fell for the phishing email.", "ja2": "何人かの社員がフィッシングメールにだまされた。", "note": "", "nuance": "fall in love with（改まった恋愛表現、より一般的）とほぼ同義。be tricked（だまされる、より一般的）とは違い、fall forはだまされる時にも使われる多義語。", "groups": ["deceive"], "etymology": "fall（落ちる）＋for（求めて）\n→ 相手に心や判断が強く引き寄せられるイメージ\n→ そこから「恋に落ちる／だまされる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 312, "stage": 7, "verb": "let out", "meaning": "外に出す／（情報を）漏らす", "def": "to allow someone or something to leave; to reveal", "ex1": "We let the dog out into the backyard before bed every night.", "ja1": "毎晩寝る前に、犬を裏庭に出している。", "ex2": "Don't let out the details before the announcement.", "ja2": "発表の前に詳細を漏らさないでください。", "note": "", "nuance": "release（改まった解放）より口語的。leak（情報を漏らす、より秘密的）と似ているが、let outは物や音、感情、情報を「外に出す」全般に使える。", "groups": ["reveal_secret"], "etymology": "let（～させる）＋out（外へ）\n→ 隠していた情報や言葉が思わず漏れ出るイメージ\n→ そこから「外に出す／（情報を）漏らす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(1,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 313, "stage": 7, "verb": "eat out", "meaning": "外食する", "def": "to eat at a restaurant instead of at home", "ex1": "We're too tired to cook tonight, so let's just eat out.", "ja1": "今夜は疲れすぎて料理できないから、外食にしよう。", "ex2": "The team ate out together after the workshop.", "ja2": "ワークショップの後、チームで外食した。", "note": "", "nuance": "dine out（改まった言い方）より口語的。eat in（家で食べる）の反対で、レストランなどで食事することを表す。", "groups": ["dining_location"], "etymology": "eat（食べる）＋out（外へ）\n→ 内側の空間から外の世界へ出ていくイメージ\n→ そこから「外食する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 314, "stage": 7, "verb": "eat in", "meaning": "家で食べる、店内で食べる", "def": "to eat at home rather than at a restaurant", "ex1": "It's cheaper to eat in most nights and save eating out for weekends.", "ja1": "たいていの夜は家で食べて、外食は週末のために取っておく方が安上がりだ。", "ex2": "We ate in at the office to keep working.", "ja2": "作業を続けるため社内で食事を済ませた。", "note": "", "nuance": "eat out（外食する）の反対。cook at home（家で料理する）と似ているが、eat inは店内で食べる意味でも使われる。", "groups": ["dining_location"], "etymology": "eat（食べる）＋in（中へ）\n→ 外に出ず室内で食事を済ませるイメージ\n→ そこから「家で食べる、店内で食べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 315, "stage": 7, "verb": "ease into", "meaning": "徐々に慣らす、ゆっくり始める", "def": "to start something gradually and gently", "ex1": "The coach eased the injured player back into full training slowly.", "ja1": "コーチはけがをした選手を、ゆっくりと本格的な練習に戻していった。", "ex2": "We eased into the new process over two weeks.", "ja2": "2週間かけて新しい手順へ徐々に移行した。", "note": "", "nuance": "start slowly（改まった言い方）より口語的。ease intoは新しい環境や活動に「無理なく徐々に慣らしていく」プロセスを強調する。", "groups": ["gradual_pace"], "etymology": "ease（和らげる）＋into（中へ変化）\n→ 急がず少しずつ新しい状態の中へ入るイメージ\n→ そこから「徐々に慣らす、ゆっくり始める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 316, "stage": 7, "verb": "pull out", "meaning": "引き抜く／撤退する", "def": "to remove something; to withdraw from an agreement", "ex1": "The dentist had to pull out the tooth; it was too far gone to save.", "ja1": "その歯はもう手遅れで、歯医者は抜かざるを得なかった。", "ex2": "The partner pulled out of the joint project.", "ja2": "パートナー企業が共同事業から撤退した。", "note": "", "nuance": "remove（取り外す、より一般的）とは違い、pull outは物理的に「引き抜く」動作、または計画から「撤退する」ことを表す。", "groups": ["pull_out_away"], "etymology": "pull（引く）＋out（外へ）\n→ 刺さっていた物や人を外へ引き抜くイメージ\n→ そこから「引き抜く／撤退する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 317, "stage": 7, "verb": "pull into", "meaning": "（車が）〜に入って止まる", "def": "to drive into a place and stop", "ex1": "Investors started to pull out the moment the scandal broke.", "ja1": "スキャンダルが発覚した瞬間、投資家たちは撤退し始めた。", "ex2": "The truck pulled into the loading bay.", "ja2": "トラックが搬入口に入ってきた。", "note": "", "nuance": "park（駐車する、より一般的）とは違い、pull intoは車が特定の場所へ「入っていって止まる」動作の途中経過を表す。", "groups": ["vehicle_actions"], "etymology": "pull（引く）＋into（中へ変化）\n→ 車が空間の内側へ入って収まるイメージ\n→ そこから「（車が）〜に入って止まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 318, "stage": 7, "verb": "cut off*2", "meaning": "話を遮る", "def": "to interrupt someone who is speaking", "ex1": "A car suddenly pulled into the driveway just as we were leaving.", "ja1": "私たちが出ようとしたちょうどその時、車が突然その私道に入ってきた。", "ex2": "He cut off the client mid-sentence.", "ja2": "彼は顧客の話を途中で遮った。", "note": "Stage 5 / 7 に別語義あり", "nuance": "話を遮る（Stage7）、cut off*3（関係を断つ）と区別。", "groups": ["cut_off_senses"], "etymology": "cut（切る）＋off（離れて）\n→ 相手の話を途中で断ち切るイメージ\n→ そこから「話を遮る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 319, "stage": 7, "verb": "push through", "meaning": "押し通す、成立させる", "def": "to succeed in getting something accepted or approved", "ex1": "Sorry to cut you off, but we're running out of time.", "ja1": "話を遮ってすみませんが、時間がなくなってきています。", "ex2": "We pushed through the budget approval before quarter end.", "ja2": "四半期末までに予算承認を通した。", "note": "", "nuance": "force（改まった強行）より口語的。get through（法案などを通す）と似ているが、push throughは反対を押し切って「成立させる」という強引さを含む。", "groups": ["accomplish_through"], "etymology": "push（押す）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「押し通す、成立させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 320, "stage": 7, "verb": "end up", "meaning": "結局〜になる", "def": "to finally be in a particular state or place", "ex1": "They finally pushed the new policy through after months of debate.", "ja1": "何ヶ月もの議論の末、彼らはついにその新しい方針を通した。", "ex2": "We ended up choosing the cheaper vendor.", "ja2": "結局、安いほうの業者を選んだ。", "note": "後ろは -ing または with / in", "nuance": "become（単になる）とは違い、end upは意図とは違う結果に「結局落ち着く」というニュアンスを含む。", "groups": ["turn_out_end_up"], "etymology": "end（終わる）＋up（上へ）\n→ 物事が最終的にある状態まで行き着くイメージ\n→ そこから「結局〜になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 321, "stage": 7, "verb": "pull up*2", "meaning": "（データ・画面を）呼び出す", "def": "to retrieve and display information", "ex1": "We got lost and ended up on the completely wrong side of town.", "ja1": "道に迷って、結局街の全く反対側に着いてしまった。", "ex2": "Can you pull up last month's report?", "ja2": "先月のレポートを出してもらえますか。", "note": "Stage 6 の pull up（車を止める）と区別", "nuance": "open（開く、より一般的）とは違い、pull up*2は特にコンピューターやスマホで情報を「呼び出して表示する」場面で使う。", "groups": ["pull_up_senses"], "etymology": "pull（引く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（データ・画面を）呼び出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 322, "stage": 7, "verb": "spice up", "meaning": "変化や面白みを加える", "def": "to make something more interesting or exciting", "ex1": "Let me pull up the file so we can look at it together.", "ja1": "一緒に見られるように、そのファイルを呼び出すね。", "ex2": "Let's spice up the presentation with a live demo.", "ja2": "実演を入れてプレゼンに変化をつけましょう。", "note": "", "nuance": "improve（改善する、より一般的）とは違い、spice upは特に単調な物事に「刺激や面白みを加える」というニュアンスを含む。", "groups": [], "etymology": "spice（香辛料を加える）＋up（上へ）\n→ 単調な物に刺激を加えて引き立てるイメージ\n→ そこから「変化や面白みを加える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-3,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 323, "stage": 7, "verb": "start out", "meaning": "（最初は）〜として始まる", "def": "to begin your life or career in a particular way", "ex1": "The dish started out simple but grew more complicated with each request.", "ja1": "その料理はシンプルに始まったが、リクエストが増えるたびに複雑になっていった。", "ex2": "The company started out as a small studio.", "ja2": "その会社は小さなスタジオとして始まった。", "note": "", "nuance": "begin as（改まった言い方）より口語的。start outは物事の「最初の段階」がどうだったかを述べる時に使う。", "groups": ["begin"], "etymology": "start（始める）＋out（外へ）\n→ 物事の外側、つまり最初の一歩を踏み出すイメージ\n→ そこから「（最初は）〜として始まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(14,32,32)\"><circle cx=\"32\" cy=\"26\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M26 38 L38 38 M28 44 L36 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 324, "stage": 7, "verb": "stick up for", "meaning": "かばう、擁護する", "def": "to defend or support someone", "ex1": "She always sticks up for her younger brother, no matter what he does.", "ja1": "彼女は弟が何をしても、いつも彼をかばう。", "ex2": "She stuck up for her team in the review.", "ja2": "彼女はレビューでチームを擁護した。", "note": "", "nuance": "defend（改まった擁護）より口語的。support（支持する、より一般的）と似ているが、stick up forは特に批判されている人を「かばう」場面で使う。", "groups": [], "etymology": "stick（突き刺す・くっつく）＋up（上へ）＋for（求めて）\n→ 上向き・完了や増加のイメージ\n→ そこから「かばう、擁護する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(8,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 325, "stage": 7, "verb": "settle for", "meaning": "妥協して受け入れる", "def": "to accept something less than what you wanted", "ex1": "We couldn't afford the house we wanted, so we settled for a smaller one.", "ja1": "希望していた家は買えなかったので、もっと小さな家で妥協した。", "ex2": "We settled for a partial delivery this month.", "ja2": "今月は一部納品で妥協した。", "note": "", "nuance": "compromise（改まった妥協）より、settle forは本当は満足していないが「次善の選択肢で我慢する」というニュアンスを強く含む。", "groups": ["give_up_in"], "etymology": "settle（落ち着かせる）＋for（求めて）\n→ 本命ではない物を目的物として受け入れるイメージ\n→ そこから「妥協して受け入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(11,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 326, "stage": 7, "verb": "talk back", "meaning": "口答えする", "def": "to reply rudely to someone in authority", "ex1": "The kid talked back to the teacher and got sent to the office.", "ja1": "その子は先生に口答えして、職員室に送られた。", "ex2": "Talking back to a client rarely ends well.", "ja2": "顧客に口答えしてよい結果になることはまずない。", "note": "", "nuance": "目上に対して反抗的な口答えをする、否定的な行為。", "groups": [], "etymology": "talk（話す）＋back（後ろ・元へ）\n→ 言われた言葉をそのまま相手に投げ返すイメージ\n→ そこから「口答えする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 327, "stage": 7, "verb": "go down*2", "meaning": "（システムが）停止する、（記録に）残る", "def": "to stop working; to be recorded in history", "ex1": "The entire payment system went down for almost three hours.", "ja1": "決済システム全体が、ほぼ3時間停止した。", "ex2": "The server went down for two hours.", "ja2": "サーバーが2時間停止した。", "note": "Stage 1 の go down（下がる）と区別", "nuance": "crash（クラッシュする、より直接的）とほぼ同義。system failure（システム障害、改まった言い方）より口語的。", "groups": ["go_down_senses"], "etymology": "go（行く）＋down（下へ）\n→ 頭の中の情報を紙の上に書き落とすイメージ\n→ そこから「（システムが）停止する、（記録に）残る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 328, "stage": 7, "verb": "let off", "meaning": "大目に見る、放免する", "def": "to not punish someone, or to punish them lightly", "ex1": "The officer let him off with just a warning.", "ja1": "その警官は警告だけで彼を大目に見た。", "ex2": "He was let off with a verbal warning.", "ja2": "彼は口頭注意だけで済んだ。", "note": "", "nuance": "forgive（許す、より一般的）とは違い、let offは罰を「軽くする、見逃す」という寛大さを強調する。", "groups": [], "etymology": "let（～させる）＋off（離れて）\n→ 本来受けるはずの罰から相手を解き放つイメージ\n→ そこから「大目に見る、放免する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 329, "stage": 7, "verb": "line up", "meaning": "並ぶ／手配する、そろえる", "def": "to form a line; to arrange or organize something", "ex1": "People started lining up outside the store before it even opened.", "ja1": "開店前から、人々は店の外に並び始めた。", "ex2": "We lined up three candidates for the interview.", "ja2": "面接候補を3名手配した。", "note": "", "nuance": "wait in line（並んで待つ、より一般的）とほぼ同義。arrange（手配する）と似た別の意味でも使われる多義語。", "groups": [], "etymology": "line（並べる）＋up（上へ）\n→ バラバラだった物を一列に整えて並べるイメージ\n→ そこから「並ぶ／手配する、そろえる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(2,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 330, "stage": 7, "verb": "cut off*3", "meaning": "（関係・支援を）断つ", "def": "to end a relationship or stop providing something", "ex1": "His parents cut off his allowance after he dropped out of school.", "ja1": "彼が退学したあと、両親は彼への仕送りを断った。", "ex2": "The supplier cut us off after the payment dispute.", "ja2": "支払いのもつれの後、仕入先は取引を停止した。", "note": "Stage 5 / 7 に別語義あり", "nuance": "stop supporting（改まった言い方）より口語的。cut off*3は経済的援助や人間関係を「きっぱりと断つ」強い決断を表す。", "groups": ["cut_off_senses"], "etymology": "cut（切る）＋off（離れて）\n→ つながっていた関係をきっぱり断ち切るイメージ\n→ そこから「（関係・支援を）断つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 331, "stage": 7, "verb": "drag into", "meaning": "巻き込む", "def": "to involve someone in a situation against their will", "ex1": "I never wanted to get involved, but he dragged me into the argument anyway.", "ja1": "関わりたくなかったのに、彼は私をその口論に巻き込んだ。", "ex2": "Don't drag other teams into this issue.", "ja2": "この問題に他チームを巻き込まないでください。", "note": "", "nuance": "involve（巻き込む、より一般的）とは違い、drag intoは望んでいない人を「無理やり問題に引きずり込む」という否定的なニュアンスを含む。", "groups": [], "etymology": "drag（引きずる）＋into（中へ変化）\n→ 関係ない相手を渦中の内側へ引き込むイメージ\n→ そこから「巻き込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 332, "stage": 7, "verb": "hold off*2", "meaning": "食い止める、寄せつけない", "def": "to prevent someone from approaching or succeeding", "ex1": "The dam is designed to hold off flooding during the rainy season.", "ja1": "そのダムは、雨期の洪水を食い止めるために設計されている。", "ex2": "We held off competitors by improving support.", "ja2": "サポートを強化して競合を食い止めた。", "note": "Stage 4 の hold off（見合わせる）と区別", "nuance": "prevent（防ぐ、より一般的）とは違い、hold off*2は問題や敵の攻撃を一時的に「食い止める」という抵抗のニュアンスを含む。", "groups": ["hold_out_off"], "etymology": "hold（持つ・保つ）＋off（離れて）\n→ 動いていたものから電源やつながりを切り離して止めるイメージ\n→ そこから「食い止める、寄せつけない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><rect x=\"20\" y=\"26\" width=\"24\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/><path d=\"M24 26 L24 20 M32 26 L32 18 M40 26 L40 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 333, "stage": 7, "verb": "play out", "meaning": "展開する、結末を迎える", "def": "to develop or end in a particular way", "ex1": "Nobody could have predicted how the trial would play out.", "ja1": "その裁判がどう展開するか、誰も予想できなかった。", "ex2": "Let's see how the negotiation plays out.", "ja2": "交渉がどう展開するか見守りましょう。", "note": "", "nuance": "unfold（改まった展開）より口語的。happen（単に起こる）とは違い、play outは物事が時間をかけて「どう展開し、結末を迎えるか」を表す。", "groups": [], "etymology": "play（遊ぶ・演じる）＋out（外へ）\n→ 隠れていた筋書きが最後まで外に現れるイメージ\n→ そこから「展開する、結末を迎える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M27 24 L27 40 L41 32 Z\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 334, "stage": 7, "verb": "take over", "meaning": "引き継ぐ、支配する", "def": "to take control or responsibility for something", "ex1": "She's taking over the department once the current manager retires.", "ja1": "現在のマネージャーが退職したら、彼女がその部署を引き継ぐ。", "ex2": "I'll take over the project from April.", "ja2": "4月からプロジェクトを引き継ぎます。", "note": "", "nuance": "replace（交代する、より一般的）とは違い、take overは責任や地位を「正式に引き継ぐ」というニュアンスを含む。support、権力を「支配する」意味でも使う。", "groups": [], "etymology": "take（取る）＋over（越えて）\n→ 役割や権限が境界を越えて相手側へ移るイメージ\n→ そこから「引き継ぐ、支配する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 335, "stage": 7, "verb": "fit in*2", "meaning": "（予定に）入れる、都合をつける", "def": "to find time for someone or something", "ex1": "Can you fit in a quick call sometime this afternoon?", "ja1": "今日の午後、どこかで簡単な電話を入れられますか。", "ex2": "Can you fit in a 15-minute call today?", "ja2": "今日15分の打ち合わせを入れられますか。", "note": "Stage 5 の fit in（なじむ）と区別", "nuance": "schedule（予定を入れる、より一般的）とほぼ同義。squeeze in（無理に詰め込む）と似ているが、fit in*2は都合をつけて予定に組み込むこと全般を表す。", "groups": ["schedule_fit"], "etymology": "fit（合う）＋in（中へ）\n→ 詰まったスケジュールの内側に押し込むイメージ\n→ そこから「（予定に）入れる、都合をつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 336, "stage": 7, "verb": "stick to", "meaning": "守り続ける、固執する", "def": "to continue with something and not change it", "ex1": "Despite the criticism, he stuck to his original plan.", "ja1": "批判があっても、彼は当初の計画を守り続けた。", "ex2": "Let's stick to the agreed scope.", "ja2": "合意したスコープを守りましょう。", "note": "", "nuance": "maintain（改まった維持）より口語的。stick toは決めた方針や計画から「ぶれずに守り続ける」という一貫性を強調する。", "groups": ["stick_persist"], "etymology": "stick（突き刺す・くっつく）＋to（～へ）\n→ 決めた方針の方向からぶれずに守り続けるイメージ\n→ そこから「守り続ける、固執する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(9,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 337, "stage": 7, "verb": "play up", "meaning": "強調する、大げさに言う", "def": "to emphasize something to make it seem more important", "ex1": "The ad played up the car's fuel efficiency more than anything else.", "ja1": "その広告は、何よりもその車の燃費の良さを強調していた。", "ex2": "The proposal plays up our support capability.", "ja2": "提案書は当社のサポート力を前面に出している。", "note": "", "nuance": "exaggerate（改まった誇張）より口語的。emphasize（強調する、より中立的）とは違い、play upはやや誇張気味に強調するニュアンスを含む。", "groups": [], "etymology": "play（遊ぶ・演じる）＋up（上へ）\n→ 物事の程度や量を実際より高く引き上げるイメージ\n→ そこから「強調する、大げさに言う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-11,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M27 24 L27 40 L41 32 Z\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 338, "stage": 7, "verb": "check off", "meaning": "チェックを入れる、消し込む", "def": "to mark items on a list as completed", "ex1": "I checked off every item on the list before leaving the store.", "ja1": "店を出る前に、リストの項目を全部チェックして消し込んだ。", "ex2": "Let's check off the completed test cases.", "ja2": "完了したテストケースを消し込みましょう。", "note": "", "nuance": "mark（印をつける、より一般的）とほぼ同義。check offはリストの項目を「確認して消し込む」具体的な動作を表す。", "groups": [], "etymology": "check（確認する）＋off（離れて）\n→ 完了した項目をリストから切り離すイメージ\n→ そこから「チェックを入れる、消し込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 339, "stage": 7, "verb": "fill in*2", "meaning": "（不在の間の情報を）伝える", "def": "to give someone the information they missed", "ex1": "Could you fill me in on what happened while I was out?", "ja1": "私が留守にしている間に何があったか、教えてもらえますか。", "ex2": "Can you fill me in on yesterday's meeting?", "ja2": "昨日の会議の内容を教えてもらえますか。", "note": "fill someone in on の語順。Stage 5 の fill in（記入する）と区別", "nuance": "update（改まった更新）より口語的。fill in（記入する、より一般的）とは別の意味で、fill in*2は不在中の出来事を「後から伝える」ことを表す。", "groups": ["contact_related"], "etymology": "fill（満たす）＋in（中へ）\n→ 抜けていた期間の情報を内側から埋めるイメージ\n→ そこから「（不在の間の情報を）伝える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><path d=\"M22 26 L24 46 Q24 48 26 48 L38 48 Q40 48 40 46 L42 26\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M18 26 L46 26\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 14 L32 22 M28 18 L32 22 L36 18\" stroke=\"#C79A3D\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 340, "stage": 7, "verb": "let on", "meaning": "秘密を漏らす、そぶりを見せる", "def": "to reveal a secret or show that you know something", "ex1": "She never let on that she already knew about the surprise party.", "ja1": "彼女はサプライズパーティーのことを既に知っていると、決してそぶりに出さなかった。", "ex2": "Don't let on that the deal is still unsigned.", "ja2": "契約がまだ未締結だと漏らさないでください。", "note": "", "nuance": "reveal（改まった暴露）とは反対で、let onは秘密を「うっかり漏らす」、または知っていることを「そぶりに出す」ことを表す（通常否定文で使われる）。", "groups": ["reveal_secret"], "etymology": "let（～させる）＋on（接触・継続）\n→ 隠していたことを表面にうっすら出すイメージ\n→ そこから「秘密を漏らす、そぶりを見せる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 341, "stage": 7, "verb": "sit back", "meaning": "ゆったり座る／静観する", "def": "to relax; to take no action when you could", "ex1": "Just sit back and enjoy the show; you don't need to do anything.", "ja1": "ただゆったり座ってショーを楽しんで、何もしなくていいから。", "ex2": "We can't just sit back while the schedule slips.", "ja2": "予定が遅れていくのを静観はできない。", "note": "", "nuance": "relax（くつろぐ、より一般的）とは違い、sit backは椅子に深くもたれて「何もせず見守る」という受動的な姿勢を強調する。", "groups": ["reflect_step_back"], "etymology": "sit（座る）＋back（後ろ・元へ）\n→ 力を抜いて後方へ体を預けるイメージ\n→ そこから「ゆったり座る／静観する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 342, "stage": 7, "verb": "scoot over", "meaning": "席を詰めて寄る", "def": "to move sideways to make space for someone", "ex1": "Could you scoot over a little? There's barely any room left on this bench.", "ja1": "少し詰めてもらえる？このベンチ、もうほとんど席がないんだ。", "ex2": "Could everyone scoot over so the client can sit?", "ja2": "顧客が座れるよう皆さん詰めてもらえますか。", "note": "くだけた表現", "nuance": "move over（改まった言い方）より口語的。scoot overは特に座席で「体をずらして詰める」という具体的な動作を表す。", "groups": [], "etymology": "scoot（素早く移動する）＋over（越えて）\n→ 自分の場所を少し越えて隣へ寄るイメージ\n→ そこから「席を詰めて寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 343, "stage": 7, "verb": "take away from", "meaning": "価値を損なう", "def": "to reduce the value or good effect of something", "ex1": "A few typos here and there don't take away from how good the essay is.", "ja1": "多少のタイプミスがあっても、そのエッセイの良さを損なうことはない。", "ex2": "The typos took away from an otherwise strong proposal.", "ja2": "誤字が、それ以外は優れた提案の価値を損ねた。", "note": "Stage 5 の take away（取り上げる）と区別", "nuance": "reduce（減らす、より一般的）とは違い、take away fromは全体の質や価値を「部分的に損なう」というニュアンスを含む。", "groups": [], "etymology": "take（取る）＋away（遠くへ）＋from（～から）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「価値を損なう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-11,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 344, "stage": 7, "verb": "get across", "meaning": "（考えを）伝える、理解させる", "def": "to communicate an idea so that others understand", "ex1": "It's hard to get across how much this opportunity means to me.", "ja1": "この機会が私にとってどれだけ大きいか、伝えるのは難しい。", "ex2": "The slides got the message across clearly.", "ja2": "スライドは意図を明確に伝えた。", "note": "", "nuance": "communicate（伝える、より一般的）とは違い、get acrossは特に考えを相手に「理解してもらう」という結果に焦点がある。", "groups": ["convey_info"], "etymology": "get（得る・～になる）＋across（横切って）\n→ ある空間や境界を横切って向こう側に届くイメージ\n→ そこから「（考えを）伝える、理解させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M2 2 L14 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M2 14 L14 2\" stroke=\"#B5392F\" stroke-width=\"1.4\" opacity=\"0.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 345, "stage": 7, "verb": "stand for*2", "meaning": "容認する、我慢する", "def": "to tolerate behavior you disapprove of", "ex1": "I won't stand for being talked to like that.", "ja1": "そんな話し方をされるのは我慢できない。", "ex2": "We won't stand for repeated delays.", "ja2": "度重なる遅延は容認できません。", "note": "否定文で使うのが普通。Stage 3 の stand for（略である）と区別", "nuance": "tolerate（改まった容認）より口語的。put up with（我慢する）とほぼ同義で、stand for*2は主に否定文で「我慢できない」という強い拒絶を表す。", "groups": ["stand_for_senses"], "etymology": "stand（立つ）＋for（求めて）\n→ 不満があっても目的のために受け入れるイメージ\n→ そこから「容認する、我慢する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 346, "stage": 7, "verb": "hand over", "meaning": "引き渡す、引き継ぐ", "def": "to give something or responsibility to someone else", "ex1": "After thirty years, he finally handed over the family business to his daughter.", "ja1": "30年経って、彼はついに家業を娘に引き渡した。", "ex2": "I'll hand over the account to my successor.", "ja2": "担当顧客を後任に引き継ぎます。", "note": "", "nuance": "give（与える、より一般的）とは違い、hand overは責任や物を正式に「引き渡す」という手続き的なニュアンスを含む。", "groups": ["hand_over"], "etymology": "hand（手渡す）＋over（越えて）\n→ 役割や権限が境界を越えて相手側へ移るイメージ\n→ そこから「引き渡す、引き継ぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 8 L16 12 L12 15\" stroke=\"#B5392F\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 347, "stage": 7, "verb": "pass out*2", "meaning": "配る", "def": "to give something to each person in a group", "ex1": "Volunteers passed out flyers about the upcoming election.", "ja1": "ボランティアたちが、来る選挙についてのチラシを配った。", "ex2": "Please pass out the agenda before we start.", "ja2": "始める前に議事次第を配ってください。", "note": "Stage 3 の pass out（気を失う）と区別", "nuance": "give out*2（配る、より一般的）とほぼ同義。distributeより口語的で、チラシやサンプルなどを配る場面でよく使う。", "groups": ["distribute"], "etymology": "pass（通す・渡す）＋out（外へ）\n→ 内側にあった物を外の人々へ配って行き渡らせるイメージ\n→ そこから「配る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 348, "stage": 7, "verb": "stick around", "meaning": "その場に残る、居残る", "def": "to stay in a place for a while longer", "ex1": "Everyone else left, but she stuck around to help clean up.", "ja1": "他のみんなは帰ったが、彼女は片付けを手伝うためにその場に残った。", "ex2": "Could you stick around after the meeting?", "ja2": "会議の後、少し残ってもらえますか。", "note": "", "nuance": "stay（留まる、より一般的）とほぼ同義。leave（去る）の反対で、stick aroundは特に「もうしばらくその場にいる」というカジュアルな言い方。", "groups": ["stick_persist"], "etymology": "stick（突き刺す・くっつく）＋around（周りに）\n→ 立ち去らずその場の周辺に留まるイメージ\n→ そこから「その場に残る、居残る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(7,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 349, "stage": 7, "verb": "work on", "meaning": "取り組む、改善する", "def": "to spend time producing or improving something", "ex1": "We've been working on the design for nearly six months now.", "ja1": "そのデザインに取り組んで、もう6ヶ月近くになる。", "ex2": "She's working on the requirements document.", "ja2": "彼女は要件定義書に取り組んでいる。", "note": "", "nuance": "do（単にする、より一般的）とは違い、work onは特定の課題やプロジェクトに継続的に「取り組んでいる」プロセスを強調する。", "groups": ["undertake_continue_work"], "etymology": "work（働く・作用させる）＋on（接触・継続）\n→ 対象の上に手をかけ続けて改善するイメージ\n→ そこから「取り組む、改善する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 350, "stage": 7, "verb": "come down to", "meaning": "結局〜次第である", "def": "to be a matter of one decisive factor", "ex1": "In the end, it all comes down to how much you're willing to risk.", "ja1": "結局のところ、どれだけリスクを取る覚悟があるか次第だ。", "ex2": "It comes down to whether we can meet the deadline.", "ja2": "結局は納期を守れるかどうかだ。", "note": "", "nuance": "depend on（依存する、より一般的）と似ているが、come down toは複雑な状況を「結局のところ、これが決め手だ」と要約する時に使う。", "groups": ["turn_out_end_up"], "etymology": "come（来る）＋down（下へ）＋to（～へ）\n→ 物事が最終的に行き着く先を指すイメージ\n→ そこから「結局〜次第である」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 351, "stage": 7, "verb": "settle down", "meaning": "落ち着く／身を固める", "def": "to become calm; to start living a stable life", "ex1": "After years of traveling, he finally settled down in a small coastal town.", "ja1": "何年も旅を続けた末、彼はついに小さな海辺の町に落ち着いた。", "ex2": "Things settled down after the release.", "ja2": "リリース後、状況は落ち着いた。", "note": "", "nuance": "calm down（落ち着く、感情面）とは違い、settle downは生活が「安定する」、または結婚して「身を固める」という長期的な変化を表す。", "groups": ["calm_down"], "etymology": "settle（落ち着かせる）＋down（下へ）\n→ 高ぶっていた気持ちが静かに下がるイメージ\n→ そこから「落ち着く／身を固める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 352, "stage": 7, "verb": "catch on*2", "meaning": "理解する、飲み込む", "def": "to begin to understand something", "ex1": "I explained the rule three times before it finally caught on.", "ja1": "そのルールを3回説明して、ようやく彼女は理解した。", "ex2": "He caught on to the new process quickly.", "ja2": "彼は新しい手順をすぐに飲み込んだ。", "note": "Stage 5 の catch on（流行する）と区別", "nuance": "understand（単に理解する）より口語的。get it（分かる、カジュアル）と似た表現で、説明を聞いて「腑に落ちる」瞬間を表す。", "groups": ["understand"], "etymology": "catch（捕まえる）＋on（接触・継続）\n→ 説明が頭にくっついて定着し、理解できるイメージ\n→ そこから「理解する、飲み込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 353, "stage": 8, "verb": "hash out", "meaning": "議論して詰める", "def": "to discuss something in detail until you reach agreement", "ex1": "The two sides spent all night hashing out the final terms.", "ja1": "両者は最終条件を詰めるために一晩中議論した。", "ex2": "Let's hash out the responsibilities before signing.", "ja2": "締結の前に責任分担を詰めましょう。", "note": "", "nuance": "discuss（改まった議論）より、hash outは意見の相違がある中で「時間をかけて詳細を詰める」というニュアンスを含む。", "groups": ["discuss_thoroughly"], "etymology": "hash（こまごまと処理する）＋out（外へ）\n→ 議論を重ねて結論を外に絞り出すイメージ\n→ そこから「議論して詰める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-11,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 354, "stage": 8, "verb": "read up on", "meaning": "（事前に）読み込む、調べる", "def": "to study a subject by reading about it", "ex1": "I read up on the company before walking into the interview.", "ja1": "面接に入る前に、その会社について読み込んでおいた。", "ex2": "I read up on their industry before the meeting.", "ja2": "会議の前に先方の業界について読み込んだ。", "note": "", "nuance": "study（勉強する、より一般的）とは違い、read up onは特定の話題について事前に「情報を仕入れておく」準備的なニュアンスを含む。", "groups": ["study_review"], "etymology": "read（読む）＋up（上へ）＋on（接触・継続）\n→ 知りたい情報を掘り起こして表に持ってくるイメージ\n→ そこから「（事前に）読み込む、調べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 355, "stage": 8, "verb": "dig into", "meaning": "深く掘り下げる", "def": "to examine or investigate something thoroughly", "ex1": "The documentary really digs into the causes behind the crisis.", "ja1": "そのドキュメンタリーは、その危機の原因を深く掘り下げている。", "ex2": "We dug into the logs to find the root cause.", "ja2": "根本原因を探るためログを掘り下げた。", "note": "", "nuance": "explore（探求する、より一般的）とは違い、dig intoは表面的でなく「深く掘り下げて調べる」という執念を強調する。", "groups": ["elaborate_dig"], "etymology": "dig（掘る）＋into（中へ変化）\n→ 表面ではなく奥深くまで掘り進むイメージ\n→ そこから「深く掘り下げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><path d=\"M40 16 Q46 16 46 22 Q46 26 42 28 L24 46 Q22 48 20 46 Q18 44 20 42 L38 24 Q40 20 40 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 356, "stage": 8, "verb": "take up on", "meaning": "（申し出を）受ける", "def": "to accept an offer that someone has made", "ex1": "She finally took him up on his offer to help move the couch.", "ja1": "彼女はついに、ソファを運ぶのを手伝うという彼の申し出を受けた。", "ex2": "I'd like to take you up on your offer of a trial.", "ja2": "試用のご提案をお受けしたいです。", "note": "take someone up on something の語順", "nuance": "accept（単に受け入れる）とは違い、take up onは相手からの申し出や誘いを「実際に受けて行動する」ことを表す。", "groups": ["accept_take_up"], "etymology": "take（取る）＋up（上へ）＋on（接触・継続）\n→ 上向き・完了や増加のイメージ\n→ そこから「（申し出を）受ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 357, "stage": 8, "verb": "sit through", "meaning": "最後まで座って耐える", "def": "to stay until the end of something long or dull", "ex1": "I could barely sit through the entire three-hour lecture.", "ja1": "その3時間の講義を最後まで座っていられるかどうか、ぎりぎりだった。", "ex2": "We sat through a three-hour vendor presentation.", "ja2": "3時間の業者説明を最後まで聞いた。", "note": "", "nuance": "endure（改まった忍耐）より口語的。sit throughは退屈な会議や映画などを「最後まで座って我慢する」場面でよく使う。", "groups": ["endure"], "etymology": "sit（座る）＋through（通り抜けて）\n→ 始めから終わりまで一気に通り抜けるイメージ\n→ そこから「最後まで座って耐える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 358, "stage": 8, "verb": "whip out", "meaning": "さっと取り出す", "def": "to take something out quickly", "ex1": "He whipped out his phone the moment the deal was mentioned.", "ja1": "その取引の話が出た瞬間、彼はさっと携帯を取り出した。", "ex2": "She whipped out a printed copy of the contract.", "ja2": "彼女は契約書の印刷版をさっと取り出した。", "note": "", "nuance": "take out（取り出す、より一般的）とは違い、whip outは物を「素早く、さっと取り出す」という動作の速さを強調する。", "groups": [], "etymology": "whip（ムチ打つ・さっと動かす）＋out（外へ）\n→ 中にしまってあった物を外へ取り出すイメージ\n→ そこから「さっと取り出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 359, "stage": 8, "verb": "rough up", "meaning": "手荒に扱う、暴行する", "def": "to attack someone physically", "ex1": "The bouncers roughed him up before throwing him out of the club.", "ja1": "用心棒たちは彼を手荒に扱ってから、クラブの外に放り出した。", "ex2": "Roughing up a colleague is grounds for dismissal.", "ja2": "同僚への暴行は解雇事由になる。", "note": "", "nuance": "assault（改まった暴行）より口語的。treat roughly（手荒に扱う、より一般的）とほぼ同義。", "groups": ["bully_mistreat"], "etymology": "rough（手荒に扱う・大まかにする）＋up（上へ）\n→ 相手を乱暴に扱い、痛めつけるイメージ\n→ そこから「手荒に扱う、暴行する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 360, "stage": 8, "verb": "get on with", "meaning": "（仕事を）進める", "def": "to continue doing something, especially work", "ex1": "Let's stop chatting and get on with the actual work.", "ja1": "おしゃべりはやめて、実際の作業を進めよう。", "ex2": "Let's get on with the agenda; we're behind.", "ja2": "遅れているので議事を進めましょう。", "note": "", "nuance": "continue（続ける、より一般的）とは違い、get on withは中断していた作業を「再開して進める」というニュアンスを含む。", "groups": ["undertake_continue_work"], "etymology": "get（得る・～になる）＋on（接触・継続）＋with（一緒に）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（仕事を）進める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 361, "stage": 8, "verb": "stay out", "meaning": "外にいて帰らない", "def": "to remain away from home, especially at night", "ex1": "She stayed out past midnight without telling anyone where she was.", "ja1": "彼女は誰にも行き先を告げず、深夜過ぎまで外にいた。", "ex2": "The team stayed out late celebrating the contract.", "ja2": "チームは契約成立を祝って遅くまで外にいた。", "note": "", "nuance": "not come home（改まった言い方）より口語的。stay out lateの形で「夜遅くまで外にいて帰らない」ことを表す。", "groups": ["home_or_out"], "etymology": "stay（とどまる）＋out（外へ）\n→ 内側の空間から外の世界へ出ていくイメージ\n→ そこから「外にいて帰らない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 362, "stage": 8, "verb": "branch out", "meaning": "手を広げる、新分野に進出する", "def": "to start doing something new or different", "ex1": "The bakery decided to branch out into wedding cakes this year.", "ja1": "そのパン屋は今年、ウェディングケーキの分野に手を広げることにした。", "ex2": "The company branched out into cloud services.", "ja2": "同社はクラウドサービスに進出した。", "note": "", "nuance": "expand（改まった拡大）より、branch outは既存の事業や活動から「新しい分野へ手を広げる」という発展的なニュアンスを含む。", "groups": [], "etymology": "branch（枝分かれする）＋out（外へ）\n→ 内側から外側へ向かって範囲を広げるイメージ\n→ そこから「手を広げる、新分野に進出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M32 48 L32 28\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 28 Q22 28 20 18 Q30 18 32 28 Q34 18 44 18 Q42 28 32 28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 363, "stage": 8, "verb": "sneak out", "meaning": "こっそり抜け出す", "def": "to leave a place quietly without being noticed", "ex1": "The teenagers snuck out through the window after their parents fell asleep.", "ja1": "両親が寝入ったあと、その十代の子たちは窓からこっそり抜け出した。", "ex2": "She sneaked out of the session to take a call.", "ja2": "彼女は電話のためセッションをそっと抜けた。", "note": "", "nuance": "escape quietly（改まった言い方）より口語的。sneak outは誰にも気づかれないよう「こっそり」抜け出す密かさを強調する。", "groups": ["sneak_out"], "etymology": "sneak（こっそり動く）＋out（外へ）\n→ 続いていた場から途中で外へ抜け出すイメージ\n→ そこから「こっそり抜け出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 364, "stage": 8, "verb": "chip away at", "meaning": "少しずつ削る、地道に取り組む", "def": "to gradually reduce or work at something", "ex1": "We've been chipping away at the debt for three years now.", "ja1": "私たちはもう3年間、その借金を少しずつ返済してきている。", "ex2": "We're chipping away at the backlog.", "ja2": "未処理案件を少しずつ片づけている。", "note": "", "nuance": "gradually reduce（改まった言い方）より口語的。chip away atは大きな問題や借金などに「少しずつ、地道に取り組む」忍耐強さを表す。", "groups": ["gradual_reduce"], "etymology": "chip（欠く）＋away（遠くへ）＋at（～めがけて）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「少しずつ削る、地道に取り組む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 365, "stage": 8, "verb": "hook up", "meaning": "接続する、つなぐ", "def": "to connect one piece of equipment to another", "ex1": "Can you help me hook up the new printer to the Wi-Fi?", "ja1": "新しいプリンターをWi-Fiに接続するのを手伝ってもらえる？", "ex2": "Can you hook up the laptop to the projector?", "ja2": "ノートPCをプロジェクターにつないでもらえますか。", "note": "", "nuance": "connect（接続する、より一般的）とほぼ同義。hook up withとは別の意味で、hook upは機器やケーブルをつなぐ場面で使う。", "groups": ["hook_up_senses"], "etymology": "hook（鉤で引っかける）＋up（上へ）\n→ 離れていた物同士のつながりを作るイメージ\n→ そこから「接続する、つなぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(11,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 366, "stage": 8, "verb": "hook up with", "meaning": "（人と）落ち合う、組む", "def": "to meet or start working with someone", "ex1": "Let's hook up for coffee sometime next week.", "ja1": "来週のどこかで、コーヒーでも飲みに落ち合おう。", "ex2": "We hooked up with a local partner for the rollout.", "ja2": "展開のため現地パートナーと組んだ。", "note": "文脈により性的な意味になるため、職場では使い方に注意", "nuance": "meet up（待ち合わせる、より一般的）とほぼ同義。hook up withはカジュアルな響きがあり、待ち合わせにも協力関係にも使える。", "groups": ["hook_up_senses"], "etymology": "hook（鉤で引っかける）＋up（上へ）＋with（一緒に）\n→ 上向き・完了や増加のイメージ\n→ そこから「（人と）落ち合う、組む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 367, "stage": 8, "verb": "stack up", "meaning": "匹敵する、比較して見劣りしない", "def": "to compare with something else", "ex1": "Their new phone just doesn't stack up against the competition.", "ja1": "彼らの新しい携帯は、競合製品と比べると見劣りする。", "ex2": "Let's see how our pricing stacks up against competitors.", "ja2": "当社の価格が競合と比べてどうか見てみましょう。", "note": "stack up against の形が多い", "nuance": "compare favorably（改まった言い方）より口語的。measure up（基準に達する）と似ているが、stack upは通常否定文で「見劣りする」ことを表す場面が多い。", "groups": [], "etymology": "stack（積み重ねる）＋up（上へ）\n→ 比較対象の高さまで積み上がるイメージ\n→ そこから「匹敵する、比較して見劣りしない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"18\" y=\"38\" width=\"28\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"20\" y=\"28\" width=\"24\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"22\" y=\"18\" width=\"20\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 368, "stage": 8, "verb": "go off on", "meaning": "怒鳴りつける", "def": "to suddenly start speaking angrily to someone", "ex1": "The coach went off on the referee after the missed call.", "ja1": "誤審のあと、コーチは審判に怒鳴りつけた。", "ex2": "The client went off on the vendor about the outage.", "ja2": "顧客は障害の件で業者を怒鳴りつけた。", "note": "Stage 2 の go off（鳴る）と区別", "nuance": "誰かに対して怒りを爆発させる、強い叱責。", "groups": ["scold_yell"], "etymology": "go（行く）＋off（離れて）＋on（接触・継続）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「怒鳴りつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 369, "stage": 8, "verb": "pack up", "meaning": "荷物をまとめる、片づける", "def": "to put things away or into containers when finishing", "ex1": "We need to pack up the whole apartment before Saturday.", "ja1": "土曜日までにアパート全体の荷物をまとめないといけない。", "ex2": "We packed up the booth at six.", "ja2": "6時にブースを片づけた。", "note": "", "nuance": "clean up（片づける、より一般的）とは違い、pack upは特に荷物をまとめて「移動や帰宅の準備をする」場面で使う。", "groups": ["tidy_up"], "etymology": "pack（荷造りする）＋up（上へ）\n→ 最後まできっちり仕上げる・整えるイメージ\n→ そこから「荷物をまとめる、片づける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 370, "stage": 8, "verb": "suck up to", "meaning": "ごまをする、へつらう", "def": "to try to please someone in authority insincerely", "ex1": "He's always sucking up to the boss, and everyone notices it.", "ja1": "彼はいつも上司にへつらっていて、みんな気づいている。", "ex2": "Sucking up to management won't fix the schedule.", "ja2": "上層部にごまをすっても日程は直らない。", "note": "", "nuance": "flatter（改まったお世辞）より口語的で否定的。please（喜ばせる、より中立的）とは違い、suck up toは自己利益のためにへつらうという軽蔑的なニュアンスを含む。", "groups": [], "etymology": "suck（吸う）＋up（上へ）＋to（～へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「ごまをする、へつらう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 371, "stage": 8, "verb": "get back together", "meaning": "よりを戻す、再び組む", "def": "to start a relationship or partnership again", "ex1": "After a year apart, they finally got back together.", "ja1": "1年離れていたあと、彼らはついによりを戻した。", "ex2": "The two firms got back together on a new joint venture.", "ja2": "両社は新しい合弁事業で再び手を組んだ。", "note": "", "nuance": "reunite（改まった再会）より口語的。break up（別れる）の反対で、恋人や仲間が「よりを戻す」ことを表す。", "groups": ["dating_romance"], "etymology": "get（得る・～になる）＋back（後ろ・元へ）＋together（一つに）\n→ 離れていた関係が元の状態へ戻るイメージ\n→ そこから「よりを戻す、再び組む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 372, "stage": 8, "verb": "narrow down", "meaning": "絞り込む", "def": "to reduce the number of possibilities or options", "ex1": "We narrowed down the list of candidates from twenty to three.", "ja1": "候補者リストを20人から3人まで絞り込んだ。", "ex2": "We narrowed down the cause to a network setting.", "ja2": "原因をネットワーク設定に絞り込んだ。", "note": "", "nuance": "reduce（減らす、より一般的）とは違い、narrow downは選択肢を検討しながら「絞り込んでいく」プロセスを強調する。", "groups": ["gradual_reduce"], "etymology": "narrow（狭める）＋down（下へ）\n→ \n→ そこから「絞り込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 373, "stage": 8, "verb": "wrap up", "meaning": "まとめる、終える", "def": "to finish or conclude something", "ex1": "Let's wrap up the meeting; everyone has somewhere else to be.", "ja1": "会議をまとめましょう、みんな次の予定があるので。", "ex2": "Let's wrap up the meeting in five minutes.", "ja2": "あと5分で会議を締めましょう。", "note": "", "nuance": "finish（単に終える）とは違い、wrap upは物事を「きれいにまとめて締めくくる」というニュアンスを含む。", "groups": ["organize"], "etymology": "wrap（包む）＋up（上へ）\n→ 最後まできっちり仕上げる・整えるイメージ\n→ そこから「まとめる、終える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(6,32,32)\"><rect x=\"18\" y=\"26\" width=\"28\" height=\"22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 26 L32 48 M18 34 L46 34\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 374, "stage": 8, "verb": "squeeze in", "meaning": "無理に詰め込む、都合をつける", "def": "to fit something into a limited space or schedule", "ex1": "Somehow she squeezed in a haircut between two back-to-back meetings.", "ja1": "彼女はどうにか、連続する2つの会議の間に美容院の予定を詰め込んだ。", "ex2": "Can we squeeze in a review before Friday?", "ja2": "金曜より前にレビューを入れられますか。", "note": "", "nuance": "fit in*2（予定に入れる）と似ているが、squeeze inは特にすでに詰まっているスケジュールに「無理やり時間を作る」努力を強調する。", "groups": ["schedule_fit"], "etymology": "squeeze（絞る）＋in（中へ）\n→ 詰まったスケジュールの内側に押し込むイメージ\n→ そこから「無理に詰め込む、都合をつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 375, "stage": 8, "verb": "sink in", "meaning": "実感が湧く、腑に落ちる", "def": "to be fully understood or felt after some time", "ex1": "It hadn't sunk in that I'd actually gotten the job until I saw the contract.", "ja1": "契約書を見るまで、自分が本当に採用されたという実感が湧かなかった。", "ex2": "It took a day for the scale of the incident to sink in.", "ja2": "障害の規模を実感するのに1日かかった。", "note": "", "nuance": "realize（改まった気づき）より、sink inは事実が頭では分かっていても「感情として実感が湧く」までの時間差を表す。", "groups": [], "etymology": "sink（沈む）＋in（中へ）\n→ 事実がじわじわと心の内側に染み込むイメージ\n→ そこから「実感が湧く、腑に落ちる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(12,32,32)\"><path d=\"M16 26 Q22 20 28 26 Q34 32 40 26 Q46 20 50 26\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 30 L32 46\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M27 41 L32 46 L37 41\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 376, "stage": 8, "verb": "crack up", "meaning": "大笑いする", "def": "to laugh a lot, or to make someone laugh a lot", "ex1": "His impression of the teacher made the whole class crack up.", "ja1": "彼の先生のものまねに、クラス全員が大笑いした。", "ex2": "The team cracked up at the typo on the slide.", "ja2": "スライドの誤字にチームは大笑いした。", "note": "", "nuance": "laugh hard（改まった言い方）より口語的。burst out laughing（急に笑い出す、より劇的）と似ているが、crack upはより日常会話で使われる。", "groups": [], "etymology": "crack（ひびを入れる）＋up（上へ）\n→ 抑えきれない笑いが込み上げてくるイメージ\n→ そこから「大笑いする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 377, "stage": 8, "verb": "play into", "meaning": "（相手の）思うつぼになる", "def": "to unintentionally help someone else's plan", "ex1": "By getting angry, you're just playing into his hands.", "ja1": "怒ることで、あなたはただ彼の思うつぼになっているだけだ。", "ex2": "Rushing the estimate plays into the client's strategy.", "ja2": "見積もりを急ぐのは顧客の思うつぼだ。", "note": "play into someone's hands の形が多い", "nuance": "fall for（だまされる、より一般的）とは違い、play intoは相手の狙い通りに行動してしまい「思うつぼにはまる」ことを表す。", "groups": [], "etymology": "play（遊ぶ・演じる）＋into（中へ変化）\n→ 相手が仕組んだ罠の中へまんまとはまるイメージ\n→ そこから「（相手の）思うつぼになる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M27 24 L27 40 L41 32 Z\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 378, "stage": 8, "verb": "pull off*2", "meaning": "（道路脇に）車を寄せて止める", "def": "to drive off a road and stop", "ex1": "She pulled off onto the shoulder to check the strange noise.", "ja1": "彼女はその変な音を確認するため、路肩に車を寄せて止めた。", "ex2": "The driver pulled off the road to check the address.", "ja2": "運転手は住所を確認するため道路脇に車を寄せた。", "note": "Stage 4 の pull off（やってのける）と区別", "nuance": "pull over（路肩に寄せて止める、より一般的）とほぼ同義。pull off*2はハイウェイなど本線から「外れて」停車する場面でよく使う。", "groups": ["pull_over_stop_car"], "etymology": "pull（引く）＋off（離れて）\n→ 動いていたものから電源やつながりを切り離して止めるイメージ\n→ そこから「（道路脇に）車を寄せて止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 379, "stage": 8, "verb": "bank on", "meaning": "当てにする、頼りにする", "def": "to rely on something happening", "ex1": "Don't bank on the weather being good; bring an umbrella just in case.", "ja1": "天気が良いと当てにしないで、念のため傘を持っていって。", "ex2": "Don't bank on the client approving it this week.", "ja2": "顧客が今週承認すると当てにしないでください。", "note": "", "nuance": "rely on（頼る、より一般的）とほぼ同義。count on（頼りにする）と似ているが、bank onは特に将来の結果を「当てにする」場面で使う。", "groups": ["rely_on"], "etymology": "bank（頼る）＋on（接触・継続）\n→ 相手の上に体重を預けるようによりかかるイメージ\n→ そこから「当てにする、頼りにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M44 18 L44 46\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"20\" cy=\"32\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M20 36 L20 44 M20 38 L44 30\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 380, "stage": 8, "verb": "rule out", "meaning": "除外する、可能性を否定する", "def": "to eliminate something as a possibility", "ex1": "The doctors ruled out anything serious after running the tests.", "ja1": "検査をした結果、医者たちは重大な病気の可能性を除外した。", "ex2": "We ruled out a hardware failure.", "ja2": "ハードウェア障害の可能性は除外した。", "note": "", "nuance": "eliminate（改まった除去）より口語的。exclude（除外する、より一般的）と似ているが、rule outは可能性を検討した上で「否定する」というプロセスを含む。", "groups": [], "etymology": "rule（線を引く・支配する）＋out（外へ）\n→ いらない物や選択肢を内側から外へ弾き出すイメージ\n→ そこから「除外する、可能性を否定する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 381, "stage": 8, "verb": "come off as", "meaning": "〜という印象を与える（言動・態度から）", "def": "to appear to have a particular quality", "ex1": "He didn't mean to be rude, but his comment came off as cold.", "ja1": "彼に失礼にするつもりはなかったが、その発言は冷たい印象を与えた。", "ex2": "The reply came off as dismissive.", "ja2": "その返信はそっけない印象を与えた。", "note": "Stage 6 の come across as とほぼ同義", "nuance": "seem（〜のように見える、より一般的）とほぼ同義。come across as（印象を与える）とほぼ同じ意味だが、come off asは言動や態度から受ける印象に焦点がある。", "groups": ["impression"], "etymology": "come（来る）＋off（離れて）＋as（～として）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「〜という印象を与える（言動・態度から）」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 382, "stage": 8, "verb": "throw together", "meaning": "急ごしらえで作る", "def": "to make something quickly without much care", "ex1": "We threw together a quick dinner from whatever was left in the fridge.", "ja1": "冷蔵庫に残っていたもので、急ごしらえの夕食を作った。", "ex2": "He threw together a deck the night before.", "ja2": "彼は前夜に急ごしらえで資料を作った。", "note": "", "nuance": "prepare quickly（改まった言い方）より口語的。make（作る、より一般的）とは違い、throw togetherは時間をかけず「急ごしらえで作る」ラフさを強調する。", "groups": [], "etymology": "throw（投げる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「急ごしらえで作る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 383, "stage": 8, "verb": "buzz in", "meaning": "（解錠して）中に入れる", "def": "to let someone into a building by pressing a buzzer", "ex1": "Could you buzz me in? I forgot my key at home.", "ja1": "解錠して中に入れてもらえる？鍵を家に忘れちゃって。", "ex2": "Reception will buzz you in at the second door.", "ja2": "受付が2つ目の扉で解錠します。", "note": "", "nuance": "unlock（改まった解錠）より口語的。let in（中に入れる、より一般的）と似ているが、buzz inは特にインターホンで遠隔操作して解錠する場面で使う。", "groups": ["enter_various"], "etymology": "buzz（ブンブン鳴る）＋in（中へ）\n→ 外から内側の空間へ入り込むイメージ\n→ そこから「（解錠して）中に入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 384, "stage": 8, "verb": "space out", "meaning": "ぼんやりする、上の空になる", "def": "to stop paying attention and think about nothing", "ex1": "I completely spaced out during the meeting and missed my cue.", "ja1": "会議中すっかりぼんやりしていて、自分の出番を逃してしまった。", "ex2": "I spaced out during the long status report.", "ja2": "長い進捗報告の間、上の空だった。", "note": "くだけた表現", "nuance": "daydream（改まった空想）より口語的。zone out（俗語的、より強い）と似ているが、space outは注意力が散漫になりぼんやりする状態を表す。", "groups": [], "etymology": "space（間隔をあける）＋out（外へ）\n→ 意識がふわっと外へ漂い出てしまうイメージ\n→ そこから「ぼんやりする、上の空になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 385, "stage": 8, "verb": "throw off", "meaning": "調子を狂わせる、混乱させる", "def": "to confuse someone or disrupt something", "ex1": "The last-minute schedule change really threw off our whole plan.", "ja1": "土壇場でのスケジュール変更が、私たちの計画をすっかり狂わせた。", "ex2": "The last-minute change threw off the whole schedule.", "ja2": "直前の変更で全体の日程が狂った。", "note": "", "nuance": "confuse（混乱させる、より一般的）とは違い、throw offは順調だった調子やペースを「狂わせる」というニュアンスを強く含む。", "groups": ["mess_disrupt"], "etymology": "throw（投げる）＋off（離れて）\n→ 整っていたリズムや調子を狂わせて外すイメージ\n→ そこから「調子を狂わせる、混乱させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 386, "stage": 8, "verb": "chip in", "meaning": "出し合う／口を挟む", "def": "to contribute money; to add a comment", "ex1": "We all chipped in to buy her a nice retirement gift.", "ja1": "彼女に素敵な退職祝いを買うため、みんなでお金を出し合った。", "ex2": "Feel free to chip in with your ideas.", "ja2": "気軽に意見を出してください。", "note": "", "nuance": "contribute（改まった貢献）より口語的。pitch in（協力する、より一般的）と似ているが、chip inは特にお金を少しずつ出し合う場面でよく使う。", "groups": ["interrupt"], "etymology": "chip（欠く）＋in（中へ）\n→ 進行中の輪の内側に割り込んで加わるイメージ\n→ そこから「出し合う／口を挟む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 387, "stage": 8, "verb": "get to*3", "meaning": "悩ませる、こたえる", "def": "to annoy or upset someone over time", "ex1": "Something about his tone really gets to me.", "ja1": "彼のその口調が、どうも私にはこたえる。", "ex2": "The constant changes are getting to the team.", "ja2": "度重なる変更がチームにこたえている。", "note": "Stage 1 / 2 に別語義あり", "nuance": "bother（困らせる、より一般的）とは違い、get to*3は何かがじわじわと精神的に「こたえる、応える」ことを表す。", "groups": ["get_to_senses"], "etymology": "get（得る・～になる）＋to（～へ）\n→ 負担が心の方向へじわじわ迫ってくるイメージ\n→ そこから「悩ませる、こたえる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M40 16 L44 12 M43 20 L48 18 M39 24 L44 23\" stroke=\"#C79A3D\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><rect x=\"18\" y=\"26\" width=\"22\" height=\"18\" rx=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 388, "stage": 8, "verb": "stumble on", "meaning": "偶然見つける", "def": "to find something by chance", "ex1": "I stumbled on this little café while looking for a parking spot.", "ja1": "駐車場を探している時に、この小さなカフェを偶然見つけた。", "ex2": "I stumbled on the bug while testing something else.", "ja2": "別のテスト中に偶然その不具合を見つけた。", "note": "", "nuance": "find by chance（改まった言い方）より口語的。come across（偶然見つける、より一般的）と似ているが、stumble onはつまずくように「思いがけず」見つけるニュアンスが強い。", "groups": ["encounter"], "etymology": "stumble（つまずく）＋on（接触・継続）\n→ 電源をつなげて機能させるイメージ\n→ そこから「偶然見つける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-5,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 389, "stage": 8, "verb": "wind down", "meaning": "徐々に終わる、くつろぐ", "def": "to relax; to gradually reduce activity", "ex1": "The party started winding down around midnight.", "ja1": "パーティーは深夜あたりから徐々にお開きになっていった。", "ex2": "The project is winding down this quarter.", "ja2": "プロジェクトは今四半期で徐々に終息する。", "note": "", "nuance": "relax（くつろぐ、より一般的）とは違い、wind downはパーティーやイベントが「徐々に落ち着いて終わっていく」プロセスを強調する。", "groups": ["gradual_pace"], "etymology": "wind（巻く）＋down（下へ）\n→ \n→ そこから「徐々に終わる、くつろぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-10,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 390, "stage": 8, "verb": "gross out", "meaning": "気持ち悪がらせる", "def": "to make someone feel disgusted", "ex1": "The smell from the fridge was enough to gross out the whole kitchen.", "ja1": "冷蔵庫からのにおいで、キッチン全体が気持ち悪がった。", "ex2": "The photo in the slide grossed out the audience.", "ja2": "スライドの写真に聴衆は不快感を示した。", "note": "くだけた表現", "nuance": "disgust（改まった不快感）より口語的。weird outと似ているが、gross outは主に見た目や匂いなど生理的な「気持ち悪さ」を与えることを表す。", "groups": ["disturb_creep_out"], "etymology": "gross（（口語で）気持ち悪い・下品な）＋out（外へ）\n→ 見た人の嫌悪感を外に引き出してしまうイメージ\n→ そこから「気持ち悪がらせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 391, "stage": 8, "verb": "ask out", "meaning": "デートに誘う", "def": "to invite someone to go on a date", "ex1": "He finally worked up the courage to ask her out.", "ja1": "彼はついに勇気を振り絞って、彼女をデートに誘った。", "ex2": "Asking out a subordinate can create a conflict of interest.", "ja2": "部下をデートに誘うのは利益相反になりうる。", "note": "", "nuance": "invite on a date（改まった言い方）より口語的。ask outはデートに誘うという最も一般的なカジュアル表現。", "groups": ["dating_romance"], "etymology": "ask（尋ねる）＋out（外へ）\n→ 相手を外の場へ誘い出す誘いのイメージ\n→ そこから「デートに誘う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 392, "stage": 8, "verb": "talk around", "meaning": "遠回しに話す、核心を避ける", "def": "to avoid discussing the main point", "ex1": "She talked around the question instead of giving a real answer.", "ja1": "彼女はまともに答える代わりに、その質問について遠回しに話した。", "ex2": "Stop talking around the delay and give us a date.", "ja2": "遅延の話を避けずに日付を出してください。", "note": "", "nuance": "avoid the topic（改まった言い方）より、talk aroundは核心に触れずに「その周辺だけを話す」という遠回しな話し方を強調する。", "groups": [], "etymology": "talk（話す）＋around（周りに）\n→ 本題に触れず、その周りを回るように話すイメージ\n→ そこから「遠回しに話す、核心を避ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"9\" r=\"5\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2.3\"/><path d=\"M11.8 6.2 L13.3 8.6 L10.3 8.9 Z\" fill=\"#B5392F\" stroke=\"none\"/></g></svg>"}, {"no": 393, "stage": 8, "verb": "sell out", "meaning": "売り切れる／信念を売る", "def": "to be completely sold; to betray your principles", "ex1": "The concert tickets sold out within ten minutes of going on sale.", "ja1": "そのコンサートのチケットは、発売から10分で売り切れた。", "ex2": "The venue sold out before we could register.", "ja2": "申し込む前に会場が満席になった。", "note": "", "nuance": "sell all（改まった言い方）より口語的。run out of stock（在庫切れになる、より一般的）と似ているが、sell outは信念を「売り渡す」という比喩的な意味でも使う。", "groups": [], "etymology": "sell（売る）＋out（外へ）\n→ 内側にあった力や在庫が外へ出尽くして、空っぽになるイメージ\n→ そこから「売り切れる／信念を売る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 394, "stage": 8, "verb": "block out", "meaning": "遮る／（時間を）確保する", "def": "to prevent light or noise; to reserve time", "ex1": "I always block out Friday afternoons for deep, focused work.", "ja1": "私はいつも金曜の午後を、集中作業のために確保している。", "ex2": "I blocked out two hours for the review.", "ja2": "レビューのため2時間を確保した。", "note": "", "nuance": "reserve（予約する、改まった言い方）より、block outはスケジュール上の時間を他の予定が入らないよう「確保する」ことを強調する。物理的に光や音を「遮る」意味もある。", "groups": [], "etymology": "block（塞ぐ）＋out（外へ）\n→ 時間や視界を外側から区切って確保するイメージ\n→ そこから「遮る／（時間を）確保する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 395, "stage": 8, "verb": "weird out", "meaning": "気味悪がらせる、戸惑わせる", "def": "to make someone feel uncomfortable or strange", "ex1": "His sudden mood swings really weirded her out.", "ja1": "彼の突然の気分の変化に、彼女はすっかり戸惑った。", "ex2": "The unexpected call weirded out the client.", "ja2": "予期しない電話に顧客は戸惑った。", "note": "くだけた表現", "nuance": "gross out（気持ち悪がらせる）と似ているが、weird outは奇妙さや違和感によって相手を「戸惑わせる」というニュアンスが強い。", "groups": ["disturb_creep_out"], "etymology": "weird（（口語で）奇妙な・気味の悪い）＋out（外へ）\n→ 見た人の嫌悪感を外に引き出してしまうイメージ\n→ そこから「気味悪がらせる、戸惑わせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M27 29 m-2,0 a2,2 0 1,0 4,0 a2,2 0 1,0 -4,0\" stroke=\"#C79A3D\" stroke-width=\"1.5\" fill=\"none\"/><path d=\"M37 29 m-2,0 a2,2 0 1,0 4,0 a2,2 0 1,0 -4,0\" stroke=\"#C79A3D\" stroke-width=\"1.5\" fill=\"none\"/><path d=\"M27 40 Q32 37 37 40\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 396, "stage": 8, "verb": "sniff out", "meaning": "嗅ぎつける、探り当てる", "def": "to discover something that is hidden", "ex1": "The journalist sniffed out the scandal months before anyone else.", "ja1": "その記者は、他の誰よりも数ヶ月早くそのスキャンダルを嗅ぎつけた。", "ex2": "The auditor sniffed out the discrepancy.", "ja2": "監査人は不一致を嗅ぎつけた。", "note": "", "nuance": "detect（改まった検知）より口語的。find out（判明する、より一般的）とは違い、sniff outは犬が匂いを嗅ぐように「勘や調査で嗅ぎつける」比喩的な表現。", "groups": ["probe_sniff"], "etymology": "sniff（嗅ぐ）＋out（外へ）\n→ 手がかりの匂いを外へ追って探し当てるイメージ\n→ そこから「嗅ぎつける、探り当てる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M28 18 Q22 24 24 32 Q26 40 32 40 Q36 40 36 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M40 20 Q44 24 42 28 M44 30 Q48 33 46 37\" stroke=\"#C79A3D\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 397, "stage": 8, "verb": "egg on", "meaning": "けしかける、あおる", "def": "to encourage someone to do something unwise", "ex1": "His friends egged him on until he finally jumped off the diving board.", "ja1": "友人たちがけしかけ続けた末、彼はついに飛び込み台から飛んだ。", "ex2": "Don't egg on a heated discussion in the meeting.", "ja2": "会議で白熱した議論をあおらないでください。", "note": "", "nuance": "encourage（改まった励まし）とは違い、egg onは通常よくない行動をするよう「けしかける、あおる」という否定的なニュアンスを含む。", "groups": [], "etymology": "egg（（onで）けしかける）＋on（接触・継続）\n→ 相手の上に働きかけて感情を煽るイメージ\n→ そこから「けしかける、あおる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><path d=\"M20 44 L34 30\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M34 30 L34 24 M34 30 L40 30\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"20\" cy=\"44\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 398, "stage": 8, "verb": "cut back on", "meaning": "減らす、切り詰める", "def": "to reduce the amount of something", "ex1": "We're trying to cut back on takeout and cook more at home.", "ja1": "テイクアウトを減らして、もっと家で料理するようにしている。", "ex2": "We cut back on travel expenses this year.", "ja2": "今年は出張費を切り詰めた。", "note": "", "nuance": "reduce（減らす、より一般的）とは違い、cut back onは特に支出や消費を「意識的に切り詰める」という節約のニュアンスを含む。", "groups": ["gradual_reduce"], "etymology": "cut（切る）＋back（後ろ・元へ）＋on（接触・継続）\n→ 元の場所や状態に戻るイメージ\n→ そこから「減らす、切り詰める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 399, "stage": 8, "verb": "pull up*3", "meaning": "（成績・数値を）引き上げる", "def": "to improve something to a higher level", "ex1": "The new coach managed to pull up the team's ranking in just one season.", "ja1": "その新しいコーチは、たった1シーズンでチームの順位を引き上げた。", "ex2": "The new campaign pulled up the numbers in Q3.", "ja2": "新しい施策が第3四半期の数字を押し上げた。", "note": "Stage 6 / 7 に別語義あり", "nuance": "improve（改善する、より一般的）とは違い、pull up*3は特に成績や順位などの数値を「引き上げる」場面でよく使う。", "groups": ["pull_up_senses"], "etymology": "pull（引く）＋up（上へ）\n→ 低かった数値を上へ押し上げるイメージ\n→ そこから「（成績・数値を）引き上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 400, "stage": 8, "verb": "stand up to", "meaning": "立ち向かう、耐える", "def": "to resist someone unfairly powerful; to withstand", "ex1": "She stood up to her boss when he tried to take credit for her work.", "ja1": "上司が彼女の手柄を横取りしようとした時、彼女は立ち向かった。", "ex2": "He stood up to unreasonable demands from the client.", "ja2": "彼は顧客の不当な要求に立ち向かった。", "note": "", "nuance": "resist（改まった抵抗）より、stand up toは強い相手やプレッシャーに「屈せず立ち向かう」という勇気を強調する。", "groups": ["oppose_resist"], "etymology": "stand（立つ）＋up（上へ）＋to（～へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「立ち向かう、耐える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(9,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 401, "stage": 8, "verb": "slip out", "meaning": "こっそり抜け出す／（言葉が）口をつく", "def": "to leave quietly; to say something accidentally", "ex1": "I slipped out during the boring part of the ceremony.", "ja1": "式典の退屈な部分の間に、こっそり抜け出した。", "ex2": "The figure slipped out before it was official.", "ja2": "正式発表の前にその数字が漏れてしまった。", "note": "", "nuance": "sneak out（こっそり抜け出す、より一般的）とほぼ同義だが、slip outは「言葉がうっかり口から出てしまう」という別の意味でも使う多義語。", "groups": ["sneak_out"], "etymology": "slip（すべる）＋out（外へ）\n→ 続いていた場から途中で外へ抜け出すイメージ\n→ そこから「こっそり抜け出す／（言葉が）口をつく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 402, "stage": 8, "verb": "run by", "meaning": "（確認のため）意見を聞く", "def": "to tell someone about something to get their opinion", "ex1": "Can I run this idea by you before I bring it to the client?", "ja1": "クライアントに持っていく前に、このアイデアについて意見を聞かせてもらえる？", "ex2": "Let me run the draft by my manager.", "ja2": "草案を上司に確認させてください。", "note": "run something by someone の語順", "nuance": "ask（尋ねる、より一般的）とは違い、run byは考えやアイデアを相手に「一度見てもらって意見を聞く」という確認のニュアンスを含む。", "groups": ["confirm_check"], "etymology": "run（走る）＋by（そばを）\n→ 案を相手のそばに一度通して確認するイメージ\n→ そこから「（確認のため）意見を聞く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><circle cx=\"32\" cy=\"16\" r=\"5\" fill=\"#C79A3D\"/><path d=\"M32 21 L32 34\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 34 L24 48 M32 34 L41 45\" stroke=\"#C79A3D\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><path d=\"M32 25 L22 30 M32 25 L43 21\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 403, "stage": 9, "verb": "break in", "meaning": "侵入する", "def": "to enter a place illegally by force", "ex1": "Someone broke in while I was on vacation, and only the TV was missing.", "ja1": "休暇中に誰かが侵入し、テレビだけが無くなっていた。", "ex2": "The office was broken in over the weekend.", "ja2": "週末にオフィスに侵入された。", "note": "", "nuance": "enter illegally（改まった侵入）より口語的。会話に「割り込む」という別の意味もある多義語。", "etymology": "break（壊す・分ける）＋in（中へ）\n→ 障害を壊して中に入り込むイメージ\n→ そこから「侵入する」という意味に。", "illustration": "", "groups": []}, {"no": 404, "stage": 9, "verb": "burn down", "meaning": "全焼する", "def": "to be completely destroyed by fire", "ex1": "The old barn burned down before anyone could call the fire department.", "ja1": "誰かが消防に電話する前に、その古い納屋は全焼した。", "ex2": "The warehouse burned down, destroying the entire inventory.", "ja2": "その倉庫は全焼し、在庫が全て失われた。", "note": "", "nuance": "burn（単に燃える）とは違い、burn downは建物などが「跡形もなく」焼け落ちることを強調する。", "etymology": "burn（燃える）＋down（下へ）\n→ 建物が燃え尽きて崩れ落ちるイメージ\n→ そこから「全焼する」という意味に。", "illustration": "", "groups": []}, {"no": 405, "stage": 9, "verb": "carry on", "meaning": "（Aを）続ける", "def": "to continue doing something", "ex1": "Even after the injury, he carried on training every single day.", "ja1": "怪我をしたあとも、彼は毎日トレーニングし続けた。", "ex2": "Please carry on with the meeting; I'll join in five minutes.", "ja2": "会議を続けてください、5分後に合流します。", "note": "", "nuance": "continue（単に続ける）より口語的。keep on（〜し続ける）とほぼ同義だが、carry onは中断されそうな状況でもあえて続ける意志を含む。", "etymology": "carry（運ぶ）＋on（接触・継続）\n→ 途切れず物事を運び続けるイメージ\n→ そこから「続ける」という意味に。", "illustration": "", "groups": []}, {"no": 406, "stage": 9, "verb": "come about", "meaning": "起こる", "def": "to happen, especially in a particular way", "ex1": "How did that come about? Nobody told me about the schedule change.", "ja1": "それってどうやって起きたの？予定変更なんて誰にも聞いてないよ。", "ex2": "The merger came about after months of quiet negotiation.", "ja2": "その合併は何ヶ月もの水面下の交渉の末に実現した。", "note": "", "nuance": "happen（単に起こる、より一般的）より、経緯や理由に焦点を当てて「どのようにして起こったか」を語る場面でよく使う。", "etymology": "come（来る）＋about（あたりに）\n→ 事情のあたりを巡って結果が現れるイメージ\n→ そこから「起こる」という意味に。", "illustration": "", "groups": []}, {"no": 407, "stage": 9, "verb": "come out", "meaning": "（ニュースなどが）明らかとなる", "def": "to become known publicly", "ex1": "The truth about the scandal finally came out years later.", "ja1": "そのスキャンダルの真実は、何年も経ってようやく明るみに出た。", "ex2": "The new film hasn't come out yet, but the trailer already has millions of views.", "ja2": "その新作映画はまだ公開されていないが、予告編は既に何百万回も再生されている。", "note": "", "nuance": "reveal（誰かが暴露する、能動的）とは違い、come outは情報や製品が自然に「世に出てくる」という受動的な視点。", "etymology": "come（来る）＋out（外へ）\n→ 隠れていた情報が外に出てくるイメージ\n→ そこから「明らかとなる」という意味に。", "illustration": "", "groups": []}, {"no": 408, "stage": 9, "verb": "go on", "meaning": "（Aを）続ける", "def": "to continue happening or doing something", "ex1": "The meeting went on for three hours longer than planned.", "ja1": "その会議は予定より3時間も長く続いた。", "ex2": "Please go on with your presentation; we'll save questions for the end.", "ja2": "そのままプレゼンを続けてください、質問は最後にまとめて受けます。", "note": "", "nuance": "continue（単に続ける）より口語的。go on doingで「〜し続ける」、go on with Aで「Aを続ける」の形でよく使う。", "etymology": "go（行く）＋on（接触・継続）\n→ 途切れず進み続けるイメージ\n→ そこから「続ける」という意味に。", "illustration": "", "groups": []}, {"no": 409, "stage": 9, "verb": "grow up", "meaning": "成長する", "def": "to become an adult", "ex1": "He grew up in a small fishing village on the coast.", "ja1": "彼は海沿いの小さな漁村で育った。", "ex2": "The company grew up alongside the industry it helped create.", "ja2": "その会社は、自らが生み出した業界とともに成長していった。", "note": "", "nuance": "become an adult（大人になる、より直接的）と似ているが、grow upは「育っていく過程」全体を指す。子供っぽい態度への指摘としてGrow up!（大人になれ）とも使う。", "etymology": "grow（育つ）＋up（上へ）\n→ 上に向かって育っていくイメージ\n→ そこから「成長する」という意味に。", "illustration": "", "groups": []}, {"no": 410, "stage": 9, "verb": "hurry up", "meaning": "急ぐ", "def": "to do something more quickly", "ex1": "Hurry up, or we'll miss the last train home.", "ja1": "急いで、じゃないと帰りの最終電車に間に合わないよ。", "ex2": "We need to hurry up if we want to make the client deadline.", "ja2": "クライアントの締め切りに間に合わせたいなら、急ぐ必要がある。", "note": "", "nuance": "hurry（単に急ぐ）より口語的で、しばしば命令形で「早くして」と急かす場面に使われる。", "etymology": "hurry（急ぐ）＋up（上へ・程度を増す）\n→ 急ぐ度合いをさらに高めるイメージ\n→ そこから「急ぐ」という意味に。", "illustration": "", "groups": []}, {"no": 411, "stage": 9, "verb": "look back", "meaning": "（Aを）回想する", "def": "to think about something in the past", "ex1": "Looking back on it now, quitting that job was the best decision I ever made.", "ja1": "今振り返ると、あの仕事を辞めたのは人生で一番良い決断だった。", "ex2": "When we look back on this quarter, the product launch will stand out.", "ja2": "今四半期を振り返ると、あの製品発表が際立って見えるだろう。", "note": "", "nuance": "remember（単に思い出す）より、過去の出来事を意識的に「振り返って考える」という内省的なニュアンスを含む。", "etymology": "look（見る）＋back（後ろ・元へ）\n→ 視線を後ろに向けて振り返るイメージ\n→ そこから「回想する」という意味に。", "illustration": "", "groups": []}, {"no": 412, "stage": 9, "verb": "look on", "meaning": "傍観する", "def": "to watch something happen without taking part", "ex1": "Most of them looked on as the man was robbing the bank.", "ja1": "その男が銀行強盗をしている間、彼らのほとんどはただ見ていた。", "ex2": "Investors could only look on as the stock price kept dropping.", "ja2": "投資家たちは株価が下がり続けるのをただ見ていることしかできなかった。", "note": "", "nuance": "watch（単に見る）より、行動せず「ただ見ているだけ」という消極的な立場を強調する。look on A as Bで「AをBとみなす」という別の意味もある。", "etymology": "look（見る）＋on（接触・継続）\n→ 視線を対象に向け続けるイメージ\n→ そこから「傍観する」という意味に。", "illustration": "", "groups": []}, {"no": 413, "stage": 9, "verb": "pass away", "meaning": "（人が）死ぬ", "def": "to die (a polite way of saying it)", "ex1": "Her grandmother passed away peacefully in her sleep last spring.", "ja1": "彼女の祖母は去年の春、眠るように安らかに亡くなった。", "ex2": "The company's founder passed away just before the product he championed launched.", "ja2": "その会社の創業者は、自身が推進した製品の発売直前に亡くなった。", "note": "", "nuance": "die（単に死ぬ）より婉曲的で丁寧な言い方。pass byや通過するという意味のpassとは別の熟語なので混同しないよう注意。", "etymology": "pass（通す）＋away（遠くへ）\n→ この世から遠くへ去っていくイメージ\n→ そこから「死ぬ」という婉曲的な意味に。", "illustration": "", "groups": []}, {"no": 414, "stage": 9, "verb": "pass by", "meaning": "通り過ぎる", "def": "to go past something or someone", "ex1": "I ran into my old roommate as she passed by the coffee shop.", "ja1": "元ルームメイトがそのコーヒーショップを通り過ぎた時に、ばったり会った。", "ex2": "Most commuters just pass by the new mural without noticing it.", "ja2": "ほとんどの通勤客は、その新しい壁画に気づかずに通り過ぎていく。", "note": "", "nuance": "他動詞的にpass A byで「Aのそばを通り過ぎる」とも使う。pass away（死ぬ）とは全く別の意味なので注意。", "etymology": "pass（通す）＋by（そばを）\n→ 対象のそばを通り抜けていくイメージ\n→ そこから「通り過ぎる」という意味に。", "illustration": "", "groups": []}, {"no": 415, "stage": 9, "verb": "run out", "meaning": "（物資などが）尽きる", "def": "to have no more of something left", "ex1": "We ran out of milk again, so cereal for breakfast is off the table.", "ja1": "また牛乳を切らしてしまったので、朝食にシリアルは無理だ。", "ex2": "The vendor ran out of stock before half the orders could be filled.", "ja2": "その業者は、注文の半分も対応できないうちに在庫を切らした。", "note": "", "nuance": "use up（使い切る、原因側の視点）とほぼ同義だが、run out ofは「気づいたら無くなっていた」という受動的なニュアンスが強い。", "etymology": "run（走る）＋out（外へ）\n→ 中身が外へ出尽くしてしまうイメージ\n→ そこから「（物資などが）尽きる」という意味に。", "illustration": "", "groups": []}, {"no": 416, "stage": 9, "verb": "set in", "meaning": "（好ましくないことが）始まる", "def": "for something unpleasant to begin and seem likely to continue", "ex1": "Panic set in once the passengers realized the flight was cancelled.", "ja1": "フライトがキャンセルされたと分かった途端、乗客たちにパニックが広がった。", "ex2": "Doubt set in among investors as the earnings report was delayed again.", "ja2": "決算報告が再び遅れると、投資家たちの間に疑念が広がった。", "note": "", "nuance": "begin（単に始まる）より、天候の悪化や感情の広がりなど、望ましくない状態がじわじわと定着していく様子を表す。", "etymology": "set（置く）＋in（中へ）\n→ 好ましくない状態が中に居座るイメージ\n→ そこから「始まる」という意味に。", "illustration": "", "groups": []}, {"no": 417, "stage": 9, "verb": "set out", "meaning": "（Aに）出発する", "def": "to begin a journey or a task", "ex1": "We set out on the journey at dawn, before the roads got crowded.", "ja1": "道路が混む前に、夜明けとともに旅に出発した。", "ex2": "The team set out to redesign the entire onboarding process.", "ja2": "そのチームはオンボーディングの過程全体を再設計しようと着手した。", "note": "", "nuance": "leave（単に出発する）より、目的地や目標に向けて「これから始める」という意気込みを含む。set out to doで「〜しようと着手する」の形でもよく使う。", "etymology": "set（置く）＋out（外へ）\n→ 自分を外の世界に送り出すイメージ\n→ そこから「出発する」という意味に。", "illustration": "", "groups": []}, {"no": 418, "stage": 9, "verb": "slow down", "meaning": "スピードを落とす、（人に）落ち着くよう言う", "def": "to reduce speed or activity", "ex1": "Slow down, we still have twenty minutes before the meeting starts.", "ja1": "落ち着いて、会議が始まるまでまだ20分あるから。", "ex2": "Hiring needs to slow down until the new budget is approved.", "ja2": "新しい予算が承認されるまで、採用のペースを落とす必要がある。", "note": "", "nuance": "命令形のSlow down!は、実際の速度だけでなく、焦っている人に「落ち着いて」と声をかける場面でもよく使う。他動詞としてslow A downで「Aのスピードを落とす」とも使う。stop（完全に止める）とは違い、ペースを緩めるだけのニュアンス。", "etymology": "slow（遅くする）＋down（下へ）\n→ 速度を下向きに落としていくイメージ\n→ そこから「スピードを落とす」という意味に。", "illustration": "", "groups": []}, {"no": 419, "stage": 9, "verb": "speak out", "meaning": "率直に意見を述べる", "def": "to state one's opinion openly, often about something controversial", "ex1": "Few employees were willing to speak out as a politician's aide about the policy change.", "ja1": "その方針変更について、その政治家の補佐官として率直に意見する職員はほとんどいなかった。", "ex2": "Several engineers spoke out against the rushed release schedule.", "ja2": "何人かのエンジニアが、急かされたリリーススケジュールに対して異議を唱えた。", "note": "", "nuance": "say（単に言う）より、遠慮せず、時にリスクを取って「はっきり意見を述べる」という積極性を含む。", "etymology": "speak（話す）＋out（外へ）\n→ 心の内にある考えを外へ出すイメージ\n→ そこから「率直に意見を述べる」という意味に。", "illustration": "", "groups": []}, {"no": 420, "stage": 9, "verb": "blow up", "meaning": "Aを爆破する", "def": "to destroy something with an explosion, or to inflate it", "ex1": "The demolition crew blew up the old bridge in under ten seconds.", "ja1": "解体業者は10秒足らずでその古い橋を爆破した。", "ex2": "The scandal blew up into a full corporate crisis within days.", "ja2": "そのスキャンダルは数日のうちに企業全体の危機へと拡大した。", "note": "", "nuance": "destroy（改まった破壊）より口語的。空気を入れて風船を膨らませる意味と、問題が急激に「拡大する」比喩的な意味も持つ多義語。", "etymology": "blow（吹く）＋up（上へ・程度を増す）\n→ 空気や勢いを吹き込んで膨らませるイメージ\n→ そこから「爆破する」という意味に。", "illustration": "", "groups": []}, {"no": 421, "stage": 9, "verb": "bring about", "meaning": "A（破滅など）を引き起こす", "def": "to cause something to happen", "ex1": "The new regulation brought about major changes in how we handle client data.", "ja1": "その新しい規制は、クライアントデータの扱い方に大きな変化をもたらした。", "ex2": "The merger brought about a complete restructuring of the sales team.", "ja2": "その合併は営業チームの完全な再編をもたらした。", "note": "", "nuance": "cause（引き起こす、より一般的）とほぼ同義。良いことにも悪いことにも使え、bring about changeの形でよく使われる。", "etymology": "bring（持ってくる）＋about（あたりに）\n→ 結果をこちら側に持ってくるイメージ\n→ そこから「引き起こす」という意味に。", "illustration": "", "groups": []}, {"no": 422, "stage": 9, "verb": "carry out", "meaning": "A（計画など）を実行する", "def": "to perform or complete a task or plan", "ex1": "The team carried out the entire migration over a single weekend.", "ja1": "チームはたった一つの週末でその移行作業を実行し終えた。", "ex2": "We carried out three rounds of testing before the launch.", "ja2": "発売前に3回のテストを実施した。", "note": "", "nuance": "perform/execute（改まった実行）より口語的。conduct（改まった実施）と似ているが、carry outは計画や指示に沿って「やり遂げる」ニュアンスが強い。", "etymology": "carry（運ぶ）＋out（外へ）\n→ 計画を外の世界へ運び出して実現するイメージ\n→ そこから「実行する」という意味に。", "illustration": "", "groups": []}, {"no": 423, "stage": 9, "verb": "cut down", "meaning": "Aを減らす", "def": "to reduce the amount of something", "ex1": "We're trying to cut down on takeout and cook more at home.", "ja1": "テイクアウトを減らして、もっと家で料理するようにしている。", "ex2": "The company cut down on overtime costs by hiring two more staff.", "ja2": "その会社はスタッフを2人増やすことで残業コストを削減した。", "note": "", "nuance": "reduce（減らす、より一般的）とは違い、cut down onは特に支出や消費を「意識的に切り詰める」という節約のニュアンスを含む。木を切り倒す意味もある多義語。", "etymology": "cut（切る）＋down（下へ）\n→ 量を切り下げていくイメージ\n→ そこから「減らす」という意味に。", "illustration": "", "groups": []}, {"no": 424, "stage": 9, "verb": "get down", "meaning": "Aを書き留める", "def": "to write something quickly, or to get off a higher place", "ex1": "Let me get down your number before I forget it.", "ja1": "忘れないうちに、あなたの番号を書き留めておくね。", "ex2": "Get everything down in the notes before the client leaves.", "ja2": "クライアントが帰る前に、全部メモに書き留めておいて。", "note": "", "nuance": "write down（書き留める、より一般的）とほぼ同義。get down from（〜から降りる）という別の意味もある多義語。", "etymology": "get（得る）＋down（下へ）\n→ 頭の中の考えを紙面に下ろすイメージ\n→ そこから「書き留める」という意味に。", "illustration": "", "groups": []}, {"no": 425, "stage": 9, "verb": "hand down", "meaning": "A（判決・評決など）を言い渡す", "def": "to officially announce a decision, or to pass something to a younger generation", "ex1": "The judge handed down the ruling after a two-week trial.", "ja1": "2週間の審理の後、裁判官はその判決を言い渡した。", "ex2": "This recipe has been handed down through four generations of the family.", "ja2": "このレシピは家族4代にわたって受け継がれてきた。", "note": "", "nuance": "announce（発表する、より一般的）より、権威ある立場から正式に「下す」というニュアンスを含む。家宝などを代々「伝える」意味でも使う。", "etymology": "hand（手渡す）＋down（下へ）\n→ 上の立場から下へ手渡すイメージ\n→ そこから「言い渡す」という意味に。", "illustration": "", "groups": []}, {"no": 426, "stage": 9, "verb": "have on", "meaning": "A（服など）を身に着けている", "def": "to be wearing something", "ex1": "I didn't even notice what he had on until someone mentioned it.", "ja1": "誰かに言われるまで、彼が何を着ているか気づかなかった。", "ex2": "Make sure everyone has their badge on before entering the server room.", "ja2": "サーバールームに入る前に、全員が社員証を身につけていることを確認してください。", "note": "", "nuance": "wear（身につける、より一般的な動詞）とほぼ同義だが、have onは状態を表す表現で進行形にはならない。", "etymology": "have（持つ）＋on（接触・継続）\n→ 服を体にくっつけたまま持っているイメージ\n→ そこから「身に着けている」という意味に。", "illustration": "", "groups": []}, {"no": 427, "stage": 9, "verb": "hold back", "meaning": "A（人・物）を引き止める", "def": "to prevent someone or something from moving or progressing, or to restrain emotion", "ex1": "She held back her tears until the meeting was completely over.", "ja1": "彼女は会議が完全に終わるまで涙をこらえた。", "ex2": "Outdated infrastructure is holding back the company's growth.", "ja2": "老朽化したインフラが、その会社の成長を妨げている。", "note": "", "nuance": "hold in（感情を内に抑える）と似ているが、hold backは物理的に「引き止める」、または進歩を「妨げる」場面でも幅広く使う。", "etymology": "hold（持つ・保つ）＋back（後ろ・元へ）\n→ 前に出ようとする物を後ろに保つイメージ\n→ そこから「引き止める」という意味に。", "illustration": "", "groups": []}, {"no": 428, "stage": 9, "verb": "leave out", "meaning": "Aを（Bから）除外する", "def": "to not include something", "ex1": "A few typos here and there don't take away from how good the essay is, but we left out the missing citation.", "ja1": "多少のタイプミスがあってもそのエッセイの良さは損なわれないが、抜けていた引用は除外した。", "ex2": "We left out the smaller vendors from the initial shortlist.", "ja2": "最初の候補リストから小規模な業者は除外した。", "note": "", "nuance": "exclude（改まった除外）より口語的。omit（省略する）と似ているが、leave outは意図的にも偶然にも使える。", "etymology": "leave（去る・残す）＋out（外へ）\n→ 対象を外側に残していくイメージ\n→ そこから「除外する」という意味に。", "illustration": "", "groups": []}, {"no": 429, "stage": 9, "verb": "let down", "meaning": "Aを失望させる", "def": "to disappoint someone", "ex1": "I felt like I'd let everyone down after missing that deadline.", "ja1": "その締め切りを逃して、みんなを失望させた気がした。", "ex2": "The vendor let us down by shipping the wrong parts twice in a row.", "ja2": "その業者は2回連続で違う部品を送ってきて、私たちを失望させた。", "note": "", "nuance": "disappoint（改まったがっかりさせ）より口語的。upset（動揺させる）ほど深刻ではないが、期待を裏切るという意味は共通する。", "etymology": "let（させる）＋down（下へ）\n→ 相手の期待を下に落とさせるイメージ\n→ そこから「失望させる」という意味に。", "illustration": "", "groups": []}, {"no": 430, "stage": 9, "verb": "look over", "meaning": "Aにざっと目を通す", "def": "to examine something quickly", "ex1": "Let's go over the numbers one more time before the presentation.", "ja1": "プレゼンの前に、もう一度数字を見直しましょう。", "ex2": "Could you look over this contract before I sign it?", "ja2": "サインする前に、この契約書に目を通してもらえますか。", "note": "", "nuance": "look through(ざっと目を通す)より丁寧に、詳しく見直す・確認するニュアンス。reviewとほぼ同義。", "etymology": "look（見る）＋over（越えて）\n→ 全体を越えるように視線を走らせるイメージ\n→ そこから「ざっと目を通す」という意味に。", "illustration": "", "groups": []}, {"no": 431, "stage": 9, "verb": "put forward", "meaning": "A（意見・案など）を提出する", "def": "to suggest an idea or plan for consideration", "ex1": "She put forward a proposal to cut costs by working with local vendors.", "ja1": "彼女は地元業者と組んでコストを削減する提案をした。", "ex2": "The committee put forward three candidates for the new director role.", "ja2": "その委員会は新しいディレクター職に3人の候補者を推薦した。", "note": "", "nuance": "suggest（提案する、より一般的）とほぼ同義だが、put forwardは正式な検討の場に「議題として提出する」ニュアンスを含む。", "etymology": "put（置く）＋forward（前へ）\n→ 案を検討の場の前に置くイメージ\n→ そこから「提出する」という意味に。", "illustration": "", "groups": []}, {"no": 432, "stage": 9, "verb": "set aside", "meaning": "A（金・時間など）を取っておく", "def": "to save something for a particular purpose", "ex1": "We set aside a small budget for unexpected repairs.", "ja1": "予期せぬ修理のために、少額の予算を取り分けておいた。", "ex2": "Let's set aside an hour next week just to review the roadmap.", "ja2": "来週、そのロードマップを見直すためだけに1時間確保しよう。", "note": "", "nuance": "save（貯める、より一般的）とほぼ同義。put asideとも言い換えられ、後で使うために意図的に確保しておくというニュアンス。", "etymology": "set（置く）＋aside（脇に）\n→ 今は使わず脇に置いておくイメージ\n→ そこから「取っておく」という意味に。", "illustration": "", "groups": []}, {"no": 433, "stage": 9, "verb": "set down", "meaning": "Aを書き留める", "def": "to write something down, or to put something you're carrying onto a surface", "ex1": "The witness set down every detail of what she remembered.", "ja1": "その目撃者は覚えている限りの詳細を全て書き留めた。", "ex2": "Please set down the guidelines in writing so everyone can refer to them.", "ja2": "全員が参照できるよう、そのガイドラインを文書にまとめてください。", "note": "", "nuance": "write down（より一般的）とほぼ同義。put down*3とも似ているが、set downはやや改まった響きを持つ。", "etymology": "set（置く）＋down（下へ）\n→ 頭の中の内容を紙の上に置くイメージ\n→ そこから「書き留める」という意味に。", "illustration": "", "groups": []}, {"no": 434, "stage": 9, "verb": "set off", "meaning": "Aを引き起こす", "def": "to cause something to start, or to begin a journey", "ex1": "A single spark set off the entire fire alarm system.", "ja1": "たった一つの火花が、火災報知器システム全体を作動させた。", "ex2": "We set off for the client site at six in the morning.", "ja2": "私たちは朝6時にクライアントの現場へ向けて出発した。", "note": "", "nuance": "cause（引き起こす、より一般的）とほぼ同義。set out（旅に出発する）と似ているが、set offはアラームや連鎖反応を「引き起こす」場面でよく使う。", "etymology": "set（置く）＋off（離れて）\n→ その場から離れて動き出させるイメージ\n→ そこから「引き起こす」という意味に。", "illustration": "", "groups": []}, {"no": 435, "stage": 9, "verb": "set up", "meaning": "A（組織・仕組み・機器など）を設立する、整える", "def": "to establish or arrange something", "ex1": "They set up the whole home office in a single weekend.", "ja1": "彼らはたった一つの週末で、ホームオフィス全体を整えた。", "ex2": "We need to set up a new process for handling refund requests.", "ja2": "返金依頼の対応について、新しいプロセスを整える必要がある。", "note": "", "nuance": "establish（改まった設立）より口語的。build（作る、より広い意味）とは違い、set upは組織や仕組み、機器などを「整える」ニュアンスが強い。", "etymology": "set（置く）＋up（上へ）\n→ 組織や仕組みを立ち上げるイメージ\n→ そこから「設立する」という意味に。", "illustration": "", "groups": []}, {"no": 436, "stage": 9, "verb": "shut down", "meaning": "A（工場など）を閉鎖する", "def": "to close or stop a business or system from operating", "ex1": "The entire payment system went down for almost three hours, forcing us to shut down checkout.", "ja1": "決済システム全体がほぼ3時間停止し、チェックアウトを閉鎖せざるを得なかった。", "ex2": "The factory was shut down after failing three consecutive safety inspections.", "ja2": "その工場は安全検査に3回連続で不合格になり、閉鎖された。", "note": "", "nuance": "close（閉じる、より一般的）とは違い、shut downは工場やシステムなど「稼働しているものを完全に停止させる」ニュアンスを強く含む。", "etymology": "shut（閉める）＋down（下へ）\n→ 稼働をすっかり閉じて止めるイメージ\n→ そこから「閉鎖する」という意味に。", "illustration": "", "groups": []}, {"no": 437, "stage": 9, "verb": "sum up", "meaning": "A（意見・考えなど）を要約する", "def": "to summarize something briefly", "ex1": "Let's wrap up the meeting; everyone has somewhere else to be, but first let me sum up what we agreed on.", "ja1": "会議をまとめましょう、みんな次の予定があるので。ただその前に、合意した点を要約させてください。", "ex2": "To sum up, we're on track for the launch but need more testers.", "ja2": "要約すると、発売に向けては順調だが、テスターがもっと必要だ。", "note": "", "nuance": "summarize（改まった要約）より口語的。To sum upの形で「要するに」という前置きとしてもよく使われる。", "etymology": "sum（合計する）＋up（上へ・完了）\n→ 細かい点を一つにまとめ上げるイメージ\n→ そこから「要約する」という意味に。", "illustration": "", "groups": []}, {"no": 438, "stage": 9, "verb": "think over", "meaning": "Aをじっくり考える", "def": "to consider something carefully before deciding", "ex1": "Take a step back and think over the whole plan before deciding.", "ja1": "決める前に、一歩引いて計画全体をじっくり考えて。", "ex2": "I need a day to think over the offer before I respond.", "ja2": "その提案についてじっくり考えるため、返事まで1日ください。", "note": "", "nuance": "consider（考える、より一般的）とほぼ同義だが、think overは特に決断や解決に向けて「じっくり考える」プロセスを強調する。", "etymology": "think（考える）＋over（越えて）\n→ 物事の全体を越えるように考え巡らすイメージ\n→ そこから「じっくり考える」という意味に。", "illustration": "", "groups": []}, {"no": 439, "stage": 9, "verb": "turn over", "meaning": "A（財産など）を（Bに）譲渡する", "def": "to hand control of something to someone else, or to flip it", "ex1": "After thirty years, he finally turned the family business over to his daughter.", "ja1": "30年経って、彼はついに家業を娘に引き渡した。", "ex2": "We turned over the entire codebase to the new vendor last month.", "ja2": "先月、コードベース全体を新しい業者に引き渡した。", "note": "", "nuance": "hand over（引き渡す、より一般的）とほぼ同義。turn over a new leaf（心を入れ替える）という慣用句でもよく使われる。", "etymology": "turn（向きを変える）＋over（越えて）\n→ 持ち主を越えて相手側に渡すイメージ\n→ そこから「譲渡する」という意味に。", "illustration": "", "groups": []}, {"no": 440, "stage": 9, "verb": "write down", "meaning": "Aを書き留める", "def": "to record something in writing", "ex1": "I write down every idea the moment it comes to me, or I forget it by lunch.", "ja1": "アイデアが浮かんだ瞬間に書き留めないと、お昼までに忘れてしまう。", "ex2": "Write down the action items before everyone leaves the room.", "ja2": "みんなが部屋を出る前に、アクションアイテムを書き留めておいて。", "note": "", "nuance": "record（改まった記録）より口語的。put downやset downともほぼ同義で、最も一般的な「書き留める」の言い方。", "etymology": "write（書く）＋down（下へ）\n→ 頭の中の内容を紙の上に書き下ろすイメージ\n→ そこから「書き留める」という意味に。", "illustration": "", "groups": []}, {"no": 441, "stage": 9, "verb": "catch up with", "meaning": "Aに追いつく", "def": "to reach the same level or position as someone or something ahead", "ex1": "He walks so fast that I have to jog just to catch up with him.", "ja1": "彼はとても早歩きなので、追いつくには小走りしないといけない。", "ex2": "Our competitors have finally caught up with us in market share.", "ja2": "競合他社はついに市場シェアで私たちに追いついた。", "note": "", "nuance": "keep up with（遅れずについていく、現在進行形）に対し、catch up withはすでに遅れている状態から追いつく動作を表す。", "etymology": "catch（捕まえる）＋up（上へ・達しているレベルまで）＋with（一緒に）\n→ 遅れている分を捕まえて相手と同じ地点まで達するイメージ\n→ そこから「追いつく」という意味に。", "illustration": "", "groups": []}, {"no": 442, "stage": 9, "verb": "do away with", "meaning": "Aを処分する", "def": "to get rid of something, or to abolish a rule or system", "ex1": "We finally did away with the old paper-based approval process.", "ja1": "私たちはついに、古い紙ベースの承認プロセスを廃止した。", "ex2": "The new CEO did away with three layers of middle management.", "ja2": "新しいCEOは、中間管理職の3階層を撤廃した。", "note": "", "nuance": "get rid of（処分する、より一般的）とほぼ同義。dispose of（改まった処分）より口語的で、制度や慣習を「廃止する」場面でよく使う。", "etymology": "do（する）＋away（遠くへ）＋with（一緒に）\n→ 対象を遠くへやって済ませてしまうイメージ\n→ そこから「処分する」という意味に。", "illustration": "", "groups": []}, {"no": 443, "stage": 9, "verb": "get along with", "meaning": "A（人）と仲よくやっていく", "def": "to have a friendly relationship with someone", "ex1": "Even though they argue constantly, the roommates somehow get along with each other.", "ja1": "そのルームメイトたちはしょっちゅう言い合いしているのに、なぜか仲良くやっている。", "ex2": "New hires who get along with their manager tend to stay longer.", "ja2": "上司とうまくやっていく新入社員ほど、長く在籍する傾向がある。", "note": "", "nuance": "get on with とほぼ同義（イギリス英語ではget onがより一般的）。fight（喧嘩する）の反対で、良好な関係を保つことを表す。", "etymology": "get（得る）＋along（沿って）＋with（一緒に）\n→ 相手と歩調を合わせて進んでいくイメージ\n→ そこから「仲よくやっていく」という意味に。", "illustration": "", "groups": []}, {"no": 444, "stage": 9, "verb": "keep up with", "meaning": "Aに遅れないでついていく", "def": "to stay at the same pace or level as something or someone", "ex1": "He walks so fast that I have to jog just to keep up with him.", "ja1": "彼はとても早歩きなので、ついていくには小走りしないといけない。", "ex2": "It's hard to keep up with how quickly the industry is changing.", "ja2": "業界の変化があまりに速く、ついていくのが難しい。", "note": "", "nuance": "follow（単についていく）より、遅れずに同じペースを保つという努力のニュアンスがある。catch up with（遅れを取り戻す）とは違い、keep up withはすでに追いついている状態を維持すること。", "etymology": "keep（保つ）＋up（上へ）＋with（一緒に）\n→ 相手と同じ高さを保ち続けるイメージ\n→ そこから「遅れないでついていく」という意味に。", "illustration": "", "groups": []}, {"no": 445, "stage": 9, "verb": "look down on", "meaning": "A（人・流行など）を見下す", "def": "to consider someone or something inferior", "ex1": "He never looks down on people just because they're new to the field.", "ja1": "彼はその分野に不慣れだからといって、人を見下すことは決してない。", "ex2": "The old guard tends to look down on remote-first companies.", "ja2": "旧来の勢力は、リモート中心の企業を見下しがちだ。", "note": "", "nuance": "despise（改まった軽蔑）より口語的。look up to（尊敬する）の反対で、相手を「格下」と見なす態度を表す。", "etymology": "look（見る）＋down（下へ）＋on（接触・継続）\n→ 視線を下に向けて相手を見続けるイメージ\n→ そこから「見下す」という意味に。", "illustration": "", "groups": []}, {"no": 446, "stage": 9, "verb": "look out for", "meaning": "Aを警戒する", "def": "to be careful about a possible danger or problem, or to watch for something specific", "ex1": "Watch out for scammers calling about your \"unpaid taxes.\"", "ja1": "「未払いの税金」について電話してくる詐欺師に注意してください。", "ex2": "Look out for the updated terms in tomorrow's contract revision.", "ja2": "明日の契約改定で、更新された条項に注意してください。", "note": "", "nuance": "watch out for（より一般的な警戒）とほぼ同義。look out forは危険だけでなく、特定の情報や兆候を「注意深く探す」場面でも使う。", "etymology": "look（見る）＋out（外へ）＋for（求めて）\n→ 外の危険を求めるように目を光らせるイメージ\n→ そこから「警戒する」という意味に。", "illustration": "", "groups": []}, {"no": 447, "stage": 9, "verb": "make up for", "meaning": "A（損失など）の埋め合わせをする", "def": "to compensate for something lost or lacking", "ex1": "She took a second job on weekends just to make up for the difference in rent.", "ja1": "家賃の差額を埋め合わせるためだけに、彼女は週末に副業を始めた。", "ex2": "We're offering a discount to make up for the shipping delay.", "ja2": "配送の遅れを埋め合わせるため、割引を提供しています。", "note": "", "nuance": "compensate for（改まった埋め合わせ）より口語的。make upは不足分やミスを「別の方法で埋め合わせる」場面で幅広く使う。", "etymology": "make（作る）＋up（上へ・完了）＋for（求めて）\n→ 不足を埋めて元の水準まで作り上げるイメージ\n→ そこから「埋め合わせをする」という意味に。", "illustration": "", "groups": []}, {"no": 448, "stage": 9, "verb": "speak ill of", "meaning": "A（人）のことを悪く言う", "def": "to say bad things about someone", "ex1": "He never speaks ill of anyone, even people who've wronged him.", "ja1": "彼は自分を傷つけた人に対してさえ、決して悪く言わない。", "ex2": "It's unprofessional to speak ill of a former employer in an interview.", "ja2": "面接で以前の雇用主を悪く言うのはプロらしくない。", "note": "", "nuance": "criticize（批判する、より直接的）とは違い、speak ill ofは陰で人の悪口を言うというニュアンスを含む。speak well of（よく言う）の反対。", "etymology": "speak（話す）＋ill（悪く）＋of（〜の）\n→ 対象について悪い言葉を発するイメージ\n→ そこから「悪く言う」という意味に。", "illustration": "", "groups": []}, {"no": 449, "stage": 9, "verb": "speak well of", "meaning": "A（人）のことをよく言う", "def": "to say good things about someone", "ex1": "Everyone who's worked with her speaks well of her leadership.", "ja1": "彼女と働いたことのある人は皆、その指導力を高く評価する。", "ex2": "Former clients still speak well of the agency years later.", "ja2": "元クライアントたちは、何年も経った今でもその代理店を高く評価している。", "note": "", "nuance": "praise（改まった称賛）より口語的。speak ill of（悪く言う）の反対で、誰かのことを好意的に語る場面で使う。", "etymology": "speak（話す）＋well（良く）＋of（〜の）\n→ 対象について良い言葉を発するイメージ\n→ そこから「よく言う」という意味に。", "illustration": "", "groups": []}, {"no": 450, "stage": 9, "verb": "watch out for", "meaning": "Aに警戒する", "def": "to be careful of a possible danger", "ex1": "Watch out for the loose step on the way down.", "ja1": "降りる途中の緩んだ段差に気をつけて。", "ex2": "Watch out for scope creep once the client starts adding requests.", "ja2": "クライアントが要望を追加し始めたら、スコープの肥大化に気をつけて。", "note": "", "nuance": "look out for（より広い注意）とほぼ同義。watch out forは特に「具体的な危険」への警戒に使われることが多い。", "etymology": "watch（見張る）＋out（外へ）＋for（求めて）\n→ 外の危険を求めるように見張り続けるイメージ\n→ そこから「警戒する」という意味に。", "illustration": "", "groups": []}, {"no": 451, "stage": 9, "verb": "walk through", "meaning": "（人に）順を追って説明する、案内する", "def": "to explain or guide someone through something step by step", "ex1": "Could you walk me through the new expense system?", "ja1": "新しい経費精算のシステムについて、順を追って説明してもらえますか？", "ex2": "The manager walked the new hire through the onboarding process.", "ja2": "マネージャーは新入社員に入社手続きを順を追って案内した。", "note": "", "nuance": "explainより丁寧で、実際に一緒に手順をたどりながら教えるニュアンス。show（見せる）より踏み込んで、隣について一つずつ確認しながら進める感じ。", "groups": [], "etymology": "walk（歩く）＋through（通り抜けて）\n→ 一緒に歩いて中を通り抜けるイメージ\n→ そこから「順を追って説明する、案内する」という意味に。", "illustration": ""}];

const GROUP_INFO = {"visit_casually": {"label": "ふらっと立ち寄る", "note": "共通するのは「予定せず訪れる」こと。drop byは訪問先そのものに主眼があり、come byは「立ち寄って何かを受け取る・得る」ニュアンスも持つ。drop inは3つの中で最も軽く、突然性が強い。"}, "board_vehicle": {"label": "乗り物に乗る", "note": "get onは電車やバスへの標準的な乗車動作。hop onはそれをより身軽に、ひょいと乗り込む軽快でカジュアルな響きに変える。"}, "return": {"label": "戻る・戻す", "note": "come backは話し手のいる場所へ戻ってくる（聞き手視点）、go backは元いた場所へ帰る（話者側の視点）。get backは口語的な万能形。take back*2／bring backは「（物を）戻す・持ち帰る」という他動詞的な使い方。"}, "move_house": {"label": "引っ越し（反意語）", "note": "move inは新居への入居、move outはそこからの退去。ちょうど反対の意味のペア。"}, "appear": {"label": "現れる", "note": "show upは単に姿を見せるという中立的な表現。turn upは「ひょっこり」「意外にも」という予想外のニュアンスが強く、なくし物が出てくる場合にもよく使う。"}, "postpone": {"label": "延期する", "note": "put offが最も一般的な「延期する」。hold offは「様子を見て一旦保留する」という判断のニュアンスが強く、push back*2はすでに決まっていた予定を後ろにずらす具体的な動作を指す。"}, "submit": {"label": "提出する", "note": "hand inとturn inはほぼ同義（宿題やレポートなど）で、turn inの方がやや口語的。put in*2は「申請書を提出する」といった特定の文脈で使われやすい。"}, "leave_place": {"label": "立ち去る", "note": "go awayは単純に立ち去る、または症状が消えるという意味でも使う中立的な表現。walk outは抗議や不満を示して途中で退席する、より強い意味合いを持つ。"}, "power": {"label": "電源（反意語）", "note": "turn onは電源・明かりをつける、turn offは消す。日常会話で最頻出クラスの反意語ペア。"}, "encounter": {"label": "偶然出会う", "note": "run intoとbump intoは主に「人に」偶然出会う際に使う。come acrossは「物・情報に」偶然出くわす場合が中心。stumble onはそこからさらに「たまたま発見する」という驚きのニュアンスが加わる。"}, "tidy_up": {"label": "片づける", "note": "clean upは掃除して綺麗にすること全般。put awayは使った物を元の場所へしまう動作。pack upは旅行や引っ越しの文脈で荷物をまとめることを指す。"}, "turn_out_end_up": {"label": "結局〜になる", "note": "turn outは「蓋を開けてみたら〜だった」という判明のニュアンス。end upは「最終的にそうなった」という結果そのものを重視する。come down toは「要するに〜次第だ」と要因を絞り込む表現。"}, "discard": {"label": "捨てる", "note": "ほぼ同義。throw outの方が「その場から外へ放り出す」という物理的な動作がわずかに強く出る。"}, "hotel_checkin": {"label": "チェックイン（反意語）", "note": "check inはホテルや空港での手続きを済ませて入ること、check outはその逆の退出・精算の手続き。"}, "choose": {"label": "選ぶ", "note": "pick outは複数の中から選び出す動作そのもの。go forは「これに決める」という積極的な選択。go withは「これで合わせる／これにしておく」という、やや消極的・妥協的な選択も含む。"}, "gather": {"label": "集まる", "note": "get togetherはやや広い意味の「集まる」。meet upは「事前に約束して落ち合う」という待ち合わせのニュアンスが強い。"}, "wait": {"label": "少し待つ", "note": "ほぼ同義。hold onの方が電話口などでやや丁寧に響き、hang onはよりカジュアルな響きを持つ。"}, "distribute": {"label": "配る", "note": "ほぼ同義で「配る」。pass out*2の方がやや口語的に使われる。"}, "fall_down": {"label": "転ぶ・倒れる", "note": "ほぼ同義。fall overは「バランスを崩して転ぶ」動作そのものに寄り、fall downは結果として「倒れている」状態も含めて指せる。"}, "use_up": {"label": "使い果たす", "note": "run out ofは「主語（人や物）が〜を切らす」という視点。use upは「〜を使い切る」という、使う側の動作そのものに焦点がある。"}, "succeed": {"label": "うまくいく", "note": "work outは物事が「うまくいく」という全般的な表現。pull offは「難しいことをやってのける」達成感を伴う。come offは口語的でくだけた響き。pay off*2は「努力や投資が実を結ぶ」場合に使い、make out*2 (2)は「首尾よくやる」というインフォーマルな表現。"}, "speak_loudly": {"label": "大きな声で話す", "note": "speak upは「もっと大きな声で／勇気を持って意見を言う」ことを促す表現。call outは「大声で呼ぶ」意味に加え、「公然と非難する」という意味でも使われる。"}, "convey_info": {"label": "考えを伝える", "note": "pass onは情報を人から人へ伝達すること。get acrossは「考えを相手に理解させる」、伝わることそのものに焦点がある。"}, "opportunity_arises": {"label": "機会・話が持ち上がる", "note": "come upは話題や用事がふと持ち上がること。come up*2は機会そのものが生じること。come along*2やcome around*3は「機会や時期が巡ってくる」という周期性・偶然性のニュアンスを持つ。"}, "head_toward": {"label": "〜へ向かう", "note": "head toは目的地に向かう方向性そのものを表す。go over toは「そちらへ移動する」という意味のほか、比喩的に「（考え方などの）立場を変える」という意味でも使われる。"}, "accomplish_through": {"label": "やり遂げる", "note": "get throughはやり遂げる・乗り切るという全般的な表現。follow throughは「最後まで計画通りにやり遂げる」有言実行のニュアンス。push throughは「抵抗を押し切って成立させる」強い推進力を伴う。"}, "return_money": {"label": "返す", "note": "give backは物を返す一般的な表現。pay backは「借金や恩を返済する」場合に使う。take backは「返品する」、または「発言を撤回する」という意味で使われる。"}, "call_phone": {"label": "電話をかける", "note": "call backは「折り返し電話する」。call upはただ電話をかけるという中立的な表現。hit upはかなりカジュアルな「連絡する」という響きを持つ。"}, "match_suit": {"label": "合う・似合う", "note": "ほぼ同義で「合う・似合う」。go togetherの方がより一般的に、物事の調和を表す場面で使われる。"}, "understand": {"label": "理解する", "note": "take inは情報を吸収して理解すること。figure outは考えを巡らせて答えにたどり着くこと。catch on*2は口語的に「わかる、飲み込む」という響きを持つ。"}, "be_careful": {"label": "気をつける", "note": "ほぼ同義の警告表現。多くの場面で置き換え可能。"}, "organize": {"label": "整理する・まとめる", "note": "get together*2は物や情報をひとまとめにすること。put togetherは部品などを組み立てること。wrap upは物事を仕上げて終えること。sort outは混乱した状況を整理して解決することを指す。"}, "made_of_from": {"label": "材料・原料（作る）", "note": "make fromとmake out ofは「原料が姿を変えて」別のものになる場合に使う（例：ぶどうからワイン）。make ofは「材料がそのままの形で見える」場合に使う（例：木製の机）。make intoは「〜に作り変える」という変化の方向そのものを示す。"}, "avoid_stay_away": {"label": "近づかない・避ける", "note": "keep awayは他動詞的に「（何かを）近づかせない」。stay awayは自動詞的に「自分が近寄らない」。keep offは「（表面や話題に）触れない」という意味で使われる。"}, "volume": {"label": "音量・温度（反意語）", "note": "turn upは音量や温度を上げる、turn downは下げる。日常会話で頻出する反意語ペア。"}, "help_cover": {"label": "代理を務める・手伝う", "note": "help outは一般的な「手伝う」。cover forとfill in forはどちらも「人の代理を務める」という意味だが、cover forには「かばう」というニュアンスも含まれる。"}, "review_check": {"label": "確認する・見直す", "note": "go overは資料などを見直すこと。look intoは問題を詳しく調査すること。check out*2は気軽に「確認してみる」という軽さを持つ。"}, "avoid_evade": {"label": "回避する・逃れる", "note": "get around*2は「規則や制約を巧妙に回避する」こと。get out ofは「義務や責任から逃れる」ことを指す。"}, "break_into_parts": {"label": "分解する", "note": "break up*2は全体を細かく分けること。break down*2は要素ごとに分解して分析すること（内訳を示す場合にも使う）。take apartは物理的に分解する動作そのものを指す。"}, "calm_down": {"label": "落ち着く", "note": "calm downは興奮や怒りを鎮めること。settle downは気持ちが落ち着く、または生活が安定するという意味も持つ。chill outは非常にカジュアルな「リラックスする」という響き。"}, "rely_on": {"label": "頼る", "note": "turn toは困った時に頼る対象を求めること。count onは「当てにできる」という信頼のニュアンス。bank onは「それを前提に計画する」という、より強い依存を表す。"}, "deceive": {"label": "だます・だまされる", "note": "take in*2は「だます」側からの視点。fall forは「だまされる」（または「恋に落ちる」）という、される側の視点で使われる。"}, "write_down": {"label": "書き留める", "note": "ほぼ同義で「書き留める」。多くの場面で置き換え可能。"}, "come_along_together": {"label": "一緒に連れて行く・ついていく", "note": "bring alongは自分が誰かを連れて行くこと。tag alongは誘われていないのに自分からくっついていくことを指す。"}, "distinguish": {"label": "見分ける", "note": "make out*2は「かろうじて識別する」という困難さを伴う。tell apartは似たもの同士を比較して見分けるというニュアンスが強い。"}, "pull_over_stop_car": {"label": "車を止める", "note": "pull overは「路肩に寄せて止まる」という典型的な表現。pull upは単に「車が止まる」ことを指す。pull off*2は「道路脇に車を寄せる」動作そのものに焦点がある。"}, "fill_form": {"label": "記入する", "note": "ほぼ同義で「記入する」。fill outの方がアメリカ英語でより一般的に使われる。"}, "endure": {"label": "我慢する・耐える", "note": "put up withは「不快なことを我慢する」という広い意味で使われる。sit throughは「退屈でも最後まで座って耐える」という、より具体的な場面を指す。"}, "begin": {"label": "〜として始まる", "note": "ほぼ同義で「〜として始まる」。start offはその後の展開に、start outは出発点そのものに、それぞれ焦点がある。"}, "impression": {"label": "印象を与える", "note": "ほぼ同義で「〜という印象を与える」。互換性が高く、どちらを使ってもよい場面が多い。"}, "hand_over": {"label": "引き渡す", "note": "turn in*2は「犯人などを当局に引き渡す」という特定の文脈で使われる。hand overは物や権限を一般的に「引き渡す」という意味を持つ。"}, "interrupt": {"label": "口を挟む", "note": "butt inは「無礼に割り込む」という否定的なニュアンスが強い。chip inは「（お金や意見を）少しずつ出し合う」場合にも使われ、口を挟むという意味ではより中立的。"}, "sneak_out": {"label": "こっそり抜け出す", "note": "ほぼ同義で「こっそり抜け出す」。slip outは「言葉がつい口をついて出る」という意味でも使われる点が異なる。"}, "disturb_creep_out": {"label": "不快にさせる・戸惑わせる", "note": "gross outは「気持ち悪くさせる」という嫌悪感を表す。weird outは「気味悪がらせる・戸惑わせる」という、奇妙さに対する反応を表す。"}, "vehicle_actions": {"label": "乗り物に関する動作", "note": "get inは車などに「乗り込む」こと。get offはバス・電車などから「降りる」こと。pull inは車が目的地に「入って止まる」ことを表す。"}, "clothing_wear": {"label": "着る・脱ぐ・試着", "note": "put onは「身につける」動作そのもの、take offは「脱ぐ」動作。try onは購入前などに「試着する」こと。dress upは「着飾る、正装する」という結果重視の表現。"}, "escape_run_away": {"label": "逃げる", "note": "run awayは家出や逃走など「その場から逃げ出す」こと。get awayは危険から逃げる場合にも、休暇で「日常から離れる」場合にも使う。"}, "enter_various": {"label": "入る", "note": "come inは自然に「入ってくる」こと。get intoは物理的に中に入る、または比喩的に「夢中になる」こと。break intoは許可なく「押し入る」こと。get in*2は組織・学校に「入る、合格する」こと。buzz inは解錠して人を「中に入れてあげる」こと。"}, "home_or_out": {"label": "家にいる・外出する", "note": "stay inは「家にいて外出しない」こと。go outは「外出する」こと。stay outは「外にいて（夜遅くまで）帰らない」こと。"}, "undertake_continue_work": {"label": "引き受ける・続ける・取り組む", "note": "take onは新しい仕事や責任を「引き受ける」こと。hold downは今の仕事を「維持し続ける」こと。keep onは「〜し続ける」という継続そのもの。take upは新しいことを「始める」こと。work onやget on withは実際に「取り組む、進める」という作業寄りの表現。"}, "give_up_in": {"label": "あきらめる・妥協する", "note": "give upは目標や努力を完全に「あきらめる」こと。give inは相手の要求などに「屈する」こと。back offは対立や要求から「引き下がる」こと。settle forは不満は残るが「妥協して受け入れる」こと。"}, "catch_up_behind": {"label": "遅れる・追いつく", "note": "keep upは「遅れずについていく」こと。get behindは「遅れをとる」こと。catch upは遅れた状態から「追いつく」こと。"}, "put_up_senses": {"label": "put upの意味の違い", "note": "put upは看板やテントなどを「掲げる、建てる」こと。put up*2は人を自宅に「泊める」という意味で使われる。"}, "go_down_senses": {"label": "go downの意味の違い", "note": "go downは物理的に「下がる」、日が「沈む」という意味。go down*2はシステムが「停止する」、または記録に「残る」という意味で使われる。"}, "imperative_expr": {"label": "強い命令表現", "note": "shut upは「黙れ」という強い命令。listen upは「よく聞け、注目しろ」という注意喚起の命令。どちらも口語的で直接的な言い方。"}, "skim_review": {"label": "ざっと目を通す", "note": "go throughは資料などに「一通り目を通す」こと（つらい経験を「経る」の意味もある）。look throughはより「ざっと」目を通すニュアンス。"}, "put_down_senses": {"label": "put downの意味の違い", "note": "put downは物理的に「下に置く」こと。put down*2は人を「けなす、こきおろす」という比喩的な意味。"}, "get_up_stand_up": {"label": "起きる・立ち上がる", "note": "get upは寝ている状態から「起きる」こと（立ち上がる意味もある）。stand upは座っていた状態から「立ち上がる」こと。"}, "stand_out_show_off": {"label": "目立つ・見せびらかす", "note": "stand outは自然と「目立つ、際立つ」こと。show offはわざと「見せびらかす」という、やや否定的なニュアンスを持つ。"}, "relationship_harmony": {"label": "仲良くやる・一緒にいる", "note": "get alongは人と「仲良くやる、うまくやっていく」こと。stay togetherは「一緒にいる、離れずにいる」という状態そのものを表す。"}, "scold_yell": {"label": "叱る・怒鳴る", "note": "tell offは「叱る、きつく注意する」こと。go off onは感情的に「怒鳴りつける」という、より激しいニュアンス。"}, "reflect_step_back": {"label": "振り返る・一歩引く", "note": "look back onは過去を「振り返る」こと。step backは一歩引いて「冷静に考える」こと。sit backはゆったり座る、または「静観する」ことを表す。"}, "break_malfunction": {"label": "壊れる・故障する", "note": "give out*2は機械などが「壊れる、尽きる」こと。break downは「故障する」こと、または人が感情的に「取り乱す」こと。wear outは使い込んで「すり減る」こと、または人を「疲れ果てさせる」こと。"}, "pay_related": {"label": "支払う", "note": "pay forは代金を「支払う、負担する」こと。pay offは借金などを「完済する」こと。"}, "come_around_senses": {"label": "come aroundの意味の違い", "note": "come aroundは「立ち寄る」こと、または考えを変えて「同意する」こと。come around*2は気絶した状態から「意識を取り戻す」という意味。"}, "break_up_apart": {"label": "壊れる・別れる", "note": "break upは関係が「別れる」こと、または物事が「解散する」こと。fall apartはより物理的・比喩的に「ばらばらになる、崩壊する」こと。"}, "bring_up_senses": {"label": "bring upの意味の違い", "note": "bring upは話題を「持ち出す」こと。bring up*2は子どもを「育てる、養育する」という意味。"}, "take_out_senses": {"label": "take outの意味の違い", "note": "take outは物を「取り出す、持ち出す」こと。take out*2は保険やローンを「契約する」という意味で使われる。"}, "reveal_secret": {"label": "秘密を漏らす", "note": "give awayは物を「ただであげる」こと、または秘密を「漏らす」こと。let outは情報などを「外に漏らす」こと。let onは秘密をほのめかす、そぶりを「見せる」こと。"}, "get_to_senses": {"label": "get toの意味の違い", "note": "get toは場所に「到着する」こと。get to*2は「〜する機会を得る」こと。get to*3は人を「悩ませる、こたえる」という意味で使われる。"}, "pick_up_senses": {"label": "pick upの意味の違い", "note": "pick upは物を「拾い上げる」こと、または車で人を「迎えに行く」こと。pick up*2は技能や言語を自然に「身につける」こと。pick up*3は体調や状況が「回復する、勢いを増す」こと。pick up*4は電話に「出る」こと。"}, "make_up_senses": {"label": "make upの意味の違い", "note": "make upは話を「でっちあげる」こと。make up*2はけんかの後に「仲直りする」こと。make up*3は不足分を「埋め合わせる」こと。make up*4は全体を「構成する、占める」という意味。"}, "put_out_senses": {"label": "put outの意味の違い", "note": "put outは火や明かりを「消す」こと。put out*2は物を「外に出す」こと。put out*3は人に「迷惑をかける、手間をかけさせる」という意味。"}, "keep_in_out": {"label": "中に入れる・締め出す", "note": "keep outは人を「立ち入らせない、締め出す」こと。keep inは逆に、人や物を「中にとどめておく」こと。"}, "stand_for_senses": {"label": "stand forの意味の違い", "note": "stand forは略語が「〜を表す」こと。stand for*2は好ましくない状況などを「容認する、我慢する」という意味。"}, "open_up_senses": {"label": "open upの意味の違い", "note": "open upは物理的に「開ける」こと、または店を「開設する」こと。open up*2は人が心を開いて「打ち明け話をする」という意味。"}, "bully_mistreat": {"label": "いじめる・乱暴に扱う", "note": "pick onは特定の人を「いじめる、目の敵にする」こと。rough upはより直接的・身体的に「手荒に扱う、暴行する」こと。"}, "turn_direction": {"label": "向きを変える", "note": "turn aroundは「向きを変える」こと、または業績などを「好転させる」こと。turn backは来た道を「引き返す」こと。"}, "bring_in_out": {"label": "導入する・世に出す", "note": "bring inは新しい制度や人を「導入する、呼び込む」こと。bring outは製品やアイデアなどを「世に出す」こと、または人の性質を「引き出す」こと。"}, "exit_leave_briefly": {"label": "抜け出す・少し席を外す", "note": "get outはその場から「出る、抜け出す」こと。step outは「少しの間、席を外す」という短時間のニュアンス。"}, "pull_out_away": {"label": "離れる・撤退する", "note": "pull outは計画や場所から「撤退する」こと、または物を「引き抜く」こと。pull awayは物理的に「離れていく」こと。"}, "cheer_encourage": {"label": "応援する・励ます", "note": "cheer upは落ち込んでいる人を「元気づける」こと。cheer onは声を出して「応援する」こと。get behind*2は人や案を「支持する、後押しする」こと。"}, "take_down_senses": {"label": "take downの意味の違い", "note": "take down*2は建物などを「取り壊す、撤去する」こと。take down*3は相手を「やり込める、打ち負かす」という意味。"}, "hold_out_off": {"label": "持ちこたえる・食い止める", "note": "hold outは苦しい状況で「持ちこたえる」こと。hold off*2は問題などを「食い止める、寄せつけない」こと。"}, "study_review": {"label": "復習する・予習する", "note": "brush upは以前学んだことを「復習する、磨き直す」こと。read up onはある話題について事前に「読み込む、調べる」こと。"}, "oppose_resist": {"label": "抵抗する・立ち向かう", "note": "push backは要求や意見に「反発する、難色を示す」こと。stand up toは困難や相手に「立ち向かう、耐える」こと。"}, "elaborate_dig": {"label": "詳しく述べる・深く掘り下げる", "note": "go intoは話題について「詳しく述べる」こと。dig intoはより「深く掘り下げて調べる」というニュアンス。"}, "hold_in_senses": {"label": "hold inの意味の違い", "note": "hold inは感情などを「抑える」こと。hold in*2は熱や水などを「閉じ込める」という物理的な意味。"}, "gain_popularity": {"label": "人気が出る・急に伸びる", "note": "catch onは「人気が出る、広まる」こと。take off*2は離陸のイメージから転じて、売上や人気が「急伸する」こと。"}, "slack_off_group": {"label": "怠ける・ふざける", "note": "slack offは仕事などで「手を抜く、怠ける」こと。fool aroundは「ふざける、時間を無駄にする」こと。"}, "move_on_over": {"label": "気持ちを切り替える・立ち直る", "note": "move onは次の段階へ「気持ちを切り替える」こと。get overはつらい経験や別れから「立ち直る、克服する」こと。"}, "adapt_fit_in": {"label": "慣れる・なじむ", "note": "fit inは周囲に「なじむ、溶け込む」こと。settle inは新しい環境に「慣れる」という、時間をかけて馴染んでいくニュアンス。"}, "schedule_fit": {"label": "予定に入れる・都合をつける", "note": "fit in*2は忙しい予定の中に何かを「入れる、都合をつける」こと。squeeze inは限られた時間や隙間に「無理に詰め込む」という、より切迫したニュアンス。"}, "dive_jump_in": {"label": "勢いよく取りかかる・加わる", "note": "dive inは物事に「勢いよく取りかかる」こと。jump inは会話や活動に「途中から加わる、口を挟む」こと。"}, "cut_off_senses": {"label": "cut offの意味の違い", "note": "cut offは電気やガスなどを「遮断する、停止する」こと。cut off*2は人の話を「遮る」こと。cut off*3は関係や支援を「断つ」こと。"}, "cancel_stop": {"label": "中止する・中断する", "note": "break offは物事を「中断する、打ち切る」こと。call offは予定していたイベントなどを「中止する」こと。"}, "pretend_pass_off": {"label": "偽る・話を合わせる", "note": "pass offは何かを偽って「〜として通用させる」こと。make out*3は実際とは違うことを「〜であるかのように主張する」こと。play alongは話を合わせて「調子を合わせる」こと。"}, "dating_romance": {"label": "恋愛・交際", "note": "go out withは人と「付き合う」こと。come on toは「言い寄る」こと。ask outはデートに「誘う」こと。get back togetherは別れた関係で「よりを戻す」こと。"}, "contact_related": {"label": "連絡する・情報を伝える", "note": "hear fromは人から「連絡をもらう」こと。check in withは相手の状況を「確認する、連絡を取る」こと。fill in*2は不在の間の出来事を「伝える」こと。"}, "revenge_group": {"label": "仕返しする・八つ当たりする", "note": "get back atは相手に「仕返しをする」こと。take out onは自分の怒りやストレスを、関係ない人に「八つ当たりする」こと。"}, "comply_defy": {"label": "従う・逆らう", "note": "go along withは意見や方針に「同意する、従う」こと。go againstはそれに「反する、逆らう」こと。ちょうど反対の意味を持つペア。"}, "dining_location": {"label": "外食する・家で食べる", "note": "eat outは「外食する」こと。eat inは「家で食べる」、または店内で「食事をする」ことを表す。"}, "confirm_check": {"label": "確認する", "note": "check out*3は情報の「裏が取れる、確認が取れる」こと。run byは確認のために「（人に）意見を聞く」こと。"}, "mess_disrupt": {"label": "台無しにする・狂わせる", "note": "mess upは物事を「台無しにする、しくじる」こと。throw offは人の調子やペースを「狂わせる」こと。"}, "probe_sniff": {"label": "探る", "note": "feel outはやんわりと相手の反応を「探る」こと。sniff outはより積極的に何かを「嗅ぎつける、探り当てる」こと。"}, "discuss_thoroughly": {"label": "じっくり話し合う", "note": "talk overは物事について「じっくり話し合う」こと。hash outは意見の違いなどを「議論して詰める」こと。"}, "gradual_pace": {"label": "徐々に・ゆっくり", "note": "ease intoは新しいことに「徐々に慣らす、ゆっくり始める」こと。wind downは活動などが「徐々に終わる」こと、または「くつろぐ」こと。"}, "pull_up_senses": {"label": "pull upの意味の違い", "note": "pull up*2はデータや画面を「呼び出す」こと。pull up*3は成績や数値を「引き上げる」という意味。"}, "stick_persist": {"label": "固執する・居残る", "note": "stick toは決めたことを「守り続ける、固執する」こと。stick aroundはその場に「残る、居残る」こと。"}, "gradual_reduce": {"label": "少しずつ削る・減らす", "note": "chip away atは少しずつ物事を「削る、地道に取り組む」こと。narrow downは選択肢などを「絞り込む」こと。cut back onは量や頻度を「減らす、切り詰める」こと。"}, "hook_up_senses": {"label": "hook upの意味の違い", "note": "hook upは機器などを「接続する、つなぐ」こと。hook up withは人と「落ち合う、組む」という意味で使われる。"}, "socialize_catch_up": {"label": "近況を語り合う・一緒に過ごす", "note": "catch up*2は久しぶりに会った人と「近況を語り合う」こと。hang outは友人などと「ぶらぶら過ごす、一緒に時間を過ごす」こと。"}, "accept_take_up": {"label": "提案を受け入れる", "note": "take up*2は提案などを「受け入れる」こと、または問題を「取り上げる」こと。take up onは相手の申し出を「受ける」こと。"}, "spend_time_effort": {"label": "時間・労力を費やす", "note": "put inは時間や労力を「注ぐ」という、主体的・前向きな投資のニュアンス。eat upは時間や資源を「食う」という、意図せず消費されてしまう、やや否定的なニュアンス。"}};
